type staticNeoModelMapper map[string]string

type neoRoundTripFunc func(*http.Request) (*http.Response, error)

type neoTestOperation struct {
	name string
	done <-chan struct{}
}

func (f neoRoundTripFunc) RoundTrip(req *http.Request) (*http.Response, error) {
	return f(req)
}

func waitNeoTestOperations(t *testing.T, operations ...neoTestOperation) {
	t.Helper()
	for _, operation := range operations {
		select {
		case <-operation.done:
		case <-time.After(time.Second):
			t.Fatalf("%s did not stop during cleanup", operation.name)
		}
	}
}

func allowTestTemporaryProjectDirectories(t *testing.T) {
	t.Helper()
	previous := neoWebLocalTransientProjectDirectory
	neoWebLocalTransientProjectDirectory = func(string) bool { return false }
	t.Cleanup(func() { neoWebLocalTransientProjectDirectory = previous })
}

func (m staticNeoModelMapper) MapModel(requestedModel string) string {
	return m[requestedModel]
}

func (m staticNeoModelMapper) UpdateMappings([]config.AmpModelMapping) {}

type mutatingNeoSnapshotText struct {
	once    *sync.Once
	actor   *neoActor
	message neoMessage
}

func (m mutatingNeoSnapshotText) MarshalJSON() ([]byte, error) {
	m.once.Do(func() {
		m.actor.messages = append(m.actor.messages, m.message)
		m.actor.messageRevision++
		m.actor.measurements.revision++
	})
	return json.Marshal("initial")
}

func TestNeoRuntimeEnabledIsOptIn(t *testing.T) {
	if neoRuntimeEnabled(&config.Config{}) {
		t.Fatal("neo runtime should be disabled unless explicitly enabled")
	}

	enabled := true
	if !neoRuntimeEnabled(&config.Config{AmpCode: config.AmpCode{NeoLocalRuntime: config.AmpNeoLocalRuntime{Enabled: &enabled}}}) {
		t.Fatal("neo runtime should be enabled when configured")
	}
}

func TestNeoRuntimeSubagentInferHandlesProviderStopReasons(t *testing.T) {
	tests := []struct {
		name      string
		result    neoInferenceResult
		wantError bool
	}{
		{name: "normal text", result: neoInferenceResult{Text: "done", StopReason: "end_turn"}},
		{name: "truncated text", result: neoInferenceResult{Text: "partial", StopReason: "max_tokens"}, wantError: true},
		{name: "refusal", result: neoInferenceResult{Text: "no", StopReason: "refusal"}, wantError: true},
		{name: "complete tool", result: neoInferenceResult{StopReason: "max_tokens", ToolCalls: []neoToolCall{{ID: "TU-test", Name: "finder", Input: map[string]any{"query": "target"}}}}},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			rt := newNeoRuntime(&config.Config{})
			rt.inferStream = func(*neoRuntime, neoInferenceRequest, neoStreamCallback) (neoInferenceResult, error) {
				return tc.result, nil
			}

			result, err := rt.subagentInfer(neoInferenceRequest{}, nil)
			if (err != nil) != tc.wantError {
				t.Fatalf("subagentInfer error = %v, wantError %v", err, tc.wantError)
			}
			if !tc.wantError && !reflect.DeepEqual(result, tc.result) {
				t.Fatalf("subagentInfer result = %#v, want %#v", result, tc.result)
			}
		})
	}
}

func TestNeoRuntimeMetadataIncludesClientEndpoint(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})

	tests := []struct {
		name           string
		host           string
		forwardedProto string
		forwardedHost  string
		want           string
	}{
		{name: "public forwarded endpoint", host: "neo.aikins.test", forwardedProto: "https", forwardedHost: "neo.aikins.xyz", want: "https://neo.aikins.xyz"},
		{name: "localhost stays http", host: "127.0.0.1:8317", forwardedProto: "https", want: "http://127.0.0.1:8317"},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			req := httptest.NewRequest(http.MethodGet, "/metadata", nil)
			req.Host = tc.host
			if tc.forwardedProto != "" {
				req.Header.Set("X-Forwarded-Proto", tc.forwardedProto)
			}
			if tc.forwardedHost != "" {
				req.Header.Set("X-Forwarded-Host", tc.forwardedHost)
			}
			rec := httptest.NewRecorder()

			rt.handleHTTP(rec, req)

			if rec.Code != http.StatusOK {
				t.Fatalf("metadata status = %d, body=%s", rec.Code, rec.Body.String())
			}
			var response map[string]any
			if err := json.Unmarshal(rec.Body.Bytes(), &response); err != nil {
				t.Fatalf("metadata JSON error: %v", err)
			}
			if got := stringValue(response["clientEndpoint"]); got != tc.want {
				t.Fatalf("clientEndpoint = %q, want %q", got, tc.want)
			}
		})
	}
}

func TestNeoRuntimeStartRetriesUntilPortIsReleased(t *testing.T) {
	held, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("hold tcp port: %v", err)
	}
	port := held.Addr().(*net.TCPAddr).Port

	oldInterval := neoRuntimeBindRetryInterval
	oldTimeout := neoRuntimeBindRetryTimeout
	neoRuntimeBindRetryInterval = 10 * time.Millisecond
	neoRuntimeBindRetryTimeout = 750 * time.Millisecond
	t.Cleanup(func() {
		neoRuntimeBindRetryInterval = oldInterval
		neoRuntimeBindRetryTimeout = oldTimeout
	})

	released := make(chan struct{})
	go func() {
		time.Sleep(50 * time.Millisecond)
		_ = held.Close()
		close(released)
	}()

	rt := newNeoRuntime(&config.Config{AmpCode: config.AmpCode{NeoLocalRuntime: config.AmpNeoLocalRuntime{
		Host: "127.0.0.1",
		Port: port,
	}}})
	if err := rt.start(); err != nil {
		t.Fatalf("start runtime after delayed port release: %v", err)
	}
	t.Cleanup(func() {
		ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
		defer cancel()
		_ = rt.stop(ctx)
	})
	<-released

	resp, err := http.Get(fmt.Sprintf("http://127.0.0.1:%d/metadata", port))
	if err != nil {
		t.Fatalf("metadata after retry bind: %v", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("metadata status = %d, want 200", resp.StatusCode)
	}
}

func TestNeoRuntimeActorLifecycleHTTP(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})

	req := httptest.NewRequest(http.MethodPut, "/actors", strings.NewReader(`{"name":"thread-actor","key":"T-test"}`))
	rec := httptest.NewRecorder()
	rt.handleHTTP(rec, req)
	if rec.Code != http.StatusOK {
		t.Fatalf("PUT /actors status = %d, body=%s", rec.Code, rec.Body.String())
	}
	if !strings.Contains(rec.Body.String(), `"created":true`) {
		t.Fatalf("expected actor creation response, got %s", rec.Body.String())
	}

	req = httptest.NewRequest(http.MethodGet, "/actors?name=thread-actor&key=T-test", nil)
	rec = httptest.NewRecorder()
	rt.handleHTTP(rec, req)
	if rec.Code != http.StatusOK {
		t.Fatalf("GET /actors status = %d, body=%s", rec.Code, rec.Body.String())
	}
	if !strings.Contains(rec.Body.String(), `"key":"T-test"`) {
		t.Fatalf("expected actor lookup by name/key, got %s", rec.Body.String())
	}
}

func TestNeoRuntimeActorKVKeyHTTP(t *testing.T) {
	dir := t.TempDir()
	oldStoreDir := neoAmpDataDir
	neoAmpDataDir = func() string { return dir }
	t.Cleanup(func() { neoAmpDataDir = oldStoreDir })

	rt := newNeoRuntime(&config.Config{})
	actor, _ := rt.store.upsert(map[string]any{"name": "thread-actor", "key": "T-kv"}, true)
	path := "/actors/" + url.PathEscape(actor.id) + "/kv/keys/skills%2Fstate?namespace=default"

	req := httptest.NewRequest(http.MethodGet, path, nil)
	rec := httptest.NewRecorder()
	rt.handleHTTP(rec, req)
	if rec.Code != http.StatusOK {
		t.Fatalf("GET actor kv status = %d, body=%s", rec.Code, rec.Body.String())
	}
	var body map[string]any
	if err := json.Unmarshal(rec.Body.Bytes(), &body); err != nil {
		t.Fatalf("decode kv response: %v", err)
	}
	value, exists := body["value"]
	if !exists || value != nil {
		t.Fatalf("kv response = %#v, want explicit null value", body)
	}

	req = httptest.NewRequest(http.MethodPut, path, strings.NewReader(`{"value":{"enabled":true,"count":2}}`))
	rec = httptest.NewRecorder()
	rt.handleHTTP(rec, req)
	if rec.Code != http.StatusOK {
		t.Fatalf("PUT actor kv status = %d, body=%s", rec.Code, rec.Body.String())
	}

	req = httptest.NewRequest(http.MethodGet, path, nil)
	rec = httptest.NewRecorder()
	rt.handleHTTP(rec, req)
	if rec.Code != http.StatusOK {
		t.Fatalf("GET actor kv after set status = %d, body=%s", rec.Code, rec.Body.String())
	}
	body = map[string]any{}
	if err := json.Unmarshal(rec.Body.Bytes(), &body); err != nil {
		t.Fatalf("decode kv response after set: %v", err)
	}
	stored := mapValue(body["value"])
	if stored["enabled"] != true || numberFrom(stored["count"]) != 2 {
		t.Fatalf("stored kv response = %#v", body)
	}

	req = httptest.NewRequest(http.MethodDelete, path, nil)
	rec = httptest.NewRecorder()
	rt.handleHTTP(rec, req)
	if rec.Code != http.StatusOK {
		t.Fatalf("DELETE actor kv status = %d, body=%s", rec.Code, rec.Body.String())
	}
	req = httptest.NewRequest(http.MethodGet, path, nil)
	rec = httptest.NewRecorder()
	rt.handleHTTP(rec, req)
	body = map[string]any{}
	if err := json.Unmarshal(rec.Body.Bytes(), &body); err != nil {
		t.Fatalf("decode kv response after delete: %v", err)
	}
	if value, exists := body["value"]; !exists || value != nil {
		t.Fatalf("kv response after delete = %#v, want explicit null value", body)
	}
}

func TestNeoRuntimeStateAndMessagesHTTPAreReadOnly(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})
	actor, _ := rt.store.upsert(map[string]any{"name": "threadActor", "key": "T-read-only"}, true)

	for _, path := range []string{
		"/gateway/" + actor.id + "/request/state",
		"/gateway/" + actor.id + "/request/messages",
	} {
		req := httptest.NewRequest(http.MethodGet, path, nil)
		rec := httptest.NewRecorder()
		rt.handleHTTP(rec, req)
		if rec.Code != http.StatusOK {
			t.Fatalf("GET %s status = %d, body=%s", path, rec.Code, rec.Body.String())
		}

		req = httptest.NewRequest(http.MethodPost, path, strings.NewReader(`{}`))
		rec = httptest.NewRecorder()
		rt.handleHTTP(rec, req)
		if rec.Code != http.StatusNotFound {
			t.Fatalf("POST %s status = %d, want 404 not local compatibility handling", path, rec.Code)
		}
	}
}

func assertBinarySafeMessagesForTest(t *testing.T, thread map[string]any) {
	t.Helper()
	messages := arrayValue(thread["messages"])
	if messages == nil {
		t.Fatalf("messages = %#v, want binary-safe array", thread["messages"])
	}
	for _, raw := range messages {
		message := mapValue(raw)
		if len(message) == 0 {
			continue
		}
		if content := arrayValue(message["content"]); content == nil {
			t.Fatalf("message content = %#v, want binary-safe array for %#v", message["content"], message)
		}
		if stringValue(message["role"]) != "user" {
			continue
		}
		userState := mapValue(message["userState"])
		if userState == nil {
			t.Fatalf("userState = %#v, want binary-safe object", message["userState"])
		}
		if files := arrayValue(userState["currentlyVisibleFiles"]); files == nil {
			t.Fatalf("currentlyVisibleFiles = %#v, want binary-safe array", userState["currentlyVisibleFiles"])
		}
		if _, exists := userState["runningTerminalCommands"]; exists {
			t.Fatalf("runningTerminalCommands = %#v, want omitted when not an array", userState["runningTerminalCommands"])
		}
		if aggman := mapValue(userState["aggmanContext"]); len(aggman) > 0 {
			if _, exists := aggman["availableProjects"]; exists {
				t.Fatalf("aggmanContext.availableProjects = %#v, want omitted when not an array", aggman["availableProjects"])
			}
			if _, exists := aggman["recentUnreadThreads"]; exists {
				t.Fatalf("aggmanContext.recentUnreadThreads = %#v, want omitted when not an array", aggman["recentUnreadThreads"])
			}
		}
	}
}

func runNeoCompactionPlanForTest(t *testing.T, actor *neoActor, agentMode, reasoningEffort, parentToolCallID string, generation int) bool {
	t.Helper()
	return actor.maybeCompactBeforeInference(agentMode, reasoningEffort, parentToolCallID, generation, "")
}

func TestNeoRuntimeAutoCompactsLargeLocalHistory(t *testing.T) {
	dir := t.TempDir()
	oldStoreDir := neoAmpDataDir
	neoAmpDataDir = func() string { return dir }
	t.Cleanup(func() { neoAmpDataDir = oldStoreDir })

	calls := 0
	upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/api/provider/openai/v1/chat/completions" {
			t.Fatalf("unexpected compaction path %s", r.URL.Path)
		}
		calls++
		payload := readNeoJSON(r.Body)
		wantKeys := map[string]bool{
			"max_completion_tokens": true,
			"messages":              true,
			"model":                 true,
			"reasoning_effort":      true,
			"stream":                true,
		}
		if len(payload) != len(wantKeys) {
			t.Fatalf("compaction payload keys = %v, want only [max_completion_tokens messages model reasoning_effort stream]", sortedMapKeys(payload))
		}
		for key := range wantKeys {
			if _, ok := payload[key]; !ok {
				t.Fatalf("compaction payload missing key %q: %v", key, sortedMapKeys(payload))
			}
		}
		if payload["model"] != "gpt-5.4" {
			t.Fatalf("compaction model = %#v, want gpt-5.4", payload["model"])
		}
		if payload["stream"] != false {
			t.Fatalf("compaction stream = %#v, want false", payload["stream"])
		}
		if numberFrom(payload["max_completion_tokens"]) != neoCompactionMaxOutputTokens {
			t.Fatalf("compaction max_completion_tokens = %#v, want %d", payload["max_completion_tokens"], neoCompactionMaxOutputTokens)
		}
		if payload["reasoning_effort"] != defaultNeoCompactionReasoning {
			t.Fatalf("compaction reasoning_effort = %#v, want %s", payload["reasoning_effort"], defaultNeoCompactionReasoning)
		}
		if _, ok := payload["tools"]; ok {
			t.Fatalf("compaction payload should omit tools: %#v", payload["tools"])
		}
		if _, ok := payload["tool_choice"]; ok {
			t.Fatalf("compaction payload should omit tool_choice: %#v", payload["tool_choice"])
		}
		if _, ok := payload["temperature"]; ok {
			t.Fatalf("compaction payload should omit temperature: %#v", payload["temperature"])
		}
		messages := arrayValue(payload["messages"])
		renderedMessages := fmt.Sprint(messages)
		if len(messages) < 31 || !strings.Contains(renderedMessages, "continuation summary") || !strings.Contains(renderedMessages, "message 00") || !strings.Contains(renderedMessages, "message 29") {
			t.Fatalf("compaction prompt missing provider-shaped history: %#v", payload)
		}
		firstMessage := mapValue(messages[0])
		if firstMessage["role"] == "system" {
			t.Fatalf("first compaction message = %#v, want history without compaction-only system prompt", firstMessage)
		}
		for _, raw := range messages[:len(messages)-1] {
			if mapValue(raw)["role"] == "system" {
				t.Fatalf("compaction history should not include a compaction-only system prompt: %#v", messages)
			}
		}
		lastMessage := mapValue(messages[len(messages)-1])
		if lastMessage["role"] != "user" || lastMessage["content"] != neoCompactionPrompt() {
			t.Fatalf("last compaction message = %#v, want Amp continuation summary prompt", lastMessage)
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"choices":[{"message":{"content":"- preserved project goal\n- tests passed"}}]}`))
	}))
	t.Cleanup(upstream.Close)
	parsed, err := url.Parse(upstream.URL)
	if err != nil {
		t.Fatalf("parse upstream url: %v", err)
	}
	_, portString, err := net.SplitHostPort(parsed.Host)
	if err != nil {
		t.Fatalf("parse upstream host: %v", err)
	}
	port, err := strconv.Atoi(portString)
	if err != nil {
		t.Fatalf("parse upstream port: %v", err)
	}

	enabled := true
	rt := newNeoRuntime(&config.Config{
		Host: "127.0.0.1",
		Port: port,
		AmpCode: config.AmpCode{NeoLocalRuntime: config.AmpNeoLocalRuntime{
			Enabled:         &enabled,
			CompactionModel: "openai/gpt-5.4",
		}},
	})
	threadID := "T-auto-compact"
	actor := newNeoActor(rt, "actor-test", "threadActor", threadID, threadID, neoActorRecord("actor-test", "threadActor", threadID), nil)
	actor.settings["internal.model"] = "openai/local-small"
	actor.settings["internal.compactionThresholdPercent"] = 0
	longText := strings.Repeat("important context ", 300)
	actor.mu.Lock()
	for i := 0; i < 30; i++ {
		role := "user"
		if i%2 == 1 {
			role = "assistant"
		}
		actor.storeMessageLocked(neoMessage{ThreadID: threadID, MessageID: fmt.Sprintf("M-%022d", i), Role: role, Content: []any{map[string]any{"type": "text", "text": fmt.Sprintf("message %02d %s", i, longText)}}})
	}
	actor.currentInference = &neoInferenceInflight{messageID: "M-0000000000000000000029", agentMode: "smart", reasoningEffort: "medium"}
	actor.rebuildHistoryLocked()
	actor.mu.Unlock()

	actor.mu.Lock()
	actor.syncRunning = true
	actor.mu.Unlock()
	runNeoCompactionPlanForTest(t, actor, "smart", "medium", "", actor.generation)
	snapshot, ok := actor.threadSnapshot()
	if !ok {
		t.Fatalf("thread snapshot unavailable after compaction")
	}
	storedThread := neoCloudThread(snapshot)
	storedMessages := arrayValue(storedThread["messages"])
	summaryIndex := 30 - neoCompactionTailMessages
	if len(storedMessages) <= summaryIndex+1 {
		t.Fatalf("stored messages after compaction = %d, want at least %d", len(storedMessages), summaryIndex+2)
	}
	if !boolValue(mapValue(storedThread["currentInference"])["preflightCompactionChecked"]) {
		t.Fatalf("stored currentInference = %#v, want compaction checked marker", storedThread["currentInference"])
	}
	if got := stringValue(mapValue(storedMessages[summaryIndex])["role"]); got != "info" {
		t.Fatalf("stored summary role at cut boundary = %q, want info", got)
	}
	if got := stringValue(mapValue(storedMessages[summaryIndex+1])["protocolMessageID"]); got != "M-0000000000000000000022" {
		t.Fatalf("stored cut message after summary = %q, want M-0000000000000000000022", got)
	}
	actor.mu.Lock()
	actor.syncRunning = false
	actor.syncPending = false
	actor.mu.Unlock()
	waitForNeoActorSyncIdle(t, actor)

	actor.mu.Lock()
	if calls != 1 {
		actor.mu.Unlock()
		t.Fatalf("compaction calls = %d, want 1", calls)
	}
	if len(actor.messages) != 31 {
		actor.mu.Unlock()
		t.Fatalf("message count after compaction = %d, want preserved 30 messages plus summary", len(actor.messages))
	}
	if actor.messages[0].MessageID != "M-0000000000000000000000" {
		actor.mu.Unlock()
		t.Fatalf("old transcript prefix was removed: first message = %#v", actor.messages[0])
	}
	summaryMessage := actor.messages[summaryIndex]
	if summaryMessage.Role != "info" || stringValue(mapValue(summaryMessage.Content[0])["type"]) != "summary" {
		actor.mu.Unlock()
		t.Fatalf("summary message = %#v, want summary info at cut boundary", summaryMessage)
	}
	retained := actor.messages[summaryIndex+1]
	if retained.Role != "user" || retained.MessageID != "M-0000000000000000000022" {
		actor.mu.Unlock()
		t.Fatalf("retained cut message = %#v, want original cut message after summary", retained)
	}
	if !strings.Contains(stringValue(mapValue(mapValue(summaryMessage.Content[0])["summary"])["summary"]), "preserved project goal") {
		actor.mu.Unlock()
		t.Fatalf("summary message content = %#v", summaryMessage.Content)
	}
	if len(actor.compactionRecords) != 1 || stringValue(actor.compactionRecords[0]["cutMessageId"]) != "M-0000000000000000000022" {
		actor.mu.Unlock()
		t.Fatalf("compaction records = %#v", actor.compactionRecords)
	}
	if len(actor.history) == 0 || actor.history[0].Role != "user" || !strings.Contains(actor.history[0].Text, "preserved project goal") {
		actor.mu.Unlock()
		t.Fatalf("history after compaction = %#v", actor.history)
	}
	if !strings.Contains(fmt.Sprint(actor.history), "message 29") {
		actor.mu.Unlock()
		t.Fatalf("history after compaction lost retained tail messages: %#v", actor.history)
	}
	if strings.Contains(fmt.Sprint(actor.history), "message 00") {
		actor.mu.Unlock()
		t.Fatalf("history after compaction leaked pre-summary messages: %#v", actor.history)
	}
	actor.mu.Unlock()

	runNeoCompactionPlanForTest(t, actor, "smart", "medium", "", actor.generation)
	waitForNeoActorSyncIdle(t, actor)

	actor.mu.Lock()
	defer actor.mu.Unlock()
	if calls != 1 {
		t.Fatalf("compaction calls after unchanged compacted window = %d, want 1", calls)
	}
}

func TestNeoRuntimePreflightIgnoresNestedSubagentMessagePressure(t *testing.T) {
	dir := t.TempDir()
	oldStoreDir := neoAmpDataDir
	neoAmpDataDir = func() string { return dir }
	t.Cleanup(func() { neoAmpDataDir = oldStoreDir })

	calls := 0
	upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		calls++
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"choices":[{"message":{"content":"unexpected summary"}}]}`))
	}))
	t.Cleanup(upstream.Close)
	parsed, err := url.Parse(upstream.URL)
	if err != nil {
		t.Fatalf("parse upstream url: %v", err)
	}
	_, portString, err := net.SplitHostPort(parsed.Host)
	if err != nil {
		t.Fatalf("parse upstream host: %v", err)
	}
	port, err := strconv.Atoi(portString)
	if err != nil {
		t.Fatalf("parse upstream port: %v", err)
	}

	enabled := true
	rt := newNeoRuntime(&config.Config{
		Host: "127.0.0.1",
		Port: port,
		AmpCode: config.AmpCode{NeoLocalRuntime: config.AmpNeoLocalRuntime{
			Enabled:         &enabled,
			CompactionModel: "openai/gpt-5.4",
		}},
	})
	threadID := "T-nested-pressure"
	actor := newNeoActor(rt, "actor-test", "threadActor", threadID, threadID, neoActorRecord("actor-test", "threadActor", threadID), nil)
	actor.settings["internal.compactionThresholdPercent"] = 0
	longNested := strings.Repeat("hidden read_thread observation ", 4000)
	actor.mu.Lock()
	for i := 0; i < 4; i++ {
		role := "user"
		if i%2 == 1 {
			role = "assistant"
		}
		actor.storeMessageLocked(neoMessage{ThreadID: threadID, MessageID: fmt.Sprintf("M-root-%019d", i), Role: role, Content: []any{map[string]any{"type": "text", "text": fmt.Sprintf("visible root message %02d", i)}}})
	}
	for i := 0; i < 40; i++ {
		actor.storeMessageLocked(neoMessage{ThreadID: threadID, MessageID: fmt.Sprintf("M-child-%018d", i), Role: "user", ParentToolUseID: "TU-read", Content: []any{map[string]any{"type": "text", "text": fmt.Sprintf("child message %02d %s", i, longNested)}}})
	}
	rootMessages, _ := neoCompactionSourceMessages(actor.messages, "")
	if len(rootMessages) != 4 {
		actor.mu.Unlock()
		t.Fatalf("root messages = %d, want 4", len(rootMessages))
	}
	if !neoCompactionShouldRun(actor.messages, 1, 0) {
		actor.mu.Unlock()
		t.Fatal("unscoped messages should demonstrate pre-change compaction pressure")
	}
	if neoCompactionShouldRun(rootMessages, 1, 0) {
		actor.mu.Unlock()
		t.Fatal("root-scoped messages should stay below minimum safe compaction count")
	}
	actor.currentInference = &neoInferenceInflight{messageID: "M-current", agentMode: "smart", reasoningEffort: "medium"}
	actor.rebuildHistoryLocked()
	generation := actor.generation
	actor.mu.Unlock()

	if actor.maybeCompactBeforeInference("smart", "medium", "", generation, "M-current") {
		t.Fatal("nested child pressure triggered root compaction")
	}
	if calls != 0 {
		t.Fatalf("compaction calls = %d, want 0", calls)
	}
}

func TestNeoRuntimeEmptyCompactionSummarySuppressesImmediateRetry(t *testing.T) {
	dir := t.TempDir()
	oldStoreDir := neoAmpDataDir
	neoAmpDataDir = func() string { return dir }
	t.Cleanup(func() { neoAmpDataDir = oldStoreDir })

	calls := 0
	upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		calls++
		if r.URL.Path != "/api/provider/openai/v1/chat/completions" {
			t.Fatalf("unexpected compaction path %s", r.URL.Path)
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"choices":[{"message":{"content":""}}]}`))
	}))
	t.Cleanup(upstream.Close)
	parsed, err := url.Parse(upstream.URL)
	if err != nil {
		t.Fatalf("parse upstream url: %v", err)
	}
	_, portString, err := net.SplitHostPort(parsed.Host)
	if err != nil {
		t.Fatalf("parse upstream host: %v", err)
	}
	port, err := strconv.Atoi(portString)
	if err != nil {
		t.Fatalf("parse upstream port: %v", err)
	}

	enabled := true
	rt := newNeoRuntime(&config.Config{
		Host: "127.0.0.1",
		Port: port,
		AmpCode: config.AmpCode{NeoLocalRuntime: config.AmpNeoLocalRuntime{
			Enabled:         &enabled,
			CompactionModel: "openai/gpt-5.4",
		}},
	})
	threadID := "T-empty-compact"
	actor := newNeoActor(rt, "actor-test", "threadActor", threadID, threadID, neoActorRecord("actor-test", "threadActor", threadID), nil)
	actor.settings["internal.compactionThresholdPercent"] = 0
	longText := strings.Repeat("empty compaction context ", 300)
	actor.mu.Lock()
	for i := 0; i < 30; i++ {
		role := "user"
		if i%2 == 1 {
			role = "assistant"
		}
		actor.storeMessageLocked(neoMessage{ThreadID: threadID, MessageID: fmt.Sprintf("M-%022d", i), Role: role, Content: []any{map[string]any{"type": "text", "text": fmt.Sprintf("message %02d %s", i, longText)}}})
	}
	actor.agentState = "working"
	actor.currentInference = &neoInferenceInflight{messageID: "M-current", agentMode: "smart", reasoningEffort: "medium"}
	actor.rebuildHistoryLocked()
	generation := actor.generation
	actor.mu.Unlock()

	if actor.maybeCompactBeforeInference("smart", "medium", "", generation, "M-current") {
		t.Fatal("empty compaction summary reported success")
	}
	if calls != 1 {
		t.Fatalf("compaction calls = %d, want first attempt", calls)
	}
	actor.mu.Lock()
	if actor.compacting {
		t.Fatal("actor remained compacting after empty summary")
	}
	if len(actor.compactionRecords) != 0 {
		t.Fatalf("compactionRecords = %#v, want none", actor.compactionRecords)
	}
	if actor.currentInference == nil || !actor.currentInference.preflightCompactionChecked {
		t.Fatalf("currentInference = %#v, want checked after empty summary", actor.currentInference)
	}
	retryAfter := actor.compactionRetryAfterLen
	actor.currentInference = &neoInferenceInflight{messageID: "M-current-2", agentMode: "smart", reasoningEffort: "medium"}
	actor.mu.Unlock()

	if actor.maybeCompactBeforeInference("smart", "medium", "", generation, "M-current-2") {
		t.Fatal("retry guard reported compaction success")
	}
	if calls != 1 {
		t.Fatalf("compaction calls = %d, want immediate retry suppressed", calls)
	}
	actor.mu.Lock()
	if retryAfter <= len(actor.messages) {
		t.Fatalf("retryAfterLen = %d, messages = %d, want retry delayed", retryAfter, len(actor.messages))
	}
	if actor.currentInference == nil || !actor.currentInference.preflightCompactionChecked {
		t.Fatalf("currentInference after suppressed retry = %#v, want checked", actor.currentInference)
	}
	for i := len(actor.messages); i < retryAfter; i++ {
		role := "user"
		if i%2 == 1 {
			role = "assistant"
		}
		actor.storeMessageLocked(neoMessage{ThreadID: threadID, MessageID: fmt.Sprintf("M-%022d", i), Role: role, Content: []any{map[string]any{"type": "text", "text": fmt.Sprintf("new message %02d %s", i, longText)}}})
	}
	actor.currentInference = &neoInferenceInflight{messageID: "M-current-3", agentMode: "smart", reasoningEffort: "medium"}
	generation = actor.generation
	actor.mu.Unlock()

	if actor.maybeCompactBeforeInference("smart", "medium", "", generation, "M-current-3") {
		t.Fatal("empty compaction summary after retry boundary reported success")
	}
	if calls != 2 {
		t.Fatalf("compaction calls = %d, want retry after source length reaches %d", calls, retryAfter)
	}
}

