	now := time.Now()
	actor.mu.Lock()
	actor.lastUsed = now.Add(-time.Hour)
	actor.messages = []neoMessage{{ThreadID: threadID, MessageID: "M-deferred-inference", Role: "user", Content: []any{map[string]any{"type": "text", "text": "keep active state"}}, Seq: 1}}
