func TestNeoRuntimeWebLocalInferenceBootstrapExecutor(t *testing.T) {
	dir := t.TempDir()
	missingCommand := filepath.Join(dir, "missing-amp")
	enabled := true
	rt := newNeoRuntime(&config.Config{AmpCode: config.AmpCode{
		NeoLocalRuntime: config.AmpNeoLocalRuntime{
			Enabled:           &enabled,
			ForceThreadActors: true,
			ExecutorCommand:   missingCommand,
		},
		WebLocalInference: config.AmpWebLocalInference{
			Enabled:        true,
			AllowedOrigins: []string{"https://ampcode.com"},
		},
	}})
	server := httptest.NewServer(http.HandlerFunc(rt.handleHTTP))
	t.Cleanup(server.Close)

	threadID := "T-11111111-1111-4111-8111-111111111111"
	dialer := websocket.Dialer{Subprotocols: []string{"rivet", "rivet_encoding.4", "rivet_skip_ready_wait"}}
	wsURL := "ws" + strings.TrimPrefix(server.URL, "http") + "/gateway/threadActor/websocket/?rvt-method=get&rvt-key=" + threadID + "&rvt-skip-ready-wait=true&cliproxy-bootstrap-executor=true"
	headers := http.Header{
		"Origin":                      []string{"https://ampcode.com"},
		neoInternalClientAPIKeyHeader: []string{"local-key"},
	}
	conn, resp, err := dialer.Dial(wsURL, headers)
	if err != nil {
		status := 0
		if resp != nil {
			status = resp.StatusCode
		}
		t.Fatalf("gateway websocket dial failed status=%d err=%v", status, err)
	}
	defer conn.Close()

	waitForNeoRivetBareInit(t, conn, 2*time.Second)
	status := waitForNeoRivetBareEventTypeWhere(t, conn, "executor_status", 2*time.Second, func(msg map[string]any) bool {
		return mapValue(msg["details"])["reasonCode"] == "spawn_failed"
	})
	if status["status"] != "failed" {
		t.Fatalf("executor status = %#v, want failed", status)
	}
	details := mapValue(status["details"])
	if details["reasonCode"] != "spawn_failed" {
		t.Fatalf("executor status details = %#v, want spawn_failed", details)
	}
	if actor := rt.store.lookupThreadActor(threadID); actor == nil {
		t.Fatal("web local inference bootstrap did not create thread actor")
	}
}

func TestNeoWebLocalInferenceSocketRequiresOptInOrigin(t *testing.T) {
	enabled := true
	rt := newNeoRuntime(&config.Config{AmpCode: config.AmpCode{
		NeoLocalRuntime: config.AmpNeoLocalRuntime{
			Enabled:           &enabled,
			ForceThreadActors: true,
		},
		WebLocalInference: config.AmpWebLocalInference{
			Enabled:        true,
			AllowedOrigins: []string{"https://ampcode.com"},
			BaseURL:        "https://aikinss-macbook-pro.taila39f5b.ts.net",
		},
	}})
	threadID := "T-99999999-9999-4999-8999-999999999999"
	actor, _ := rt.store.upsert(map[string]any{
		"name": "threadActor",
		"key":  threadID,
		"input": map[string]any{
			"threadId": threadID,
		},
	}, true)

	req := httptest.NewRequest(http.MethodGet, "/gateway/threadActor/websocket/?rvt-method=get&rvt-key="+threadID+"&cliproxy-bootstrap-executor=true", nil)
	if neoWebLocalInferenceSocketRequested(req, actor) {
		t.Fatal("query flag without Origin unexpectedly enabled web local inference")
	}
	req.Header.Set("Origin", "https://example.com")
	if neoWebLocalInferenceSocketRequested(req, actor) {
		t.Fatal("untrusted Origin unexpectedly enabled web local inference")
	}
	req.Header.Set("Origin", "https://ampcode.com")
	if neoWebLocalInferenceSocketRequested(req, actor) {
		t.Fatal("trusted Origin without internal client key unexpectedly enabled web local inference")
	}
	req.Header.Set(neoInternalClientAPIKeyHeader, "local-key")
	if !neoWebLocalInferenceSocketRequested(req, actor) {
		t.Fatal("trusted Origin did not enable web local inference")
	}
	req.Header.Set("Origin", "https://aikinss-macbook-pro.taila39f5b.ts.net")
	if !neoWebLocalInferenceSocketRequested(req, actor) {
		t.Fatal("configured base URL Origin did not enable web local inference")
	}
	req.Header.Set("Origin", "https://example.com")
	query := req.URL.Query()
	query.Set("cliproxy-client", "amp-web-local-inference")
	req.URL.RawQuery = query.Encode()
	if !neoWebLocalInferenceSocketRequested(req, actor) {
		t.Fatal("authenticated userscript marker did not enable observer protection")
	}

	disabledRuntime := newNeoRuntime(&config.Config{AmpCode: config.AmpCode{
		NeoLocalRuntime: config.AmpNeoLocalRuntime{
			Enabled:           &enabled,
			ForceThreadActors: true,
		},
	}})
	disabledActor, _ := disabledRuntime.store.upsert(map[string]any{
		"name": "threadActor",
		"key":  threadID,
		"input": map[string]any{
			"threadId": threadID,
		},
	}, true)
	if neoWebLocalInferenceSocketRequested(req, disabledActor) {
		t.Fatal("disabled web local inference unexpectedly accepted query and Origin")
	}
}

func TestNeoApplyWebLocalInferenceBootstrapQueryAppliesThreadDefaults(t *testing.T) {
	enabled := true
	rt := newNeoRuntime(&config.Config{AmpCode: config.AmpCode{
		NeoLocalRuntime: config.AmpNeoLocalRuntime{
			Enabled:           &enabled,
			ForceThreadActors: true,
		},
		WebLocalInference: config.AmpWebLocalInference{
			Enabled:        true,
			AllowedOrigins: []string{"https://ampcode.com"},
		},
	}})
	threadID := "T-12121212-1212-4121-8121-121212121212"
	actor, _ := rt.store.upsert(map[string]any{
		"name": "threadActor",
		"key":  threadID,
		"input": map[string]any{
			"threadId": threadID,
		},
	}, true)
	workingDirectory := t.TempDir()
	expectedWorkingDirectory := neoExistingDirectory(workingDirectory)
	rawURL := "/gateway/threadActor/websocket/?rvt-method=get&rvt-key=" + threadID +
		"&cliproxy-bootstrap-executor=true" +
		"&cliproxy-working-directory=" + url.QueryEscape(workingDirectory) +
		"&cliproxy-agent-mode=deep" +
		"&cliproxy-reasoning-effort=xhigh"
	req := httptest.NewRequest(http.MethodGet, rawURL, nil)
	req.Header.Set("Origin", "https://ampcode.com")
	req.Header.Set(neoInternalClientAPIKeyHeader, "local-key")

	neoApplyWebLocalInferenceBootstrapQuery(req, actor)
	actor.updateAgentModeFromBinary(map[string]any{"mode": "high"})
	reconnectedReq := httptest.NewRequest(http.MethodGet, "/gateway/threadActor/websocket/?rvt-method=get&rvt-key="+threadID+
		"&cliproxy-bootstrap-executor=true&cliproxy-agent-mode=high&cliproxy-reasoning-effort=xhigh", nil)
	reconnectedReq.Header.Set("Origin", "https://ampcode.com")
	reconnectedReq.Header.Set(neoInternalClientAPIKeyHeader, "local-key")
	neoApplyWebLocalInferenceBootstrapQuery(reconnectedReq, actor)

	actor.mu.Lock()
	defer actor.mu.Unlock()
	if got := stringValue(actor.environment["workingDirectory"]); got != expectedWorkingDirectory {
		t.Fatalf("workingDirectory = %q, want %q", got, expectedWorkingDirectory)
	}
	if got := stringValue(actor.environment["workspaceRoot"]); got != expectedWorkingDirectory {
		t.Fatalf("workspaceRoot = %q, want %q", got, expectedWorkingDirectory)
	}
	if actor.currentAgentMode != "deep" {
		t.Fatalf("currentAgentMode = %q, want deep", actor.currentAgentMode)
	}
	if actor.currentReasoningEffort != "xhigh" {
		t.Fatalf("currentReasoningEffort = %q, want xhigh", actor.currentReasoningEffort)
	}
	if got := stringValue(actor.settings["agentMode"]); got != "deep" {
		t.Fatalf("settings agentMode = %q, want deep", got)
	}
	if got := stringValue(actor.settings["reasoning.effort"]); got != "xhigh" {
		t.Fatalf("settings reasoning.effort = %q, want xhigh", got)
	}
	if actor.bootstrapExecutorType != "local-client" {
		t.Fatalf("bootstrapExecutorType = %q, want local-client", actor.bootstrapExecutorType)
	}
}

