func TestNeoApplyWebLocalInferenceBootstrapQueryReplacesProvisionalModeWithPlugin(t *testing.T) {
	useTempNeoThreadStore(t)
	dir := t.TempDir()
	oldPluginsDir := neoAmpUserPluginsDir
	neoAmpUserPluginsDir = func() string { return dir }
	t.Cleanup(func() { neoAmpUserPluginsDir = oldPluginsDir })
	source := "// @amp-agent-mode {\"key\":\"deep-red\",\"label\":\"Deep Red\"}\n" +
		"const PROMPT = `BOOTSTRAP_ENI_INSTRUCTIONS`;\n" +
		"export default function plugin(amp) {\n" +
		"  const agent = amp.createAgent({ name: 'eni', model: 'anthropic/kimi-k3', instructions: PROMPT, tools: 'all', reasoningEffort: 'max' });\n" +
		"  amp.registerAgentMode({ key: 'deep-red', label: 'Deep Red', agent: agent.definition });\n" +
		"}\n"
	if err := os.WriteFile(filepath.Join(dir, "deep-red.ts"), []byte(source), 0o600); err != nil {
		t.Fatal(err)
	}

	enabled := true
	rt := newNeoRuntime(&config.Config{AmpCode: config.AmpCode{
		NeoLocalRuntime: config.AmpNeoLocalRuntime{
			Enabled:           &enabled,
			ForceThreadActors: true,
			ModeModelRoutes:   map[string]config.ModelRouteList{"deep-red": {"moonshotai/kimi-k3"}},
		},
		WebLocalInference: config.AmpWebLocalInference{
			Enabled:        true,
			AllowedOrigins: []string{"https://ampcode.com"},
		},
	}})
	threadID := "T-12121212-1212-4121-8121-121212121217"
	actor := rt.store.ensureThreadActor(threadID)
	actor.mu.Lock()
	actor.settings["agentMode"] = "high"
	actor.settings["reasoning.effort"] = "xhigh"
	actor.currentAgentMode = "high"
	actor.currentReasoningEffort = "xhigh"
	actor.meta["cliProxyAPILocalNeo"] = true
	actor.meta["cliProxyAPIWebLocalShell"] = true
	actor.meta["agentMode"] = "high"
	actor.mu.Unlock()

	req := httptest.NewRequest(http.MethodGet, "/gateway/threadActor/websocket/?rvt-method=get&rvt-key="+threadID+
		"&cliproxy-bootstrap-executor=true&cliproxy-agent-mode=deep-red&cliproxy-reasoning-effort=max", nil)
	req.Header.Set("Origin", "https://ampcode.com")
	req.Header.Set(neoInternalClientAPIKeyHeader, "local-key")
	neoApplyWebLocalInferenceBootstrapQuery(req, actor)
	actor.updateAgentModeFromBinary(map[string]any{"mode": "high"})
	staleReq := httptest.NewRequest(http.MethodGet, "/gateway/threadActor/websocket/?rvt-method=get&rvt-key="+threadID+
		"&cliproxy-bootstrap-executor=true&cliproxy-agent-mode=high&cliproxy-reasoning-effort=xhigh", nil)
	staleReq.Header.Set("Origin", "https://ampcode.com")
	staleReq.Header.Set(neoInternalClientAPIKeyHeader, "local-key")
	neoApplyWebLocalInferenceBootstrapQuery(staleReq, actor)
	actor.updateReasoningEffortFromBinary(map[string]any{"effort": "low"})

	actor.mu.Lock()
	mode := actor.currentAgentMode
	effort := actor.currentReasoningEffort
	settings := cloneMap(actor.settings)
	meta := cloneMap(actor.meta)
	request := actor.inferenceRequestLocked(mode, effort, "")
	actor.mu.Unlock()
	if mode != "deep-red" || effort != "max" {
		t.Fatalf("actor mode/effort = %q/%q, want deep-red/max", mode, effort)
	}
	if settings[neoCustomAgentModeSetting] != "deep-red" || settings[neoCustomAgentConfigKeySetting] != "eni" || settings[neoCustomAgentModelSetting] != "anthropic/kimi-k3" || settings[neoCustomAgentInstructionsSetting] != "BOOTSTRAP_ENI_INSTRUCTIONS" || settings[neoCustomAgentToolsSetting] != "all" {
		t.Fatalf("custom agent settings = %#v", settings)
	}
	if meta["agentMode"] != "deep-red" || meta["reasoningEffort"] != "max" || meta["pluginName"] != "deep-red" {
		t.Fatalf("plugin metadata = %#v", meta)
	}
	route := selectNeoModelRouteWithConfig(rt, request.AgentMode, request.Settings)
	if route.Provider != "moonshotai" || route.Model != "kimi-k3" {
		t.Fatalf("route = %#v, want moonshotai/kimi-k3", route)
	}
	waitForNeoActorSyncIdle(t, actor)
	persisted, ok := loadNeoThreadFromDir(threadID, rt.threadDir)
	if !ok {
		t.Fatal("bootstrapped plugin thread was not persisted")
	}
	persistedSettings := mapValue(persisted["settings"])
	if persistedSettings[neoCustomAgentModeSetting] != "deep-red" || persistedSettings[neoCustomAgentInstructionsSetting] != "BOOTSTRAP_ENI_INSTRUCTIONS" {
		t.Fatalf("persisted plugin settings = %#v", persistedSettings)
	}

	actor.mu.Lock()
	actor.messages = append(actor.messages, neoMessage{ThreadID: threadID, MessageID: "M-bootstrap-user", Role: "user", Content: []any{map[string]any{"type": "text", "text": "start"}}})
	actor.mu.Unlock()
	lockedReq := httptest.NewRequest(http.MethodGet, "/gateway/threadActor/websocket/?rvt-method=get&rvt-key="+threadID+
		"&cliproxy-bootstrap-executor=true&cliproxy-agent-mode=high&cliproxy-reasoning-effort=xhigh", nil)
	lockedReq.Header.Set("Origin", "https://ampcode.com")
	lockedReq.Header.Set(neoInternalClientAPIKeyHeader, "local-key")
	neoApplyWebLocalInferenceBootstrapQuery(lockedReq, actor)
	actor.updateAgentModeFromBinary(map[string]any{"mode": "high"})
	actor.mu.Lock()
	lockedMode := actor.currentAgentMode
	lockedEffort := actor.currentReasoningEffort
	lockedInstructions := stringValue(actor.settings[neoCustomAgentInstructionsSetting])
	actor.mu.Unlock()
	if lockedMode != "deep-red" || lockedEffort != "max" || lockedInstructions != "BOOTSTRAP_ENI_INSTRUCTIONS" {
		t.Fatalf("post-user bootstrap changed mode=%q effort=%q instructions=%q", lockedMode, lockedEffort, lockedInstructions)
	}

	actor.updateSettings(map[string]any{"agentMode": "smart"})
	actor.mu.Lock()
	builtInSettings := cloneMap(actor.settings)
	builtInMeta := cloneMap(actor.meta)
	actor.mu.Unlock()
	if builtInSettings[neoCustomAgentModeSetting] != nil || builtInMeta["pluginName"] != nil || builtInMeta["pluginPath"] != nil || builtInMeta["pluginRepositoryName"] != nil || builtInMeta["pluginScope"] != nil {
		t.Fatalf("built-in mode retained plugin state: settings=%#v meta=%#v", builtInSettings, builtInMeta)
	}
	if builtInMeta["agentMode"] != "smart" || builtInMeta["reasoningEffort"] != "high" {
		t.Fatalf("built-in metadata = %#v, want smart/high", builtInMeta)
	}
}

func TestNeoUpdateAgentModeFromBinaryInstallsPluginBeforeFirstUserTurn(t *testing.T) {
	useTempNeoThreadStore(t)
	dir := t.TempDir()
	oldPluginsDir := neoAmpUserPluginsDir
	neoAmpUserPluginsDir = func() string { return dir }
	t.Cleanup(func() { neoAmpUserPluginsDir = oldPluginsDir })
	source := "// @amp-agent-mode {\"key\":\"deep-red\",\"label\":\"Deep Red\"}\n" +
		"const PROMPT = `BINARY_ENI_INSTRUCTIONS`;\n" +
		"export default function plugin(amp) {\n" +
		"  const agent = amp.createAgent({ name: 'eni', model: 'anthropic/kimi-k3', instructions: PROMPT, tools: 'all', reasoningEffort: 'max' });\n" +
		"  amp.registerAgentMode({ key: 'deep-red', label: 'Deep Red', agent });\n" +
		"}\n"
	if err := os.WriteFile(filepath.Join(dir, "deep-red.ts"), []byte(source), 0o600); err != nil {
		t.Fatal(err)
	}

	rt := newNeoRuntime(&config.Config{})
	actor := rt.store.ensureThreadActor("T-12121212-1212-4121-8121-121212121218")
	actor.mu.Lock()
	actor.settings["agentMode"] = "high"
	actor.settings["reasoning.effort"] = "xhigh"
	actor.currentAgentMode = "high"
	actor.currentReasoningEffort = "xhigh"
	actor.mu.Unlock()
	actor.updateAgentModeFromBinary(map[string]any{"mode": "deep-red"})

	actor.mu.Lock()
	mode := actor.currentAgentMode
	effort := actor.currentReasoningEffort
	settings := cloneMap(actor.settings)
	actor.mu.Unlock()
	if mode != "deep-red" || effort != "max" || settings[neoCustomAgentModeSetting] != "deep-red" || settings[neoCustomAgentInstructionsSetting] != "BINARY_ENI_INSTRUCTIONS" {
		t.Fatalf("binary plugin mode=%q effort=%q settings=%#v", mode, effort, settings)
	}

	opaqueMode := "custom-0123456789abcdef"
	actor.mu.Lock()
	actor.settings["agentMode"] = opaqueMode
	actor.settings["reasoning.effort"] = "high"
	actor.settings[neoCustomAgentModeSetting] = opaqueMode
	actor.settings[neoCustomAgentModelSetting] = "anthropic/kimi-k3"
	actor.settings[neoCustomAgentInstructionsSetting] = "OPAQUE_ENI_INSTRUCTIONS"
	actor.currentAgentMode = opaqueMode
	actor.currentReasoningEffort = "high"
	actor.mu.Unlock()
	actor.updateAgentModeFromBinary(map[string]any{"mode": opaqueMode})
	actor.mu.Lock()
	opaqueCurrentMode := actor.currentAgentMode
	opaqueCurrentEffort := actor.currentReasoningEffort
	opaqueInstructions := stringValue(actor.settings[neoCustomAgentInstructionsSetting])
	actor.mu.Unlock()
	if opaqueCurrentMode != opaqueMode || opaqueCurrentEffort != "high" || opaqueInstructions != "OPAQUE_ENI_INSTRUCTIONS" {
		t.Fatalf("opaque custom mode=%q effort=%q instructions=%q", opaqueCurrentMode, opaqueCurrentEffort, opaqueInstructions)
	}
	waitForNeoActorSyncIdle(t, actor)
}

func TestNeoResolvedEnvironmentWorkspacePathsPrefersTaskTrees(t *testing.T) {
	root := t.TempDir()
	firstRepository := filepath.Join(root, "first")
	secondRepository := filepath.Join(root, "second")
	workingDirectory := filepath.Join(secondRepository, "internal", "api")
	for _, directory := range []string{firstRepository, workingDirectory} {
		if err := os.MkdirAll(directory, 0o700); err != nil {
			t.Fatalf("create directory %q: %v", directory, err)
		}
	}

	t.Run("stale explicit directory", func(t *testing.T) {
		environment := map[string]any{
			"workingDirectory": firstRepository,
			"workspaceRoot":    firstRepository,
			"trees":            []any{map[string]any{"uri": neoFileURLForDirectory(secondRepository)}},
		}
		work, workspace := neoResolvedEnvironmentWorkspacePaths(environment)
		if work != secondRepository || workspace != secondRepository {
			t.Fatalf("resolved workspace = work:%q root:%q, want %q", work, workspace, secondRepository)
		}
		normalized := neoCanonicalizeEnvironmentWorkspace(cloneMap(environment))
		if stringValue(normalized["workingDirectory"]) != secondRepository || stringValue(normalized["workspaceRoot"]) != secondRepository {
			t.Fatalf("normalized environment = %#v", normalized)
		}
		threadDirectory := neoWorkingDirectoryFromThread(map[string]any{
			"workingDirectory": firstRepository,
			"workspaceRoot":    firstRepository,
			"env":              map[string]any{"trees": []any{map[string]any{"uri": neoFileURLForDirectory(secondRepository)}}},
		})
		if expected := neoExistingDirectory(secondRepository); threadDirectory != expected {
			t.Fatalf("thread working directory = %q, want task tree %q", threadDirectory, expected)
		}
	})

	t.Run("valid nested directory", func(t *testing.T) {
		work, workspace := neoResolvedEnvironmentWorkspacePaths(map[string]any{
			"workingDirectory": workingDirectory,
			"workspaceRoot":    firstRepository,
			"trees": []any{
				map[string]any{"uri": neoFileURLForDirectory(firstRepository)},
				map[string]any{"uri": neoFileURLForDirectory(secondRepository)},
			},
		})
		if work != workingDirectory || workspace != secondRepository {
			t.Fatalf("resolved workspace = work:%q root:%q, want work:%q root:%q", work, workspace, workingDirectory, secondRepository)
		}
	})

	t.Run("no tree", func(t *testing.T) {
		work, workspace := neoResolvedEnvironmentWorkspacePaths(map[string]any{
			"workingDirectory": workingDirectory,
			"workspaceRoot":    secondRepository,
		})
		if work != workingDirectory || workspace != secondRepository {
			t.Fatalf("resolved workspace = work:%q root:%q, want explicit paths", work, workspace)
		}
	})
}

func TestNeoChangesFileOrderMatchesBinaryProtocol(t *testing.T) {
	section := neoChangesFileOrderSection{
		baseRevision:     "base",
		headRevision:     "worktree",
		includeUntracked: true,
	}
	entry := neoGitDiffRangeEntry{path: "a.go", changeType: "modified"}
	if got := neoChangesFileOrderDiffToken(section, entry, "diff"); got != "66cc0eb37aa77bb60750007f21fd28b24081701097d5a83fa0aac1767e2f86a2" {
		t.Fatalf("changes file order diff token = %q", got)
	}
	streamedHash := neoChangesFileOrderDiffHash(section, entry)
	streamed := &neoTrimTrailingNewlinesWriter{writer: streamedHash}
	if _, err := streamed.Write([]byte("di")); err != nil {
		t.Fatal(err)
	}
	if _, err := streamed.Write([]byte("ff\n\n")); err != nil {
		t.Fatal(err)
	}
	if got := fmt.Sprintf("%x", streamedHash.Sum(nil)); got != neoChangesFileOrderDiffToken(section, entry, "diff") {
		t.Fatalf("streamed changes file order diff token = %q", got)
	}
	repository := t.TempDir()
	run := func(args ...string) string {
		t.Helper()
		cmd := exec.Command("git", args...)
		cmd.Dir = repository
		output, err := cmd.CombinedOutput()
		if err != nil {
			t.Fatalf("git %v: %v\n%s", args, err, output)
		}
		return string(output)
	}
	run("init")
	run("config", "user.email", "test@example.test")
	run("config", "user.name", "Test User")
	run("config", "commit.gpgsign", "false")
	for _, name := range []string{"a.go", "main.go", "main_test.go", "z.go"} {
		if err := os.WriteFile(filepath.Join(repository, name), []byte("package initial\n"), 0o600); err != nil {
			t.Fatal(err)
		}
	}
	run("add", "a.go", "main.go", "main_test.go", "z.go")
	run("commit", "-m", "initial")
	head := strings.TrimSpace(run("rev-parse", "HEAD"))
	for _, name := range []string{"z.go", "a.go", "main.go", "main_test.go", "m.go"} {
		if err := os.WriteFile(filepath.Join(repository, name), []byte("package changed\n"), 0o600); err != nil {
			t.Fatal(err)
		}
	}

	request := map[string]any{
		"type":      "client_changes_file_order",
		"requestId": "changes-file-order-test",
		"sections": []any{map[string]any{
			"sectionID":        "working-tree",
			"diffHash":         "diff-hash",
			"baseRevision":     head,
			"headRevision":     "worktree",
			"includeUntracked": true,
		}},
	}
	requestID, sections, ok := normalizeNeoChangesFileOrderRequest(request)
	if !ok || requestID != "changes-file-order-test" || len(sections) != 1 {
		t.Fatalf("normalized changes order request id=%q sections=%#v ok=%v", requestID, sections, ok)
	}
	paths, diffHash, err := neoChangesFileOrderSnapshot(context.Background(), repository, sections[0])
	expectedPaths := []string{"a.go", "m.go", "main_test.go", "main.go", "z.go"}
	if err != nil || !slices.Equal(paths, expectedPaths) {
		t.Fatalf("changes order paths=%#v err=%v", paths, err)
	}
	expectedFiles := make([]any, 0, len(expectedPaths))
	trackedTokens, err := neoChangesFileOrderTrackedDiffTokens(context.Background(), repository, sections[0], []neoGitDiffRangeEntry{
		{path: "a.go", changeType: "modified"},
		{path: "main.go", changeType: "modified"},
		{path: "main_test.go", changeType: "modified"},
		{path: "z.go", changeType: "modified"},
	})
	if err != nil {
		t.Fatal(err)
	}
	untrackedTokens, err := neoChangesFileOrderUntrackedDiffTokens(context.Background(), repository, sections[0], []neoGitDiffRangeEntry{{path: "m.go", changeType: "untracked"}})
	if err != nil {
		t.Fatal(err)
	}
	for _, path := range expectedPaths {
		token := trackedTokens[path]
		if token == "" {
			token = untrackedTokens[path]
		}
		expectedFiles = append(expectedFiles, map[string]any{"path": path, "diffToken": token})
	}
	if expectedDiffHash := neoGitDiffHash(expectedFiles); diffHash != expectedDiffHash {
		t.Fatalf("changes order hash=%q, want locale-ordered hash %q", diffHash, expectedDiffHash)
	}
	mapValue(arrayValue(request["sections"])[0])["diffHash"] = diffHash
	requestID, sections, ok = normalizeNeoChangesFileOrderRequest(request)
	if !ok || sections[0].diffHash != diffHash {
		t.Fatalf("normalized changes order hash=%q sections=%#v ok=%v", diffHash, sections, ok)
	}
	paths, err = neoChangesFileOrderPaths(context.Background(), repository, sections[0])
	if err != nil || !slices.Equal(paths, expectedPaths) {
		t.Fatalf("changes order path wrapper=%#v err=%v", paths, err)
	}

	rt := newNeoRuntime(&config.Config{})
	actor := newNeoActor(rt, "changes-order-actor", "thread-actor", "T-test", "T-test", neoActorRecord("changes-order-actor", "thread-actor", "T-test"), nil)
	actor.environment = map[string]any{"workingDirectory": repository, "workspaceRoot": repository}
	frames := make(chan map[string]any, 1)
	socket := &neoSocket{writeMessage: func(_ int, data []byte) error {
		var frame map[string]any
		if err := json.Unmarshal(data, &frame); err != nil {
			return err
		}
		frames <- frame
		return nil
	}}
	observerFrames := make(chan map[string]any, 1)
	observerSocket := &neoSocket{writeMessage: func(_ int, data []byte) error {
		var frame map[string]any
		if err := json.Unmarshal(data, &frame); err != nil {
			return err
		}
		observerFrames <- frame
		return nil
	}}
	actor.sockets[socket] = struct{}{}
	actor.sockets[observerSocket] = struct{}{}
	actor.handleForSocket(socket, request)
	select {
	case frame := <-frames:
		result := mapValue(frame["result"])
		orderedSections := arrayValue(result["sections"])
		if frame["type"] != "client_changes_file_order_result" || frame["requestId"] != "changes-file-order-test" || result["status"] != "success" || len(orderedSections) != 1 || !reflect.DeepEqual(stringArrayValue(mapValue(orderedSections[0])["orderedPaths"]), []any{"a.go", "m.go", "main_test.go", "main.go", "z.go"}) {
			t.Fatalf("changes order result = %#v", frame)
		}
	case <-time.After(2 * time.Second):
		t.Fatal("timed out waiting for changes file order result")
	}
	select {
	case frame := <-observerFrames:
		t.Fatalf("changes file order result leaked to another socket: %#v", frame)
	case <-time.After(50 * time.Millisecond):
	}
	if err := os.WriteFile(filepath.Join(repository, "a.go"), []byte("package changed_again\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	staleRequest := map[string]any{
		"type":      "client_changes_file_order",
		"requestId": "changes-file-order-stale",
		"sections": []any{map[string]any{
			"sectionID":        "working-tree",
			"diffHash":         diffHash,
			"baseRevision":     head,
			"headRevision":     "worktree",
			"includeUntracked": true,
		}},
	}
	actor.handleForSocket(socket, staleRequest)
	select {
	case frame := <-frames:
		result := mapValue(frame["result"])
		if frame["requestId"] != "changes-file-order-stale" || result["status"] != "failure" || !strings.Contains(stringValue(result["error"]), "Changes changed") {
			t.Fatalf("stale changes order result = %#v", frame)
		}
	case <-time.After(2 * time.Second):
		t.Fatal("timed out waiting for stale changes file order result")
	}
	staleKey := neoChangesFileOrderRequestKey{socket: socket, requestID: "changes-file-order-stale"}
	deadline := time.Now().Add(time.Second)
	for {
		actor.changesFileOrderMu.Lock()
		_, pending := actor.changesFileOrderRequests[staleKey]
		actor.changesFileOrderMu.Unlock()
		if !pending {
			break
		}
		if time.Now().After(deadline) {
			t.Fatal("stale changes file order request was not released")
		}
		runtime.Gosched()
	}

	cancelKey := neoChangesFileOrderRequestKey{socket: socket, requestID: "cancel-test"}
	cancelled, cancel := context.WithCancel(context.Background())
	actor.changesFileOrderRequests[cancelKey] = neoChangesFileOrderRequest{ctx: cancelled, cancel: cancel, publishMu: &sync.Mutex{}}
	actor.cancelChangesFileOrder(socket, "cancel-test")
	select {
	case <-cancelled.Done():
	default:
		t.Fatal("changes file order cancellation did not cancel pending work")
	}
	if _, exists := actor.changesFileOrderRequests[cancelKey]; exists {
		t.Fatal("cancelled changes file order request was retained")
	}
	sharedRequestID := "replacement-test"
	requestKey := neoChangesFileOrderRequestKey{socket: socket, requestID: sharedRequestID}
	observerRequestKey := neoChangesFileOrderRequestKey{socket: observerSocket, requestID: sharedRequestID}
	firstRequestContext := context.Background()
	secondRequestContext := context.WithValue(context.Background(), struct{}{}, "replacement")
	observerRequestContext := context.WithValue(context.Background(), struct{}{}, "observer")
	actor.changesFileOrderRequests[requestKey] = neoChangesFileOrderRequest{ctx: secondRequestContext, cancel: func() {}, publishMu: &sync.Mutex{}}
	actor.changesFileOrderRequests[observerRequestKey] = neoChangesFileOrderRequest{ctx: observerRequestContext, cancel: func() {}, publishMu: &sync.Mutex{}}
	actor.finishChangesFileOrderRequest(requestKey, firstRequestContext)
	if current, exists := actor.changesFileOrderRequests[requestKey]; !exists || current.ctx != secondRequestContext {
		t.Fatal("finishing an old changes file order request removed its replacement")
	}
	if current, exists := actor.changesFileOrderRequests[observerRequestKey]; !exists || current.ctx != observerRequestContext {
		t.Fatal("same request ID on another socket was replaced")
	}
	if actor.publishChangesFileOrderResult(requestKey, firstRequestContext, map[string]any{"type": "stale"}) {
		t.Fatal("an old changes file order request published after replacement")
	}
	if !actor.publishChangesFileOrderResult(requestKey, secondRequestContext, map[string]any{"type": "active"}) {
		t.Fatal("the active changes file order request could not publish")
	}
	actor.finishChangesFileOrderRequest(requestKey, secondRequestContext)
	if _, exists := actor.changesFileOrderRequests[requestKey]; exists {
		t.Fatal("finishing the active changes file order request retained it")
	}
	if _, exists := actor.changesFileOrderRequests[observerRequestKey]; !exists {
		t.Fatal("finishing a request removed another socket's request with the same ID")
	}
	actor.cancelChangesFileOrderRequestsForSocket(observerSocket)
	if _, exists := actor.changesFileOrderRequests[observerRequestKey]; exists {
		t.Fatal("closing a socket retained its changes file order request")
	}

	invalid := cloneMap(request)
	invalid["sections"] = []any{map[string]any{"sectionID": "bad", "diffHash": "hash", "baseRevision": "HEAD", "headRevision": "worktree", "includeUntracked": false}}
	if _, _, ok := normalizeNeoChangesFileOrderRequest(invalid); ok {
		t.Fatal("changes file order accepted a non-protocol revision")
	}
	indexRequest := cloneMap(request)
	indexRequest["sections"] = []any{map[string]any{"sectionID": "index-head", "diffHash": "hash", "baseRevision": "index", "headRevision": head, "includeUntracked": false}}
	_, indexSections, ok := normalizeNeoChangesFileOrderRequest(indexRequest)
	if !ok || len(indexSections) != 1 || !slices.Equal(neoChangesFileOrderDiffArgs(indexSections[0].baseRevision, indexSections[0].headRevision), []string{"diff", "--no-color", "--no-ext-diff", "--name-status", "-z", "--find-renames", "--cached", "-R", head}) {
		t.Fatalf("changes file order rejected index-to-commit range: %#v", indexSections)
	}
	run("add", "a.go")
	indexPaths, _, err := neoChangesFileOrderSnapshot(context.Background(), repository, indexSections[0])
	if err != nil || !slices.Equal(indexPaths, []string{"a.go"}) {
		t.Fatalf("index-to-commit changes order paths=%#v err=%v", indexPaths, err)
	}
	for _, revisions := range [][2]string{{"worktree", "index"}, {"worktree", head}, {"index", "index"}, {"worktree", "worktree"}} {
		invalid["sections"] = []any{map[string]any{"sectionID": "bad", "diffHash": "hash", "baseRevision": revisions[0], "headRevision": revisions[1], "includeUntracked": false}}
		if _, _, ok := normalizeNeoChangesFileOrderRequest(invalid); ok {
			t.Fatalf("changes file order accepted unsupported revisions %q -> %q", revisions[0], revisions[1])
		}
	}
}

func TestNeoChangesFileOrderBoundsPathStream(t *testing.T) {
	collection := &neoChangesFileOrderEntryCollection{seen: map[string]bool{}}
	nameStatus := newNeoChangesFileOrderNameStatusWriter(collection)
	for _, chunk := range [][]byte{[]byte("M\x00a"), []byte(".go\x00R100\x00old.go\x00"), []byte("new.go\x00")} {
		if _, err := nameStatus.Write(chunk); err != nil {
			t.Fatal(err)
		}
	}
	if err := nameStatus.finish(); err != nil {
		t.Fatal(err)
	}
	want := []neoGitDiffRangeEntry{
		{path: "a.go", changeType: "modified"},
		{path: "new.go", previousPath: "old.go", changeType: "renamed"},
	}
	if !reflect.DeepEqual(collection.entries, want) {
		t.Fatalf("streamed changed paths = %#v, want %#v", collection.entries, want)
	}
	section := neoChangesFileOrderSection{baseRevision: "base", headRevision: "worktree"}
	entry := neoGitDiffRangeEntry{path: "generated.txt", changeType: "modified"}
	patchWriter := &neoChangesFileOrderPatchWriter{section: section, entries: []neoGitDiffRangeEntry{entry}, tokens: map[string]string{}}
	largeLine := bytes.Repeat([]byte("x"), 2*neoWebLocalGitDiffMaxResponseBytes)
	patch := append([]byte("diff --git a/generated.txt b/generated.txt\n+"), largeLine...)
	for len(patch) > 0 {
		chunkSize := min(997, len(patch))
		if _, err := patchWriter.Write(patch[:chunkSize]); err != nil {
			t.Fatalf("stream large patch line: %v", err)
		}
		if len(patchWriter.pending) > len("diff --git ") {
			t.Fatalf("patch writer buffered %d bytes", len(patchWriter.pending))
		}
		patch = patch[chunkSize:]
	}
	if err := patchWriter.finish(); err != nil {
		t.Fatalf("finish large patch line: %v", err)
	}
	expectedPatch := "diff --git a/generated.txt b/generated.txt\n+" + string(largeLine)
	if patchWriter.tokens[entry.path] != neoChangesFileOrderDiffToken(section, entry, expectedPatch) {
		t.Fatal("streamed large patch line changed its diff token")
	}

	exactPathWriter := newNeoChangesFileOrderUntrackedWriter(&neoChangesFileOrderEntryCollection{seen: map[string]bool{}})
	if _, err := exactPathWriter.Write(append(bytes.Repeat([]byte("x"), neoChangesFileOrderPathMaxBytes), 0)); err != nil {
		t.Fatalf("maximum-length path rejected: %v", err)
	}
	if err := exactPathWriter.finish(); err != nil {
		t.Fatalf("maximum-length path finish: %v", err)
	}
	longPathWriter := newNeoChangesFileOrderUntrackedWriter(&neoChangesFileOrderEntryCollection{seen: map[string]bool{}})
	_, err := longPathWriter.Write(bytes.Repeat([]byte("x"), neoChangesFileOrderPathMaxBytes+1))
	var clientError *neoChangesFileOrderClientError
	if !errors.As(err, &clientError) || clientError.code != "path_too_long" || len(longPathWriter.pending) > neoChangesFileOrderPathMaxBytes {
		t.Fatalf("long path error=%v pending=%d", err, len(longPathWriter.pending))
	}

	repository := t.TempDir()
	cmd := exec.Command("git", "init")
	cmd.Dir = repository
	if output, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("git init: %v\n%s", err, output)
	}
	for index := 0; index <= neoChangesFileOrderMaxFiles; index++ {
		path := filepath.Join(repository, fmt.Sprintf("file-%03d.txt", index))
		if err := os.WriteFile(path, []byte("x"), 0o600); err != nil {
			t.Fatal(err)
		}
	}
	_, _, err = neoChangesFileOrderSnapshot(context.Background(), repository, neoChangesFileOrderSection{
		baseRevision:     "worktree",
		headRevision:     "worktree",
		includeUntracked: true,
	})
	clientError = nil
	if !errors.As(err, &clientError) || clientError.code != "too_many_files" {
		t.Fatalf("too many paths error = %v", err)
	}
}

func TestNeoChangesFileOrderPreservesRenamePatchOrder(t *testing.T) {
	repository := t.TempDir()
	run := func(args ...string) string {
		t.Helper()
		cmd := exec.Command("git", args...)
		cmd.Dir = repository
		output, err := cmd.CombinedOutput()
		if err != nil {
			t.Fatalf("git %v: %v\n%s", args, err, output)
		}
		return string(output)
	}
	run("init")
	run("config", "user.email", "test@example.test")
	run("config", "user.name", "Test User")
	run("config", "commit.gpgsign", "false")
	if err := os.WriteFile(filepath.Join(repository, "z.txt"), []byte("rename me\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(repository, "m.txt"), []byte("old\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	run("add", "m.txt", "z.txt")
	run("commit", "-m", "initial")
	base := strings.TrimSpace(run("rev-parse", "HEAD"))
	if err := os.Rename(filepath.Join(repository, "z.txt"), filepath.Join(repository, "a.txt")); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(repository, "m.txt"), []byte("new\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	run("add", "-A")
	run("commit", "-m", "rename")
	head := strings.TrimSpace(run("rev-parse", "HEAD"))
	section := neoChangesFileOrderSection{baseRevision: base, headRevision: head}
	paths, diffHash, err := neoChangesFileOrderSnapshot(context.Background(), repository, section)
	if err != nil {
		t.Fatal(err)
	}
	if !slices.Equal(paths, []string{"a.txt", "m.txt"}) {
		t.Fatalf("rename paths = %#v", paths)
	}
	tokens, err := neoChangesFileOrderTrackedDiffTokens(context.Background(), repository, section, []neoGitDiffRangeEntry{
		{path: "a.txt", previousPath: "z.txt", changeType: "renamed"},
		{path: "m.txt", changeType: "modified"},
	})
	if err != nil {
		t.Fatal(err)
	}
	expected := neoGitDiffHash([]any{
		map[string]any{"path": "a.txt", "diffToken": tokens["a.txt"]},
		map[string]any{"path": "m.txt", "diffToken": tokens["m.txt"]},
	})
	if diffHash != expected {
		t.Fatalf("rename diff hash = %q, want %q", diffHash, expected)
	}
}

func TestNeoGitWorkspaceReconciliationUsesSelectedRepository(t *testing.T) {
	createRepository := func(t *testing.T, name, remoteURL string) (string, string) {
		t.Helper()
		repository := filepath.Join(t.TempDir(), name)
		if err := os.MkdirAll(repository, 0o700); err != nil {
			t.Fatal(err)
		}
		run := func(args ...string) string {
			t.Helper()
			cmd := exec.Command("git", args...)
			cmd.Dir = repository
			output, err := cmd.CombinedOutput()
			if err != nil {
				t.Fatalf("git %v: %v\n%s", args, err, output)
			}
			return string(output)
		}
		run("init")
		run("config", "user.email", "test@example.test")
		run("config", "user.name", "Test User")
		run("config", "commit.gpgsign", "false")
		run("remote", "add", "origin", remoteURL)
		if err := os.WriteFile(filepath.Join(repository, "README.md"), []byte(name+"\n"), 0o600); err != nil {
			t.Fatal(err)
		}
		run("add", "README.md")
		run("commit", "-m", "initial")
		return neoExistingDirectory(repository), strings.TrimSpace(run("rev-parse", "HEAD"))
	}

	firstDirectory, firstHead := createRepository(t, "first", "https://github.com/example/first.git")
	secondDirectory, secondHead := createRepository(t, "second", "https://github.com/example/second.git")
	staleTree := map[string]any{
		"displayName": "first",
		"uri":         neoFileURLForDirectory(firstDirectory),
		"repository": map[string]any{
			"type": "git",
			"url":  "https://github.com/example/first.git",
			"sha":  firstHead,
		},
	}
	environment := neoEnvironmentWithWorkingDirectory(map[string]any{
		"cwd":              firstDirectory,
		"workingDirectory": firstDirectory,
		"workspaceRoot":    firstDirectory,
		"trees":            []any{cloneMap(staleTree)},
		"initial": map[string]any{
			"cwd":              firstDirectory,
			"workingDirectory": firstDirectory,
			"workspaceRoot":    firstDirectory,
			"trees":            []any{cloneMap(staleTree)},
		},
	}, secondDirectory)

	for _, state := range []map[string]any{environment, mapValue(environment["initial"])} {
		if stringValue(state["cwd"]) != secondDirectory || stringValue(state["workingDirectory"]) != secondDirectory || stringValue(state["workspaceRoot"]) != secondDirectory {
			t.Fatalf("workspace paths were not reconciled: %#v", state)
		}
		trees := arrayValue(state["trees"])
		if len(trees) != 1 {
			t.Fatalf("workspace trees = %#v", trees)
		}
		tree := mapValue(trees[0])
		repository := mapValue(tree["repository"])
		if stringValue(tree["uri"]) != neoFileURLForDirectory(secondDirectory) || stringValue(repository["url"]) != "https://github.com/example/second.git" || stringValue(repository["sha"]) != secondHead {
			t.Fatalf("workspace tree was not reconciled: %#v", tree)
		}
	}

	actor := &neoActor{environment: environment}
	request := actor.reconciledGitDiffSnapshotRequest(map[string]any{
		"type":             "client_git_diff_snapshot",
		"requestId":        "git-snapshot-1",
		"baseRevision":     firstHead,
		"headRevision":     "index",
		"includeUntracked": false,
		"content":          "renderable",
	}, "executor_git_diff_snapshot")
	if request["type"] != "executor_git_diff_snapshot" || request["baseRevision"] != secondHead {
		t.Fatalf("foreign snapshot base was not reconciled: %#v", request)
	}
	validRequest := actor.reconciledGitDiffSnapshotRequest(map[string]any{
		"type":         "client_git_diff_snapshot",
		"requestId":    "git-snapshot-2",
		"baseRevision": secondHead,
		"headRevision": "index",
	}, "executor_git_diff_snapshot")
	if validRequest["baseRevision"] != secondHead {
		t.Fatalf("valid snapshot base changed: %#v", validRequest)
	}
}

func TestNeoCloudThreadShellUsesWorkingDirectoryRepository(t *testing.T) {
	useTempNeoThreadStore(t)
	repository := t.TempDir()
	run := func(args ...string) string {
		t.Helper()
		cmd := exec.Command("git", args...)
		cmd.Dir = repository
		output, err := cmd.CombinedOutput()
		if err != nil {
			t.Fatalf("git %v: %v\n%s", args, err, output)
		}
		return string(output)
	}
	run("init")
	run("config", "user.email", "test@example.test")
	run("config", "user.name", "Test User")
	run("config", "commit.gpgsign", "false")
	const repositoryURL = "https://github.com/example/selected.git"
	run("remote", "add", "origin", repositoryURL)
	if err := os.WriteFile(filepath.Join(repository, "README.md"), []byte("selected\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	run("add", "README.md")
	run("commit", "-m", "initial")

	const threadID = "T-019f7b22-e960-70c3-b1b1-35850ec4da08"
	upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body := readNeoJSON(r.Body)
		if stringValue(body["repositoryURL"]) != repositoryURL {
			t.Fatalf("cloud shell repositoryURL = %#v", body["repositoryURL"])
		}
		if projectID := nestedString(body["threadMeta"], "projectID"); projectID != "" {
			t.Fatalf("cloud shell received local project ID %q", projectID)
		}
		writeNeoJSON(w, http.StatusCreated, map[string]any{
			"threadId":         threadID,
			"wsToken":          "cloud-token",
			"ownerUserId":      "cloud-user",
			"threadVersion":    0,
			"usesDtw":          true,
			"usesThreadActors": true,
		})
	}))
	t.Cleanup(upstream.Close)
	rt := newNeoRuntime(&config.Config{AmpCode: config.AmpCode{
		UpstreamURL:    upstream.URL,
		UpstreamAPIKey: "upstream-key",
	}})
	response, status := rt.localThreadActorManagementResponse(context.Background(), map[string]any{
		"workingDirectory": repository,
		"workspaceRoot":    repository,
		"usesThreadActors": true,
		"threadMeta": map[string]any{
			"cliProxyAPIWebLocalShell": true,
			"cliProxyAPILocalNeo":      true,
		},
	}, "")
	if status != http.StatusCreated || stringValue(response["threadId"]) != threadID {
		t.Fatalf("cloud shell response=%#v status=%d", response, status)
	}
	actor := rt.store.lookupThreadActor(threadID)
	if actor == nil {
		t.Fatal("cloud shell actor was not created")
	}
	actor.mu.Lock()
	meta := cloneMap(actor.meta)
	environment := cloneMap(actor.environment)
	actor.mu.Unlock()
	if stringValue(meta["repositoryURL"]) != repositoryURL {
		t.Fatalf("actor repository metadata = %#v", meta)
	}
	expectedProjectID := neoDeterministicLocalProjectID("selected", repositoryURL, neoExistingDirectory(repository))
	if stringValue(meta["projectID"]) != expectedProjectID || stringValue(meta["projectName"]) != "selected" || stringValue(meta["namespace"]) != "example" {
		t.Fatalf("actor project metadata = %#v, want projectID=%q", meta, expectedProjectID)
	}
	if workingDirectory := neoWorkingDirectoryFromEnvironment(environment); workingDirectory != neoExistingDirectory(repository) {
		t.Fatalf("actor working directory = %q", workingDirectory)
	}
}

