func TestNeoRuntimeGatewayThreadActorImportRoute(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})
	server := httptest.NewServer(http.HandlerFunc(rt.handleHTTP))
	t.Cleanup(server.Close)

	threadID := "T-019e1046-656d-7132-879f-390ded941c16"
	body := bytes.NewBufferString(`{"thread":{"id":"` + threadID + `","agentMode":"smart","messages":[{"role":"user","content":[{"type":"text","text":"hi"}]}]}}`)
	req, err := http.NewRequest(http.MethodPost, server.URL+"/gateway/threadActor/request/import?rvt-method=getOrCreate&rvt-key="+url.QueryEscape(threadID), body)
	if err != nil {
		t.Fatalf("new import request: %v", err)
	}
	req.Header.Set("Content-Type", "application/json")
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		t.Fatalf("post import request: %v", err)
	}
	defer resp.Body.Close()
	respBody, _ := io.ReadAll(resp.Body)
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("import status=%d body=%s", resp.StatusCode, respBody)
	}
	if !strings.Contains(string(respBody), threadID) {
		t.Fatalf("import response missing thread id: %s", respBody)
	}

	actors := rt.store.findActors(url.Values{"name": []string{"threadActor"}, "key": []string{threadID}})
	if len(actors) != 1 {
		t.Fatalf("gateway actor count = %d, actors=%#v", len(actors), actors)
	}
	rt.store.mu.RLock()
	actorID := rt.store.byNameKey["threadActor\x00"+threadID]
	actor := rt.store.actors[actorID]
	rt.store.mu.RUnlock()
	if actor == nil {
		t.Fatalf("missing imported actor id=%q", actorID)
	}
	actor.mu.Lock()
	messageCount := len(actor.messages)
	actor.mu.Unlock()
	if messageCount != 1 {
		t.Fatalf("imported message count = %d, want 1", messageCount)
	}
}

func TestNeoRuntimeGatewayThreadActorImportRejectsMismatchedThreadID(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})
	server := httptest.NewServer(http.HandlerFunc(rt.handleHTTP))
	t.Cleanup(server.Close)

	actorThreadID := "T-019e1046-656d-7132-879f-390ded941c16"
	importThreadID := "T-019e1046-656d-7132-879f-390ded941c17"
	actor := rt.store.ensureThreadActor(actorThreadID)
	actor.title = "Original title"
	body := bytes.NewBufferString(`{"thread":{"id":"` + importThreadID + `","title":"Wrong title","agentMode":"smart","messages":[]}}`)
	req, err := http.NewRequest(http.MethodPost, server.URL+"/gateway/threadActor/request/import?rvt-method=getOrCreate&rvt-key="+url.QueryEscape(actorThreadID), body)
	if err != nil {
		t.Fatalf("new import request: %v", err)
	}
	req.Header.Set("Content-Type", "application/json")
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		t.Fatalf("post import request: %v", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusBadRequest {
		responseBody, _ := io.ReadAll(resp.Body)
		t.Fatalf("import status=%d body=%s", resp.StatusCode, responseBody)
	}

	actor.mu.Lock()
	if actor.threadID != actorThreadID || actor.title != "Original title" {
		actor.mu.Unlock()
		t.Fatalf("mismatched import mutated actor thread/title = %q/%q", actor.threadID, actor.title)
	}
	actor.mu.Unlock()
	if imported := rt.store.lookupThreadActor(importThreadID); imported != nil {
		t.Fatalf("mismatched import created actor %#v", imported)
	}
}

