func TestNeoActorArchiveUsesTopLevelArchivedFlag(t *testing.T) {
	dir := t.TempDir()
	oldStoreDir := neoAmpDataDir
	neoAmpDataDir = func() string { return dir }
	t.Cleanup(func() { neoAmpDataDir = oldStoreDir })

	rt := newNeoRuntime(&config.Config{})
	threadID := "T-019e1046-656d-7132-879f-390ded941c18"
	actor := newNeoActor(rt, "actor-test", "threadActor", threadID, threadID, neoActorRecord("actor-test", "threadActor", threadID), nil)

	actor.archiveThread(true, nil)
	waitForNeoActorSyncIdle(t, actor)

	actor.mu.Lock()
	archived := actor.archived
	threadStatus := actor.threadStatus
	actor.mu.Unlock()
	if !archived || threadStatus != "" {
		t.Fatalf("archive state = archived:%v threadStatus:%q, want archived true and empty official thread status", archived, threadStatus)
	}
	snapshot, ok := actor.threadSnapshot()
	if !ok {
		t.Fatal("threadSnapshot returned false")
	}
	thread := marshalNeoThreadForTest(t, neoCloudThread(snapshot))
	if thread["archived"] != true || thread["threadStatus"] != nil {
		t.Fatalf("cloud archive fields = archived:%#v threadStatus:%#v", thread["archived"], thread["threadStatus"])
	}

	actor.archiveThread(false, nil)
	waitForNeoActorSyncIdle(t, actor)
	snapshot, ok = actor.threadSnapshot()
	if !ok {
		t.Fatal("threadSnapshot returned false after unarchive")
	}
	thread = marshalNeoThreadForTest(t, neoCloudThread(snapshot))
	if thread["archived"] != false {
		t.Fatalf("cloud archived after unarchive = %#v, want false", thread["archived"])
	}

	actor.setPinned(true)
	waitForNeoActorSyncIdle(t, actor)
	snapshot, ok = actor.threadSnapshot()
	if !ok {
		t.Fatal("threadSnapshot returned false after pin")
	}
	thread = marshalNeoThreadForTest(t, neoCloudThread(snapshot))
	if thread["pinned"] != true || actor.stateSnapshotResponse()["pinned"] != true {
		t.Fatalf("pin fields = cloud:%#v state:%#v", thread["pinned"], actor.stateSnapshotResponse()["pinned"])
	}
	restored := newNeoActor(rt, "actor-restored", "threadActor", threadID, threadID, neoActorRecord("actor-restored", "threadActor", threadID), nil)
	if err := restored.importThreadLocalOnly(thread); err != nil {
		t.Fatalf("import pinned thread: %v", err)
	}
	if restored.stateSnapshotResponse()["pinned"] != true {
		t.Fatalf("restored pinned = %#v, want true", restored.stateSnapshotResponse()["pinned"])
	}
}

func TestNeoRuntimeSnapshotIncludesThreadStatusAndCompactionRecords(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})
	threadID := "T-019e0e6e-f3f1-7078-b5dd-748f66f8c25d"
	actor, _ := rt.store.upsert(map[string]any{"name": "threadActor", "key": threadID, "input": map[string]any{"threadId": threadID}}, true)
	actor.mu.Lock()
	actor.compactionRecords = []map[string]any{{"cutMessageId": "M-00000000000000000000aa", "createdAt": "2026-01-01T00:00:00Z"}}
	actor.mu.Unlock()

	server := httptest.NewServer(http.HandlerFunc(rt.handleHTTP))
	t.Cleanup(server.Close)

	dialer := websocket.Dialer{Subprotocols: []string{"rivet", "rivet_encoding.4"}}
	wsURL := "ws" + strings.TrimPrefix(server.URL, "http") + "/gateway/threadActor/?rvt-method=getOrCreate&rvt-key=" + url.QueryEscape(threadID)
	conn, resp, err := dialer.Dial(wsURL, nil)
	if err != nil {
		status := 0
		if resp != nil {
			status = resp.StatusCode
		}
		t.Fatalf("gateway websocket dial failed status=%d err=%v", status, err)
	}
	defer conn.Close()
	_ = conn.SetReadDeadline(time.Now().Add(2 * time.Second))

	sawThreadStatus := false
	sawCompactionRecords := false
	for !sawThreadStatus || !sawCompactionRecords {
		_, payload, err := conn.ReadMessage()
		if err != nil {
			t.Fatalf("read snapshot message: %v", err)
		}
		var msg map[string]any
		if err := json.Unmarshal(payload, &msg); err != nil {
			t.Fatalf("snapshot JSON error: %v", err)
		}
		switch msg["type"] {
		case "thread_status":
			status, ok := msg["status"]
			if !ok {
				t.Fatalf("thread_status missing nullable status: %#v", msg)
			}
			if status != nil {
				t.Fatalf("thread_status status = %#v, want null", status)
			}
			sawThreadStatus = true
		case "compaction_records":
			records := arrayValue(msg["records"])
			if len(records) != 1 || stringValue(mapValue(records[0])["cutMessageId"]) != "M-00000000000000000000aa" {
				t.Fatalf("compaction_records = %#v", msg)
			}
			sawCompactionRecords = true
		}
	}
}

func TestNeoUserActorGetRecentThreadsActionMatchesBinaryShape(t *testing.T) {
	dir := t.TempDir()
	oldStoreDir := neoAmpDataDir
	neoAmpDataDir = func() string { return dir }
	t.Cleanup(func() { neoAmpDataDir = oldStoreDir })

	rt := newNeoRuntime(&config.Config{})
	userActor, _ := rt.store.upsert(map[string]any{"name": "userActor", "key": "user-local"}, true)

	recentID := "T-019e0e6e-f3f1-7078-b5dd-748f66f8c25e"
	recent, _ := rt.store.upsert(map[string]any{"name": "threadActor", "key": recentID, "input": map[string]any{"threadId": recentID}}, true)
	recent.mu.Lock()
	recent.title = "Recent local work"
	recent.agentState = "working"
	recent.executorID = "executor-test"
	recent.executorReady = true
	recent.executorBootstrapComplete = true
	recent.currentInference = &neoInferenceInflight{messageID: "M-recent-assistant", agentMode: "deep", reasoningEffort: "xhigh", tools: []string{"shell_command"}}
	recent.environment = map[string]any{"initial": map[string]any{"trees": []any{map[string]any{"uri": "file:///Users/test/project", "displayName": "project"}}}}
	recent.meta = map[string]any{"labels": []string{"review"}}
	recent.sockets = map[*neoSocket]struct{}{&neoSocket{}: {}}
	recent.messages = []neoMessage{
		{
			ThreadID:  recentID,
			MessageID: "M-recent",
			Role:      "user",
			CreatedAt: "2026-05-31T10:00:00Z",
			Content:   []any{map[string]any{"type": "text", "text": "continue runtime parity"}},
		},
		{
			ThreadID:  recentID,
			MessageID: "M-recent-assistant",
			Role:      "assistant",
			CreatedAt: "2026-05-31T10:00:01Z",
			Content: []any{map[string]any{
				"type": "tool_use",
				"name": "edit_file",
				"input": map[string]any{
					"old_str": "old",
					"new_str": "new\nextra",
				},
			}},
		},
	}
	recent.mu.Unlock()

	oldID := "T-019e0e6e-f3f1-7078-b5dd-748f66f8c25f"
	old, _ := rt.store.upsert(map[string]any{"name": "threadActor", "key": oldID, "input": map[string]any{"threadId": oldID}}, true)
	old.mu.Lock()
	old.title = "Older local work"
	old.messages = []neoMessage{{
		ThreadID:  oldID,
		MessageID: "M-old",
		Role:      "user",
		CreatedAt: "2026-05-30T10:00:00Z",
		Content:   []any{map[string]any{"type": "text", "text": "older thread"}},
	}}
	old.mu.Unlock()

	since := int(time.Date(2026, 5, 31, 0, 0, 0, 0, time.UTC).UnixMilli())
	result := userActor.handleForSocket(nil, map[string]any{
		"type": "getRecentThreads",
		"args": []any{map[string]any{"limit": 10, "sinceMs": since}},
	})
	items := arrayValue(result)
	if len(items) != 1 {
		t.Fatalf("getRecentThreads result = %#v, want one recent thread", result)
	}
	item := mapValue(items[0])
	if item["threadId"] != recentID {
		t.Fatalf("threadId = %#v, want %s", item["threadId"], recentID)
	}
	if item["title"] != "Recent local work" {
		t.Fatalf("title = %#v", item["title"])
	}
	if item["lastUserMessageAt"] != "2026-05-31T10:00:00Z" {
		t.Fatalf("lastUserMessageAt = %#v", item["lastUserMessageAt"])
	}
	if item["state"] != "working" || item["agentState"] != "working" {
		t.Fatalf("state = %#v agentState = %#v", item["state"], item["agentState"])
	}
	if item["messageId"] != "M-recent-assistant" || item["agentMode"] != "deep" || item["reasoningEffort"] != "xhigh" {
		t.Fatalf("active inference status = %#v", item)
	}
	if tools := arrayValue(mapValue(item["currentInference"])["tools"]); len(tools) != 1 || tools[0] != "shell_command" {
		t.Fatalf("currentInference = %#v", item["currentInference"])
	}
	if item["hasExecutor"] != true || item["executorConnected"] != true {
		t.Fatalf("executor status = has:%#v connected:%#v", item["hasExecutor"], item["executorConnected"])
	}
	if numberFrom(item["messageCount"]) != 2 || stringValue(mapValue(arrayValue(item["labels"])[0])["name"]) != "review" {
		t.Fatalf("summary metadata = count:%#v labels:%#v", item["messageCount"], item["labels"])
	}
	diffStats := mapValue(mapValue(item["summaryStats"])["diffStats"])
	if numberFrom(diffStats["added"]) != 2 || numberFrom(diffStats["changed"]) != 1 || numberFrom(diffStats["deleted"]) != 1 {
		t.Fatalf("summary diffStats = %#v, want added 2 changed 1 deleted 1", diffStats)
	}
	workspace := mapValue(item["workspace"])
	if workspace["uri"] != "file:///Users/test/project" || workspace["displayName"] != "project" {
		t.Fatalf("workspace = %#v", workspace)
	}

	recent.mu.Lock()
	recent.executorID = ""
	recent.mu.Unlock()
	observerOnlyStatus, _ := recent.recentThreadStatus()
	if observerOnlyStatus["hasExecutor"] != false || observerOnlyStatus["executorConnected"] != false {
		t.Fatalf("observer-only executor status = has:%#v connected:%#v", observerOnlyStatus["hasExecutor"], observerOnlyStatus["executorConnected"])
	}
	if observerOnlyStatus["agentState"] != "working" {
		t.Fatalf("observer-only agentState = %#v", observerOnlyStatus["agentState"])
	}
}

func TestNeoRecentThreadStatusCachesDiffStatsByMessageRevision(t *testing.T) {
	threadID := "T-019e0e6e-f3f1-7078-b5dd-748f66f8c25e"
	actor := newNeoActor(nil, "actor-diff-cache", "threadActor", threadID, threadID, neoActorRecord("actor-diff-cache", "threadActor", threadID), nil)
	message := neoMessage{
		ThreadID:  threadID,
		MessageID: "M-edit",
		Role:      "assistant",
		Content: []any{map[string]any{
			"type":     "tool_use",
			"name":     "create_file",
			"complete": true,
			"input":    map[string]any{"content": "one\ntwo"},
		}},
	}
	actor.storeMessage(message)

	status, _ := actor.recentThreadStatus()
	diffStats := mapValue(mapValue(status["summaryStats"])["diffStats"])
	if numberFrom(diffStats["added"]) != 2 {
		t.Fatalf("initial diffStats = %#v, want two added lines", diffStats)
	}
	actor.mu.Lock()
	if !actor.diffStatsCached || actor.diffStatsRevision != actor.messageRevision {
		t.Fatalf("diff cache = cached:%v revision:%d messageRevision:%d", actor.diffStatsCached, actor.diffStatsRevision, actor.messageRevision)
	}
	actor.diffStats = neoDiffStats{added: 91}
	actor.mu.Unlock()

	status, _ = actor.recentThreadStatus()
	diffStats = mapValue(mapValue(status["summaryStats"])["diffStats"])
	if numberFrom(diffStats["added"]) != 91 {
		t.Fatalf("same-revision diffStats = %#v, want cached value", diffStats)
	}

	message.Content = []any{map[string]any{
		"type":     "tool_use",
		"name":     "create_file",
		"complete": true,
		"input":    map[string]any{"content": "one\ntwo\nthree"},
	}}
	actor.storeMessage(message)
	status, _ = actor.recentThreadStatus()
	diffStats = mapValue(mapValue(status["summaryStats"])["diffStats"])
	if numberFrom(diffStats["added"]) != 3 {
		t.Fatalf("updated diffStats = %#v, want three added lines", diffStats)
	}
}

func TestNeoUserActorGetRecentThreadsSeedsMarkedCloudThread(t *testing.T) {
	enabled := true
	threadID := "T-019e0e6e-f3f1-7078-b5dd-748f66f8c262"
	listRequests := 0
	getRequests := 0
	upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if got := r.Header.Get("Authorization"); got != "Bearer secret" {
			t.Fatalf("Authorization = %q, want bearer secret", got)
		}
		switch r.URL.RawQuery {
		case "listThreads":
			listRequests++
			var payload map[string]any
			if err := json.NewDecoder(r.Body).Decode(&payload); err != nil {
				t.Fatalf("listThreads body JSON error: %v", err)
			}
			params := mapValue(payload["params"])
			if params["limit"] != float64(20) {
				t.Fatalf("listThreads limit = %#v, want 20", params["limit"])
			}
			writeNeoJSON(w, http.StatusOK, map[string]any{"ok": true, "result": map[string]any{"threads": []any{map[string]any{
				"thread": map[string]any{
					"data": map[string]any{
						"id":                   threadID,
						"title":                "Cloud seeded sidebar",
						"agentMode":            "deep",
						"userLastInteractedAt": "2026-06-20T12:00:00Z",
					},
					"meta": map[string]any{"executorType": "local-client"},
				},
			}}}})
		case "getThread":
			getRequests++
			t.Fatal("recent thread seeding fetched a full thread")
		default:
			t.Fatalf("unexpected upstream request path=%s query=%s", r.URL.Path, r.URL.RawQuery)
		}
	}))
	t.Cleanup(upstream.Close)

	rt := newNeoRuntime(&config.Config{AmpCode: config.AmpCode{
		UpstreamURL:    upstream.URL,
		UpstreamAPIKey: "secret",
		NeoLocalRuntime: config.AmpNeoLocalRuntime{
			Enabled: &enabled,
		},
	}})
	userActor, _ := rt.store.upsert(map[string]any{"name": "userActor", "key": "user-local"}, true)

	result := userActor.handleForSocket(nil, map[string]any{
		"type": "getRecentThreads",
		"args": []any{map[string]any{"limit": 5}},
	})
	items := arrayValue(result)
	if len(items) != 1 {
		t.Fatalf("getRecentThreads result = %#v, want one seeded cloud thread", result)
	}
	item := mapValue(items[0])
	if item["threadId"] != threadID {
		t.Fatalf("threadId = %#v, want %s", item["threadId"], threadID)
	}
	if item["title"] != "Cloud seeded sidebar" {
		t.Fatalf("title = %#v", item["title"])
	}
	if item["lastUserMessageAt"] != "2026-06-20T12:00:00Z" {
		t.Fatalf("lastUserMessageAt = %#v", item["lastUserMessageAt"])
	}
	if listRequests != 1 || getRequests != 0 {
		t.Fatalf("upstream requests = list:%d get:%d, want list:1 get:0", listRequests, getRequests)
	}
}

