func TestNeoUserActorReceivesThreadStatusUpdatedNotification(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})
	threadID := "T-019e0e6e-f3f1-7078-b5dd-748f66f8c260"
	threadActor, _ := rt.store.upsert(map[string]any{"name": "threadActor", "key": threadID, "input": map[string]any{"threadId": threadID}}, true)
	threadActor.mu.Lock()
	threadActor.title = "Live local thread"
	threadActor.messages = []neoMessage{{
		ThreadID:  threadID,
		MessageID: "M-live",
		Role:      "user",
		CreatedAt: "2026-05-31T11:00:00Z",
		Content:   []any{map[string]any{"type": "text", "text": "watch status"}},
	}}
	threadActor.mu.Unlock()

	server := httptest.NewServer(http.HandlerFunc(rt.handleHTTP))
	t.Cleanup(server.Close)

	dialer := websocket.Dialer{Subprotocols: []string{"rivet", "rivet_conn_params.%7B%22transport%22%3A%22json-rpc%22%7D", "rivet_encoding.4", "rivet_skip_ready_wait"}}
	wsURL := "ws" + strings.TrimPrefix(server.URL, "http") + "/gateway/userActor/?rvt-method=getOrCreate&rvt-key=user-local"
	conn, resp, err := dialer.Dial(wsURL, nil)
	if err != nil {
		status := 0
		if resp != nil {
			status = resp.StatusCode
		}
		t.Fatalf("gateway userActor websocket dial failed status=%d err=%v", status, err)
	}
	defer conn.Close()

	readThreadStatusUpdated := func() map[string]any {
		t.Helper()
		deadline := time.Now().Add(2 * time.Second)
		for time.Now().Before(deadline) {
			_ = conn.SetReadDeadline(time.Now().Add(time.Until(deadline)))
			_, payload, err := conn.ReadMessage()
			if err != nil {
				if netErr, ok := err.(net.Error); ok && netErr.Timeout() {
					break
				}
				t.Fatalf("read userActor notification: %v", err)
			}
			var frame map[string]any
			if err := json.Unmarshal(payload, &frame); err != nil {
				t.Fatalf("userActor notification JSON error: %v", err)
			}
			if frame["method"] != "threadStatusUpdated" {
				continue
			}
			return mapValue(frame["params"])
		}
		t.Fatal("did not receive threadStatusUpdated notification")
		return nil
	}

	threadActor.handle(map[string]any{"type": "agent_state", "state": "working"})
	params := readThreadStatusUpdated()
	if params["threadId"] != threadID || params["title"] != "Live local thread" || params["state"] != "working" || params["agentState"] != "working" {
		t.Fatalf("threadStatusUpdated params = %#v", params)
	}
	if params["lastUserMessageAt"] != "2026-05-31T11:00:00Z" {
		t.Fatalf("threadStatusUpdated lastUserMessageAt = %#v", params["lastUserMessageAt"])
	}

	threadActor.handle(map[string]any{"type": "client_set_thread_title", "title": "Renamed live thread"})
	params = readThreadStatusUpdated()
	if params["threadId"] != threadID || params["title"] != "Renamed live thread" {
		t.Fatalf("threadStatusUpdated rename params = %#v", params)
	}

	parentThreadID := "T-019e1046-656d-7132-879f-390ded941c16"
	threadActor.handle(map[string]any{"type": "thread_relationships", "relationships": []any{map[string]any{
		"threadID":  parentThreadID,
		"type":      "mention",
		"role":      "parent",
		"createdAt": 1,
	}}})
	params = readThreadStatusUpdated()
	for params["parentThreadID"] != parentThreadID {
		params = readThreadStatusUpdated()
	}
	if params["threadId"] != threadID || params["parentThreadID"] != parentThreadID {
		t.Fatalf("threadStatusUpdated relationship params = %#v", params)
	}

	threadActor.archiveThread(true, nil)
	params = readThreadStatusUpdated()
	for params["archived"] != true {
		params = readThreadStatusUpdated()
	}
	if params["threadId"] != threadID || params["archived"] != true {
		t.Fatalf("threadStatusUpdated archive params = %#v", params)
	}
}

func TestNeoUserActorThreadStatusUpdatesAreScopedToOwner(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})
	threadID := "T-019e0e6e-f3f1-7078-b5dd-748f66f8c276"
	threadActor := rt.store.ensureThreadActor(threadID)
	threadActor.mu.Lock()
	threadActor.title = "Owner A private thread"
	threadActor.meta["ownerUserId"] = "user-a"
	threadActor.meta["creatorUserID"] = "user-a"
	threadActor.messages = []neoMessage{{
		ThreadID:  threadID,
		MessageID: "M-owner-a",
		Role:      "user",
		CreatedAt: "2026-05-31T11:00:00Z",
		Content:   []any{map[string]any{"type": "text", "text": "private"}},
	}}
	threadActor.mu.Unlock()

	server := httptest.NewServer(http.HandlerFunc(rt.handleHTTP))
	t.Cleanup(server.Close)
	dial := func(ownerUserID string) *websocket.Conn {
		t.Helper()
		dialer := websocket.Dialer{Subprotocols: []string{"rivet", "rivet_conn_params.%7B%22transport%22%3A%22json-rpc%22%7D", "rivet_encoding.4", "rivet_skip_ready_wait"}}
		wsURL := "ws" + strings.TrimPrefix(server.URL, "http") + "/gateway/userActor/?rvt-method=getOrCreate&rvt-key=" + ownerUserID
		conn, resp, err := dialer.Dial(wsURL, nil)
		if err != nil {
			status := 0
			if resp != nil {
				status = resp.StatusCode
			}
			t.Fatalf("gateway userActor websocket dial failed owner=%s status=%d err=%v", ownerUserID, status, err)
		}
		return conn
	}
	ownerConn := dial("user-a")
	defer ownerConn.Close()
	otherConn := dial("user-b")
	defer otherConn.Close()

	readStatus := func(conn *websocket.Conn, timeout time.Duration) (map[string]any, bool) {
		t.Helper()
		deadline := time.Now().Add(timeout)
		for time.Now().Before(deadline) {
			_ = conn.SetReadDeadline(deadline)
			_, payload, err := conn.ReadMessage()
			if err != nil {
				if netErr, ok := err.(net.Error); ok && netErr.Timeout() {
					return nil, false
				}
				t.Fatalf("read userActor owner notification: %v", err)
			}
			var frame map[string]any
			if err := json.Unmarshal(payload, &frame); err != nil {
				t.Fatalf("userActor owner notification JSON error: %v", err)
			}
			if frame["method"] == "threadStatusUpdated" {
				return mapValue(frame["params"]), true
			}
		}
		return nil, false
	}

	rt.store.broadcastThreadStatusUpdated(threadActor)
	if params, ok := readStatus(ownerConn, 2*time.Second); !ok || params["threadId"] != threadID || params["title"] != "Owner A private thread" {
		t.Fatalf("owner status = %#v, ok=%v", params, ok)
	}
	if params, ok := readStatus(otherConn, 250*time.Millisecond); ok {
		t.Fatalf("other owner received private status: %#v", params)
	}
}

func TestNeoUserActorReceivesThreadStatusUpdatedOnExecutorConnectDisconnect(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})
	threadID := "T-019e0e6e-f3f1-7078-b5dd-748f66f8c261"
	threadActor := rt.store.ensureThreadActor(threadID)
	threadActor.mu.Lock()
	threadActor.title = "Executor local thread"
	threadActor.messages = []neoMessage{{
		ThreadID:  threadID,
		MessageID: "M-executor-local",
		Role:      "user",
		CreatedAt: "2026-05-31T12:00:00Z",
		Content:   []any{map[string]any{"type": "text", "text": "watch executor"}},
	}}
	threadActor.mu.Unlock()

	server := httptest.NewServer(http.HandlerFunc(rt.handleHTTP))
	t.Cleanup(server.Close)

	dialer := websocket.Dialer{Subprotocols: []string{"rivet", "rivet_conn_params.%7B%22transport%22%3A%22json-rpc%22%7D", "rivet_encoding.4", "rivet_skip_ready_wait"}}
	wsURL := "ws" + strings.TrimPrefix(server.URL, "http") + "/gateway/userActor/?rvt-method=getOrCreate&rvt-key=user-local"
	conn, resp, err := dialer.Dial(wsURL, nil)
	if err != nil {
		status := 0
		if resp != nil {
			status = resp.StatusCode
		}
		t.Fatalf("gateway userActor websocket dial failed status=%d err=%v", status, err)
	}
	defer conn.Close()

	readThreadStatusUpdated := func() map[string]any {
		t.Helper()
		deadline := time.Now().Add(2 * time.Second)
		for time.Now().Before(deadline) {
			_ = conn.SetReadDeadline(time.Now().Add(time.Until(deadline)))
			_, payload, err := conn.ReadMessage()
			if err != nil {
				if netErr, ok := err.(net.Error); ok && netErr.Timeout() {
					break
				}
				t.Fatalf("read userActor executor notification: %v", err)
			}
			var frame map[string]any
			if err := json.Unmarshal(payload, &frame); err != nil {
				t.Fatalf("userActor executor notification JSON error: %v", err)
			}
			if frame["method"] != "threadStatusUpdated" {
				continue
			}
			params := mapValue(frame["params"])
			if params["threadId"] != threadID {
				continue
			}
			return params
		}
		t.Fatal("did not receive threadStatusUpdated notification for executor state")
		return nil
	}

	threadActor.executorConnected(map[string]any{"executorId": "executor-test"})
	params := readThreadStatusUpdated()
	if params["title"] != "Executor local thread" || params["state"] != "idle" || params["agentState"] != "idle" {
		t.Fatalf("executor connected threadStatusUpdated params = %#v", params)
	}
	if params["hasExecutor"] != true || params["executorConnected"] != true {
		t.Fatalf("executor connected status = has:%#v connected:%#v params=%#v", params["hasExecutor"], params["executorConnected"], params)
	}
	if params["lastUserMessageAt"] != "2026-05-31T12:00:00Z" {
		t.Fatalf("executor connected lastUserMessageAt = %#v", params["lastUserMessageAt"])
	}
	snapshot, ok := threadActor.threadSnapshot()
	if !ok {
		t.Fatal("missing connected thread snapshot")
	}
	thread := neoCloudThread(snapshot)
	if thread["hasExecutor"] != true || thread["executorConnected"] != true || mapValue(thread["meta"])["executorType"] != "local-client" {
		t.Fatalf("connected cloud thread executor state = has:%#v connected:%#v meta:%#v", thread["hasExecutor"], thread["executorConnected"], thread["meta"])
	}

	threadActor.executorDisconnected(map[string]any{"message": "done"})
	params = readThreadStatusUpdated()
	if params["hasExecutor"] != false || params["executorConnected"] != false {
		t.Fatalf("executor disconnected status = has:%#v connected:%#v params=%#v", params["hasExecutor"], params["executorConnected"], params)
	}
	snapshot, ok = threadActor.threadSnapshot()
	if !ok {
		t.Fatal("missing disconnected thread snapshot")
	}
	thread = neoCloudThread(snapshot)
	if thread["hasExecutor"] != false || thread["executorConnected"] != false {
		t.Fatalf("disconnected cloud thread executor state = has:%#v connected:%#v", thread["hasExecutor"], thread["executorConnected"])
	}
	if meta := mapValue(thread["meta"]); meta["executorType"] != "local-client" || meta["usesThreadActors"] != true {
		t.Fatalf("disconnected cloud thread identity = %#v", meta)
	}
}

func TestNeoCloudThreadSnapshotDoesNotReportConnectingExecutor(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})
	threadID := "T-019f4000-0000-4000-8000-000000000029"
	actor := rt.store.ensureThreadActor(threadID)
	actor.mu.Lock()
	actor.executorID = "executor-connecting"
	actor.executorReady = false
	actor.executorBootstrapComplete = false
	actor.bootstrapExecutorType = "local-client"
	actor.messages = []neoMessage{{MessageID: "M-user", Role: "user", Content: []any{map[string]any{"type": "text", "text": "hi"}}, Seq: 1}}
	actor.mu.Unlock()

	snapshot, ok := actor.threadSnapshot()
	if !ok {
		t.Fatal("missing thread snapshot")
	}
	thread := neoCloudThread(snapshot)
	if thread["hasExecutor"] != false || thread["executorConnected"] != false {
		t.Fatalf("connecting executor should not be reported as connected: has=%#v connected=%#v", thread["hasExecutor"], thread["executorConnected"])
	}
	if meta := mapValue(thread["meta"]); meta["executorType"] != "local-client" || meta["usesThreadActors"] != true {
		t.Fatalf("connecting executor identity = %#v", meta)
	}
	status, _ := actor.recentThreadStatus()
	if status["hasExecutor"] != false || status["executorConnected"] != false {
		t.Fatalf("connecting executor status should not be reported as connected: has=%#v connected=%#v", status["hasExecutor"], status["executorConnected"])
	}
}

func TestNeoCloudThreadSnapshotExecutorTypePrecedence(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})
	actor := rt.store.ensureThreadActor("T-019e0e6e-f3f1-7078-b5dd-748f66f8c264")
	actor.mu.Lock()
	actor.executorID = "executor-test"
	actor.executorReady = true
	actor.executorBootstrapComplete = true
	actor.bootstrapExecutorType = "daemon"
	actor.meta = map[string]any{"executorType": "local-client"}
	actor.messages = []neoMessage{{MessageID: "M-user", Role: "user", Content: []any{map[string]any{"type": "text", "text": "hi"}}, Seq: 1}}
	actor.mu.Unlock()

	snapshot, ok := actor.threadSnapshot()
	if !ok {
		t.Fatal("missing thread snapshot")
	}
	thread := neoCloudThread(snapshot)
	if mapValue(thread["meta"])["executorType"] != "daemon" {
		t.Fatalf("executorType with bootstrap override = %#v", thread["meta"])
	}

	actor.mu.Lock()
	actor.bootstrapExecutorType = ""
	actor.meta = map[string]any{"executorType": "custom-client"}
	actor.mu.Unlock()
	snapshot, ok = actor.threadSnapshot()
	if !ok {
		t.Fatal("missing thread snapshot with meta executor type")
	}
	thread = neoCloudThread(snapshot)
	if mapValue(thread["meta"])["executorType"] != "custom-client" {
		t.Fatalf("executorType with meta override = %#v", thread["meta"])
	}

	actor.mu.Lock()
	actor.meta = nil
	actor.mu.Unlock()
	snapshot, ok = actor.threadSnapshot()
	if !ok {
		t.Fatal("missing thread snapshot with fallback executor type")
	}
	thread = neoCloudThread(snapshot)
	if mapValue(thread["meta"])["executorType"] != "local-client" {
		t.Fatalf("executorType fallback = %#v", thread["meta"])
	}
}

func TestNeoCloudThreadReportsPendingInferenceAsWorking(t *testing.T) {
	thread := neoCloudThread(neoCloudThreadSnapshot{
		threadID:         "T-test",
		seq:              1,
		createdMs:        1778170000000,
		agentState:       "idle",
		pendingInference: &neoInferenceInflight{messageID: "M-pending", agentMode: "deep", reasoningEffort: "xhigh"},
		messages: []neoMessage{
			{MessageID: "M-user", Role: "user", Content: []any{map[string]any{"type": "text", "text": "hi"}}, AgentMode: "deep", Seq: 1},
		},
	})

	if thread["state"] != "working" || thread["agentState"] != "working" {
		t.Fatalf("pending inference thread state = state:%#v agentState:%#v", thread["state"], thread["agentState"])
	}
	pending := mapValue(thread["pendingInference"])
	if pending["messageId"] != "M-pending" || pending["agentMode"] != "deep" || pending["reasoningEffort"] != "xhigh" {
		t.Fatalf("pendingInference = %#v", pending)
	}
	if meta := mapValue(thread["meta"]); meta["executorType"] != nil || meta["usesThreadActors"] != true {
		t.Fatalf("pending disconnected actor identity = %#v", meta)
	}
}

func TestNeoUserActorReceivesThreadStatusUpdatedOnThreadActorCreation(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})
	server := httptest.NewServer(http.HandlerFunc(rt.handleHTTP))
	t.Cleanup(server.Close)

	dialer := websocket.Dialer{Subprotocols: []string{"rivet", "rivet_conn_params.%7B%22transport%22%3A%22json-rpc%22%7D", "rivet_encoding.4", "rivet_skip_ready_wait"}}
	wsURL := "ws" + strings.TrimPrefix(server.URL, "http") + "/gateway/userActor/?rvt-method=getOrCreate&rvt-key=user-local"
	conn, resp, err := dialer.Dial(wsURL, nil)
	if err != nil {
		status := 0
		if resp != nil {
			status = resp.StatusCode
		}
		t.Fatalf("gateway userActor websocket dial failed status=%d err=%v", status, err)
	}
	defer conn.Close()

	parentThreadID := "T-019e1046-656d-7132-879f-390ded941c16"
	response, status := rt.localThreadActorManagementResponse(context.Background(), map[string]any{
		"agentMode":      "deep",
		"parentThreadID": parentThreadID,
	}, "")
	if status != http.StatusOK {
		t.Fatalf("create status = %d response=%#v", status, response)
	}
	threadID := stringValue(response["threadId"])
	requireNeoBinaryV7ThreadID(t, threadID)

	deadline := time.Now().Add(2 * time.Second)
	for time.Now().Before(deadline) {
		_ = conn.SetReadDeadline(time.Now().Add(time.Until(deadline)))
		_, payload, err := conn.ReadMessage()
		if err != nil {
			if netErr, ok := err.(net.Error); ok && netErr.Timeout() {
				break
			}
			t.Fatalf("read userActor creation notification: %v", err)
		}
		var frame map[string]any
		if err := json.Unmarshal(payload, &frame); err != nil {
			t.Fatalf("userActor creation notification JSON error: %v", err)
		}
		if frame["method"] != "threadStatusUpdated" {
			continue
		}
		params := mapValue(frame["params"])
		if params["threadId"] != threadID || params["title"] != "Untitled" || params["state"] != "idle" {
			t.Fatalf("threadStatusUpdated params = %#v", params)
		}
		if params["parentThreadID"] != parentThreadID {
			t.Fatalf("parentThreadID = %#v, want %s; params=%#v", params["parentThreadID"], parentThreadID, params)
		}
		if strings.TrimSpace(stringValue(params["lastUserMessageAt"])) == "" {
			t.Fatalf("threadStatusUpdated missing lastUserMessageAt: %#v", params)
		}
		return
	}
	t.Fatal("did not receive threadStatusUpdated notification for created thread")
}

