func TestNeoRuntimeUserActorConnectUsesRivetActionProtocol(t *testing.T) {
	dir := t.TempDir()
	oldStoreDir := neoAmpDataDir
	neoAmpDataDir = func() string { return dir }
	t.Cleanup(func() { neoAmpDataDir = oldStoreDir })

	rt := newNeoRuntime(&config.Config{})
	threadID := "T-019e0e6e-f3f1-7078-b5dd-748f66f8c261"
	threadActor, _ := rt.store.upsert(map[string]any{"name": "threadActor", "key": threadID, "input": map[string]any{"threadId": threadID}}, true)
	threadActor.mu.Lock()
	threadActor.title = "Sidebar visible thread"
	threadActor.agentState = "idle"
	threadActor.messages = []neoMessage{{
		ThreadID:  threadID,
		MessageID: "M-sidebar",
		Role:      "user",
		CreatedAt: "2026-06-16T16:30:00Z",
		Content:   []any{map[string]any{"type": "text", "text": "sidebar test"}},
	}}
	threadActor.mu.Unlock()

	server := httptest.NewServer(http.HandlerFunc(rt.handleHTTP))
	t.Cleanup(server.Close)

	dialer := websocket.Dialer{Subprotocols: []string{"rivet", "rivet_encoding.4", "rivet_conn_params.%7B%22type%22%3A%22user%22%2C%22wsToken%22%3A%22local-neo%22%7D"}}
	wsURL := "ws" + strings.TrimPrefix(server.URL, "http") + "/gateway/userActor/connect?rvt-namespace=default&rvt-method=get&rvt-key=user_01JY3S65TF0JGK80KZ0NA9T18B&rvt-token=local-neo"
	conn, resp, err := dialer.Dial(wsURL, nil)
	if err != nil {
		status := 0
		if resp != nil {
			status = resp.StatusCode
		}
		t.Fatalf("gateway userActor rivet websocket dial failed status=%d err=%v", status, err)
	}
	defer conn.Close()

	_ = conn.SetReadDeadline(time.Now().Add(2 * time.Second))
	messageType, payload, err := conn.ReadMessage()
	if err != nil {
		t.Fatalf("read init frame: %v", err)
	}
	if messageType != websocket.BinaryMessage {
		t.Fatalf("init message type = %d, want binary", messageType)
	}
	initFrame := decodeNeoRivetBareServerFrameForTest(t, payload)
	if initFrame["tag"] != "Init" {
		t.Fatalf("first frame = %#v, want Init", initFrame)
	}
	initVal := mapValue(initFrame["val"])
	if stringValue(initVal["actorId"]) == "" || stringValue(initVal["connectionId"]) == "" {
		t.Fatalf("init val = %#v", initVal)
	}

	if err := conn.WriteMessage(websocket.BinaryMessage, encodeNeoRivetBareActionRequestForTest(t, 1, "getRecentThreads", []any{map[string]any{"limit": 5}})); err != nil {
		t.Fatalf("write action request: %v", err)
	}

	responseFrame := waitForNeoRivetBareFrameTag(t, conn, "ActionResponse", 2*time.Second)
	responseVal := mapValue(responseFrame["val"])
	if responseVal["id"] != uint64(1) {
		t.Fatalf("action response id = %#v", responseVal["id"])
	}
	items := arrayValue(responseVal["output"])
	if len(items) == 0 {
		t.Fatalf("action response output = %#v", responseVal["output"])
	}
	if got := stringValue(mapValue(items[0])["threadId"]); got != threadID {
		t.Fatalf("threadId = %q, want %s", got, threadID)
	}
	if _, exists := mapValue(items[0])["pinned"]; exists {
		t.Fatalf("unpinned realtime summary overrode canonical sidebar state: %#v", items[0])
	}

	if err := conn.WriteMessage(websocket.BinaryMessage, encodeNeoRivetBareActionRequestForTest(t, 2, "setThreadPinned", []any{map[string]any{"threadId": threadID, "pinned": true}})); err != nil {
		t.Fatalf("write setThreadPinned action request: %v", err)
	}
	pinnedEvent := waitForNeoRivetBareEventName(t, conn, "threadStatusUpdated", 2*time.Second)
	pinnedArgs := arrayValue(mapValue(pinnedEvent["val"])["args"])
	if len(pinnedArgs) != 1 || mapValue(pinnedArgs[0])["threadId"] != threadID || mapValue(pinnedArgs[0])["pinned"] != true {
		t.Fatalf("pinned event = %#v", pinnedEvent)
	}
	pinnedResponse := waitForNeoRivetBareFrameTag(t, conn, "ActionResponse", 2*time.Second)
	if got := mapValue(pinnedResponse["val"])["id"]; got != uint64(2) {
		t.Fatalf("setThreadPinned action response id = %#v", got)
	}
	threadActor.mu.Lock()
	pinned := threadActor.pinned
	threadActor.mu.Unlock()
	if !pinned {
		t.Fatal("setThreadPinned action did not update the thread actor")
	}

	threadActor.handle(map[string]any{"type": "agent_state", "state": "working"})
	eventFrame := waitForNeoRivetBareEventName(t, conn, "threadStatusUpdated", 2*time.Second)
	eventVal := mapValue(eventFrame["val"])
	args := arrayValue(eventVal["args"])
	if len(args) != 1 {
		t.Fatalf("event args = %#v, want one summary argument", eventVal["args"])
	}
	summary := mapValue(args[0])
	if summary["threadId"] != threadID || summary["state"] != "working" {
		t.Fatalf("event summary = %#v", summary)
	}
}

func encodeNeoRivetBareActionRequestForTest(t *testing.T, id uint64, name string, args any) []byte {
	t.Helper()
	encodedArgs, err := neoRivetEncodeData(args)
	if err != nil {
		t.Fatalf("encode args: %v", err)
	}
	var body bytes.Buffer
	body.WriteByte(0)
	neoRivetBareWriteVarUint(&body, id)
	neoRivetBareWriteString(&body, name)
	neoRivetBareWriteBytes(&body, encodedArgs)
	return neoRivetBareVersioned(body.Bytes())
}

func decodeNeoRivetBareServerFrameForTest(t *testing.T, payload []byte) map[string]any {
	t.Helper()
	if len(payload) < 3 || binary.LittleEndian.Uint16(payload[:2]) != neoRivetBareVersion {
		t.Fatalf("invalid bare frame header: %x", payload)
	}
	offset := 2
	tag := payload[offset]
	offset++
	switch tag {
	case 0:
		actorID, err := neoRivetBareReadString(payload, &offset)
		if err != nil {
			t.Fatalf("decode init actorID: %v", err)
		}
		connectionID, err := neoRivetBareReadString(payload, &offset)
		if err != nil {
			t.Fatalf("decode init connectionID: %v", err)
		}
		return map[string]any{"tag": "Init", "val": map[string]any{"actorId": actorID, "connectionId": connectionID}}
	case 2:
		id, err := neoRivetBareReadVarUint(payload, &offset)
		if err != nil {
			t.Fatalf("decode action response id: %v", err)
		}
		outputBytes, err := neoRivetBareReadBytes(payload, &offset)
		if err != nil {
			t.Fatalf("decode action response output: %v", err)
		}
		output, err := neoRivetDecodeData(outputBytes)
		if err != nil {
			t.Fatalf("decode action response data: %v", err)
		}
		return map[string]any{"tag": "ActionResponse", "val": map[string]any{"id": id, "output": output}}
	case 3:
		name, err := neoRivetBareReadString(payload, &offset)
		if err != nil {
			t.Fatalf("decode event name: %v", err)
		}
		argBytes, err := neoRivetBareReadBytes(payload, &offset)
		if err != nil {
			t.Fatalf("decode event args: %v", err)
		}
		args, err := neoRivetDecodeData(argBytes)
		if err != nil {
			t.Fatalf("decode event data: %v", err)
		}
		return map[string]any{"tag": "Event", "val": map[string]any{"name": name, "args": args}}
	default:
		t.Fatalf("unexpected bare server tag %d", tag)
		return nil
	}
}

func TestNeoRuntimeSnapshotIncludesToolApprovalQueue(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})
	threadID := "T-019e0e6e-f3f1-7079-b5dd-748f66f8c25d"
	actor, _ := rt.store.upsert(map[string]any{"name": "threadActor", "key": threadID, "input": map[string]any{"threadId": threadID}}, true)
	actor.mu.Lock()
	actor.approvalQueue = []map[string]any{{
		"id":               "TU-child",
		"toolCallId":       "TU-child",
		"toolUseId":        "TU-child",
		"toolName":         "Bash",
		"args":             map[string]any{"cmd": "pwd"},
		"context":          "subagent",
		"parentToolCallId": "TU-parent",
		"subagentToolName": "researcher",
		"timestamp":        123,
		"reason":           "approval needed",
		"toAllow":          []any{"pwd"},
		"ruleSource":       "built-in",
		"matchedRule":      map[string]any{"tool": "Bash", "action": "ask"},
	}}
	actor.mu.Unlock()

	server := httptest.NewServer(http.HandlerFunc(rt.handleHTTP))
	t.Cleanup(server.Close)

	conn := dialNeoActorWebSocket(t, server.URL, threadID)
	defer conn.Close()
	queue := waitForNeoMessageType(t, conn, "tool_approval_queue", 2*time.Second)
	approvals := arrayValue(queue["approvals"])
	if len(approvals) != 1 {
		t.Fatalf("approval queue snapshot = %#v", queue)
	}
	approval := mapValue(approvals[0])
	if stringValue(approval["toolCallId"]) != "TU-child" || stringValue(approval["parentToolCallId"]) != "TU-parent" || stringValue(approval["subagentToolName"]) != "researcher" {
		t.Fatalf("approval queue snapshot approval = %#v", approval)
	}
	if _, exists := approval["toolUseId"]; exists {
		t.Fatalf("approval queue snapshot leaked toolUseId alias: %#v", approval)
	}
}

func TestNeoRuntimeClientResumeIsSocketScoped(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})
	threadID := "T-019e0e6e-f3f1-7080-b5dd-748f66f8c25d"
	actor, _ := rt.store.upsert(map[string]any{"name": "threadActor", "key": threadID, "input": map[string]any{"threadId": threadID}}, true)
	actor.mu.Lock()
	actor.messages = []neoMessage{
		{ThreadID: threadID, MessageID: "M-old", Role: "user", Content: []any{map[string]any{"type": "text", "text": "old"}}, Seq: 1},
		{ThreadID: threadID, MessageID: "M-new", Role: "assistant", Content: []any{map[string]any{"type": "text", "text": "new"}}, Seq: 2},
	}
	actor.replayEvents = []neoReplayEvent{{Seq: 2, Payload: neoMessageAddedPayload(actor.messages[1])}}
	actor.seq = 3
	actor.mu.Unlock()

	server := httptest.NewServer(http.HandlerFunc(rt.handleHTTP))
	t.Cleanup(server.Close)

	conn1 := dialNeoActorWebSocket(t, server.URL, threadID)
	defer conn1.Close()
	waitForNeoMessageType(t, conn1, "agent_state", 2*time.Second)
	conn2 := dialNeoActorWebSocket(t, server.URL, threadID)
	defer conn2.Close()
	waitForNeoMessageType(t, conn2, "agent_state", 2*time.Second)
	waitForNeoMessageType(t, conn1, "observers", 2*time.Second)
	waitForNeoMessageType(t, conn2, "observers", 2*time.Second)

	if err := conn1.WriteJSON(map[string]any{"type": "client_resume", "version": 1}); err != nil {
		t.Fatalf("write client_resume: %v", err)
	}

	sawNew := false
	deadline := time.Now().Add(2 * time.Second)
	for time.Now().Before(deadline) && !sawNew {
		msg, ok := readNeoMessage(t, conn1, time.Until(deadline))
		if !ok {
			break
		}
		if msg["type"] != "message_added" {
			continue
		}
		messageID := stringValue(mapValue(msg["message"])["messageId"])
		if messageID == "M-old" {
			t.Fatalf("resume replayed message at or before requested version: %#v", msg)
		}
		if messageID == "M-new" {
			sawNew = true
		}
	}
	if !sawNew {
		t.Fatal("resume did not replay message newer than requested version")
	}
	if msg, ok := readNeoMessage(t, conn2, 150*time.Millisecond); ok {
		t.Fatalf("client_resume snapshot leaked to another socket: %#v", msg)
	}
}

func TestNeoRuntimeWebSocketFullResumePreservesLargeTranscript(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})
	threadID := "T-019e0e6e-f3f1-7080-b5dd-748f66f8c26c"
	actor, _ := rt.store.upsert(map[string]any{"name": "threadActor", "key": threadID, "input": map[string]any{"threadId": threadID}}, true)
	const messageCount = neoReplayEventLimit + 88
	messages := make([]neoMessage, 0, messageCount)
	for i := 0; i < messageCount; i++ {
		messageID := fmt.Sprintf("M-%022d", i+1)
		toolUseID := fmt.Sprintf("TU-%04d", i/2)
		message := neoMessage{ThreadID: threadID, MessageID: messageID, Seq: i + 1}
		if i%2 == 0 {
			message.Role = "assistant"
			message.Content = []any{map[string]any{"type": "tool_use", "id": toolUseID, "name": "shell_command", "input": map[string]any{"command": "pwd"}}}
		} else {
			message.Role = "user"
			message.Content = []any{map[string]any{"type": "tool_result", "toolUseID": toolUseID, "content": "/workspace"}}
		}
		if i == 0 {
			message.Seq = 0
		}
		messages = append(messages, message)
	}
	cutMessageID := messages[messageCount/2].MessageID
	actor.mu.Lock()
	actor.messages = messages
	actor.compactionRecords = []map[string]any{{"cutMessageId": cutMessageID, "createdAt": "2026-07-12T00:00:00Z"}}
	actor.seq = messageCount + 1
	actor.mu.Unlock()

	server := httptest.NewServer(http.HandlerFunc(rt.handleHTTP))
	t.Cleanup(server.Close)
	conn := dialNeoActorWebSocketWithoutResume(t, server.URL, threadID, "")
	defer conn.Close()
	if err := conn.WriteJSON(map[string]any{"type": "client_resume", "version": 0}); err != nil {
		t.Fatalf("write full client_resume: %v", err)
	}

	messageIndex := 0
	toolUses := 0
	toolResults := 0
	sawCompactionRecord := false
	deadline := time.Now().Add(5 * time.Second)
	for time.Now().Before(deadline) {
		msg, ok := readNeoMessage(t, conn, time.Until(deadline))
		if !ok {
			break
		}
		switch msg["type"] {
		case "message_added":
			if messageIndex >= len(messages) {
				t.Fatalf("full resume sent too many messages: %#v", msg)
			}
			message := mapValue(msg["message"])
			if got, want := stringValue(message["messageId"]), messages[messageIndex].MessageID; got != want {
				t.Fatalf("full resume message %d ID = %q, want %q", messageIndex, got, want)
			}
			for _, rawBlock := range arrayValue(message["content"]) {
				switch stringValue(mapValue(rawBlock)["type"]) {
				case "tool_use":
					toolUses++
				case "tool_result":
					toolResults++
				}
			}
			messageIndex++
		case "compaction_records":
			records := arrayValue(msg["records"])
			sawCompactionRecord = len(records) == 1 && stringValue(mapValue(records[0])["cutMessageId"]) == cutMessageID
		case "agent_state":
			if messageIndex != messageCount || toolUses != messageCount/2 || toolResults != messageCount/2 || !sawCompactionRecord {
				t.Fatalf("full resume completeness messages=%d/%d toolUses=%d toolResults=%d compaction=%v", messageIndex, messageCount, toolUses, toolResults, sawCompactionRecord)
			}
			return
		}
	}
	t.Fatal("timed out waiting for full resume snapshot")
}

func TestNeoRuntimeImportedPositiveResumeFallsBackToCompleteSnapshot(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})
	threadID := "T-019e0e6e-f3f1-7080-b5dd-748f66f8c26e"
	relatedThreadID := "T-019e0e6e-f3f1-7080-b5dd-748f66f8c272"
	actor, _ := rt.store.upsert(map[string]any{"name": "threadActor", "key": threadID, "input": map[string]any{"threadId": threadID}}, true)
	if err := actor.importThreadLocalOnly(map[string]any{
		"id":              threadID,
		"v":               10_000,
		"agentMode":       "deep",
		"reasoningEffort": "xhigh",
		"messages": []any{
			map[string]any{"messageId": "M-0000000000000000000001", "role": "user", "content": []any{map[string]any{"type": "text", "text": "preserve everything"}}},
			map[string]any{"messageId": "M-0000000000000000000002", "role": "assistant", "content": []any{
				map[string]any{"type": "thinking", "thinking": "reasoning", "blockState": "complete"},
				map[string]any{"type": "tool_use", "id": "TU-stable", "name": "shell_command", "input": map[string]any{"command": "go test ./..."}},
			}},
			map[string]any{"messageId": "M-0000000000000000000003", "role": "user", "content": []any{map[string]any{"type": "tool_result", "toolUseID": "TU-stable", "content": "passed"}}},
			map[string]any{"messageId": "M-0000000000000000000004", "role": "info", "content": []any{
				map[string]any{"type": "summary", "summary": map[string]any{"type": "message", "summary": "preserved summary"}},
				map[string]any{"type": "manual_bash_invocation", "args": map[string]any{"cmd": "git status --short"}, "toolRun": map[string]any{"status": "done", "result": "clean"}},
			}},
		},
		"compactionRecords": []any{map[string]any{"cutMessageId": "M-0000000000000000000001", "createdAt": "2026-07-12T00:00:00Z"}},
		"relationships":     []any{map[string]any{"threadID": relatedThreadID, "type": "mention", "role": "parent"}},
	}); err != nil {
		t.Fatalf("import thread: %v", err)
	}
	actor.bumpSeqAndRemember(map[string]any{"type": "resume_probe"})
	if actor.canReplayFrom(9_000) {
		t.Fatal("imported actor unexpectedly proved replay continuity")
	}
	actor.mu.Lock()
	wantHighWater := actor.lastSeqLocked()
	retainedSummary := len(actor.messages) == 4 && len(actor.messages[3].Content) == 2 && neoCompactionSummaryText(mapValue(mapValue(actor.messages[3].Content[0])["summary"])) == "preserved summary"
	actor.mu.Unlock()
	if !retainedSummary {
		t.Fatal("imported summary block was not retained")
	}

	server := httptest.NewServer(http.HandlerFunc(rt.handleHTTP))
	t.Cleanup(server.Close)
	conn := dialNeoActorWebSocketWithoutResume(t, server.URL, threadID, "")
	defer conn.Close()
	if err := conn.WriteJSON(map[string]any{"type": "client_resume", "version": 9_000}); err != nil {
		t.Fatalf("write positive client_resume: %v", err)
	}

	wantIDs := []string{"M-0000000000000000000001", "M-0000000000000000000002", "M-0000000000000000000003", "M-0000000000000000000004"}
	messageIDs := make([]string, 0, len(wantIDs))
	sawThinking := false
	sawToolUse := false
	sawToolResult := false
	sawManualBash := false
	sawCompactionRecord := false
	sawHighWater := false
	deadline := time.Now().Add(3 * time.Second)
	for time.Now().Before(deadline) {
		msg, ok := readNeoMessage(t, conn, time.Until(deadline))
		if !ok {
			break
		}
		switch msg["type"] {
		case "message_added":
			message := mapValue(msg["message"])
			messageIDs = append(messageIDs, stringValue(message["messageId"]))
			for _, rawBlock := range arrayValue(message["content"]) {
				switch stringValue(mapValue(rawBlock)["type"]) {
				case "thinking":
					sawThinking = true
				case "tool_use":
					sawToolUse = stringValue(mapValue(rawBlock)["id"]) == "TU-stable"
				case "tool_result":
					sawToolResult = stringValue(mapValue(rawBlock)["toolUseID"]) == "TU-stable" && stringValue(mapValue(rawBlock)["content"]) == "passed"
				case "manual_bash_invocation":
					sawManualBash = true
				}
			}
		case "compaction_records":
			records := arrayValue(msg["records"])
			sawCompactionRecord = len(records) == 1 && stringValue(mapValue(records[0])["cutMessageId"]) == wantIDs[0]
		case "error_cleared":
			sawHighWater = numberFrom(msg["seq"]) == wantHighWater
		case "agent_state":
			if !reflect.DeepEqual(messageIDs, wantIDs) || !sawThinking || !sawToolUse || !sawToolResult || !sawManualBash || !sawCompactionRecord || !sawHighWater {
				t.Fatalf("fallback completeness ids=%v thinking=%v toolUse=%v toolResult=%v manualBash=%v compaction=%v highWater=%v", messageIDs, sawThinking, sawToolUse, sawToolResult, sawManualBash, sawCompactionRecord, sawHighWater)
			}
			return
		}
	}
	t.Fatal("timed out waiting for imported fallback snapshot")
}

func TestNeoRuntimeImportedPositiveResumePreservesTranscriptBeyondReplayLimit(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})
	threadID := "T-019e0e6e-f3f1-7080-b5dd-748f66f8c26f"
	actor, _ := rt.store.upsert(map[string]any{"name": "threadActor", "key": threadID, "input": map[string]any{"threadId": threadID}}, true)
	const messageCount = neoReplayEventLimit + 88
	messages := make([]any, messageCount)
	for index := range messages {
		messages[index] = map[string]any{
			"messageId": fmt.Sprintf("M-%022d", index+1),
			"role":      "assistant",
			"content":   []any{map[string]any{"type": "text", "text": fmt.Sprintf("message %d", index+1)}},
		}
	}
	if err := actor.importThreadLocalOnly(map[string]any{"id": threadID, "v": 50_000, "agentMode": "deep", "messages": messages}); err != nil {
		t.Fatalf("import thread: %v", err)
	}

	server := httptest.NewServer(http.HandlerFunc(rt.handleHTTP))
	t.Cleanup(server.Close)
	conn := dialNeoActorWebSocketWithoutResume(t, server.URL, threadID, "")
	defer conn.Close()
	if err := conn.WriteJSON(map[string]any{"type": "client_resume", "version": 49_000}); err != nil {
		t.Fatalf("write positive client_resume: %v", err)
	}

	messageCountReceived := 0
	sawHighWater := false
	deadline := time.Now().Add(5 * time.Second)
	for time.Now().Before(deadline) {
		msg, ok := readNeoMessage(t, conn, time.Until(deadline))
		if !ok {
			break
		}
		switch msg["type"] {
		case "message_added":
			messageCountReceived++
		case "error_cleared":
			sawHighWater = numberFrom(msg["seq"]) == 50_000
		case "agent_state":
			if messageCountReceived != messageCount || !sawHighWater {
				t.Fatalf("fallback messages = %d, want %d; highWater=%v", messageCountReceived, messageCount, sawHighWater)
			}
			return
		}
	}
	t.Fatal("timed out waiting for large imported fallback snapshot")
}

func TestNeoRuntimeImportedExactResumeSkipsCompleteSnapshot(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})
	threadID := "T-imported-exact-resume"
	actor, _ := rt.store.upsert(map[string]any{"name": "threadActor", "key": threadID, "input": map[string]any{"threadId": threadID}}, true)
	if err := actor.importThreadLocalOnly(map[string]any{
		"id":        threadID,
		"v":         10_000,
		"agentMode": "smart",
		"messages": []any{
			map[string]any{"messageId": "M-imported", "role": "user", "content": []any{map[string]any{"type": "text", "text": "already loaded locally"}}},
		},
	}); err != nil {
		t.Fatalf("import thread: %v", err)
	}
	if !actor.canReplayFrom(10_000) {
		t.Fatal("imported actor rejected its exact high-water version")
	}

	server := httptest.NewServer(http.HandlerFunc(rt.handleHTTP))
	t.Cleanup(server.Close)
	conn := dialNeoActorWebSocketWithoutResume(t, server.URL, threadID, "")
	defer conn.Close()
	if err := conn.WriteJSON(map[string]any{"type": "client_resume", "version": 10_000}); err != nil {
		t.Fatalf("write exact client_resume: %v", err)
	}

	sawHighWater := false
	deadline := time.Now().Add(2 * time.Second)
	for time.Now().Before(deadline) {
		msg, ok := readNeoMessage(t, conn, time.Until(deadline))
		if !ok {
			break
		}
		if msg["type"] == "message_added" {
			t.Fatalf("exact resume replayed an imported message: %#v", msg)
		}
		if msg["type"] == "error_set" {
			t.Fatalf("exact resume restored an unexpected active error: %#v", msg)
		}
		if msg["type"] == "error_cleared" {
			sawHighWater = numberFrom(msg["seq"]) == 10_000
		}
		if msg["type"] == "agent_state" {
			if !sawHighWater {
				t.Fatal("exact resume did not advertise its high-water version")
			}
			if _, ok := msg["seq"]; ok {
				t.Fatalf("agent_state included unsupported seq: %#v", msg)
			}
			return
		}
	}
	t.Fatal("timed out waiting for exact-resume agent_state")
}

