func TestNeoThreadFeatureFramesMatchBinarySchema(t *testing.T) {
	feature, enabled, ok := normalizeNeoClientThreadFeature(map[string]any{"feature": "fast", "enabled": true})
	if !ok || feature != "fast" || !enabled {
		t.Fatalf("valid thread feature update = feature:%q enabled:%v ok:%v", feature, enabled, ok)
	}
	for _, invalid := range []map[string]any{
		{"enabled": true},
		{"feature": "slow", "enabled": true},
		{"feature": "fast", "enabled": "true"},
	} {
		if _, _, ok := normalizeNeoClientThreadFeature(invalid); ok {
			t.Fatalf("invalid thread feature update was accepted: %#v", invalid)
		}
	}

	features, ok := normalizeNeoThreadFeatures([]any{"fast", "fast"})
	if !ok || !reflect.DeepEqual(features, []string{"fast"}) {
		t.Fatalf("thread features = %#v ok=%v, want deduplicated fast feature", features, ok)
	}
	for _, invalid := range []any{"fast", []any{"slow"}, []any{true}} {
		if _, ok := normalizeNeoThreadFeatures(invalid); ok {
			t.Fatalf("invalid thread features were accepted: %#v", invalid)
		}
	}
}

func TestNeoActorPresenceIsEphemeral(t *testing.T) {
	useTempNeoThreadStore(t)
	enabled := true
	rt := newNeoRuntime(&config.Config{AmpCode: config.AmpCode{NeoLocalRuntime: config.AmpNeoLocalRuntime{Enabled: &enabled}}})
	t.Cleanup(func() { rt.store.disposeAll(true, "test done", false) })
	threadID := "T-019fa4a6-f38a-743a-af9d-bdfaf2b3e151"
	actor := rt.store.ensureThreadActor(threadID)
	actor.mu.Lock()
	wantSeq := actor.seq
	wantRevision := actor.measurements.revision
	actor.mu.Unlock()

	actor.handle(map[string]any{"type": "client_set_presence", "present": true})
	actor.handle(map[string]any{"type": "client_set_presence", "present": false})
	actor.handle(map[string]any{"type": "client_set_presence", "present": "true"})

	actor.mu.Lock()
	defer actor.mu.Unlock()
	if actor.seq != wantSeq || actor.measurements.revision != wantRevision || len(actor.replayEvents) != 0 || len(actor.threadFeatures) != 0 {
		t.Fatalf("presence created persistent actor state: seq=%d revision=%d replay=%#v features=%#v", actor.seq, actor.measurements.revision, actor.replayEvents, actor.threadFeatures)
	}
	if _, ok := loadNeoThreadFromDir(threadID, rt.threadDir); ok {
		t.Fatal("presence created a persisted thread snapshot")
	}
}

func TestNeoActorThreadFeaturesAreIdempotentAndPersisted(t *testing.T) {
	useTempNeoThreadStore(t)
	enabled := true
	rt := newNeoRuntime(&config.Config{AmpCode: config.AmpCode{NeoLocalRuntime: config.AmpNeoLocalRuntime{Enabled: &enabled}}})
	t.Cleanup(func() { rt.store.disposeAll(true, "test done", false) })
	threadID := "T-019fa4a6-f38a-743a-af9d-bdfaf2b3e152"
	actor := rt.store.ensureThreadActor(threadID)
	featureFrames := make([]map[string]any, 0, 2)
	socket := &neoSocket{writeMessage: func(_ int, payload []byte) error {
		var frame map[string]any
		if err := json.Unmarshal(payload, &frame); err != nil {
			return err
		}
		if stringValue(frame["type"]) == "thread_features" {
			featureFrames = append(featureFrames, frame)
		}
		return nil
	}}
	actor.mu.Lock()
	actor.sockets[socket] = struct{}{}
	wantSeq := actor.seq
	actor.mu.Unlock()

	actor.handle(map[string]any{"type": "client_update_thread_feature", "feature": "slow", "enabled": true})
	actor.handle(map[string]any{"type": "client_update_thread_feature", "feature": "fast", "enabled": "true"})
	if len(featureFrames) != 0 {
		t.Fatalf("invalid feature updates emitted frames: %#v", featureFrames)
	}

	actor.handle(map[string]any{"type": "client_update_thread_feature", "feature": "fast", "enabled": true})
	waitForNeoActorSyncIdle(t, actor)
	actor.mu.Lock()
	revisionAfterEnable := actor.measurements.revision
	actor.mu.Unlock()
	actor.handle(map[string]any{"type": "client_update_thread_feature", "feature": "fast", "enabled": true})
	actor.handle(map[string]any{"type": "thread_features", "features": []any{"fast"}})
	waitForNeoActorSyncIdle(t, actor)

	actor.mu.Lock()
	if !reflect.DeepEqual(actor.threadFeatures, []string{"fast"}) || actor.seq != wantSeq || actor.measurements.revision != revisionAfterEnable || len(actor.replayEvents) != 0 {
		actor.mu.Unlock()
		t.Fatalf("idempotent feature replay changed actor state: features=%#v seq=%d revision=%d replay=%#v", actor.threadFeatures, actor.seq, actor.measurements.revision, actor.replayEvents)
	}
	actor.mu.Unlock()
	if len(featureFrames) != 1 || !reflect.DeepEqual(arrayValue(featureFrames[0]["features"]), []any{"fast"}) {
		t.Fatalf("feature enable frames = %#v, want one authoritative fast state", featureFrames)
	}

	stored, ok := loadNeoThreadFromDir(threadID, rt.threadDir)
	if !ok || !reflect.DeepEqual(arrayValue(stored["features"]), []any{"fast"}) {
		t.Fatalf("persisted thread features = %#v ok=%v", stored["features"], ok)
	}
	restored := newNeoActor(rt, "actor-restored-features", "threadActor", threadID, threadID, neoActorRecord("actor-restored-features", "threadActor", threadID), nil)
	if err := restored.importThreadLocalOnly(stored); err != nil {
		t.Fatalf("import persisted thread features: %v", err)
	}
	restored.mu.Lock()
	restoredFeatures := append([]string(nil), restored.threadFeatures...)
	hasLocalState := restored.hasLocalThreadStateLocked()
	if !reflect.DeepEqual(restoredFeatures, []string{"fast"}) || !hasLocalState {
		restored.mu.Unlock()
		t.Fatalf("restored thread features = %#v localState=%v", restoredFeatures, hasLocalState)
	}
	restored.mu.Unlock()

	actor.handle(map[string]any{"type": "client_update_thread_feature", "feature": "fast", "enabled": false})
	actor.handle(map[string]any{"type": "client_update_thread_feature", "feature": "fast", "enabled": false})
	waitForNeoActorSyncIdle(t, actor)
	if len(featureFrames) != 2 || len(arrayValue(featureFrames[1]["features"])) != 0 {
		t.Fatalf("feature disable frames = %#v, want one authoritative empty state", featureFrames)
	}
}

func TestNeoActorThreadFeatureSnapshotsCoverInitialAndResume(t *testing.T) {
	capture := func(actor *neoActor, sinceSeq int) map[string]any {
		t.Helper()
		var featureFrame map[string]any
		socket := &neoSocket{writeMessage: func(_ int, payload []byte) error {
			var frame map[string]any
			if err := json.Unmarshal(payload, &frame); err != nil {
				return err
			}
			if stringValue(frame["type"]) == "thread_features" {
				featureFrame = frame
			}
			return nil
		}}
		if !actor.sendSnapshot(socket, sinceSeq) {
			t.Fatalf("thread feature snapshot since seq %d was not sent", sinceSeq)
		}
		if featureFrame == nil {
			t.Fatalf("thread feature snapshot since seq %d omitted thread_features", sinceSeq)
		}
		return featureFrame
	}

	empty := newNeoActor(nil, "actor-empty-features", "threadActor", "T-empty-features", "T-empty-features", neoActorRecord("actor-empty-features", "threadActor", "T-empty-features"), nil)
	emptyFrame := capture(empty, 0)
	if features, ok := emptyFrame["features"].([]any); !ok || len(features) != 0 {
		t.Fatalf("initial thread features = %#v, want []", emptyFrame["features"])
	}

	resumed := newNeoActor(nil, "actor-resumed-features", "threadActor", "T-resumed-features", "T-resumed-features", neoActorRecord("actor-resumed-features", "threadActor", "T-resumed-features"), nil)
	resumed.mu.Lock()
	resumed.threadFeatures = []string{"fast"}
	resumed.seq = 5
	resumed.replayContinuityKnown = true
	resumed.replayFloorSeq = 5
	resumed.mu.Unlock()
	if features := arrayValue(capture(resumed, 5)["features"]); !reflect.DeepEqual(features, []any{"fast"}) {
		t.Fatalf("resumed thread features = %#v, want fast", features)
	}
}

func TestNeoRuntimeFilesystemBridgeNormalizesBothDirections(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})
	server := httptest.NewServer(http.HandlerFunc(rt.handleHTTP))
	t.Cleanup(server.Close)

	threadID := "T-019e0e6e-f3f1-7081-b5dd-748f66f8c25e"
	client := dialNeoActorWebSocket(t, server.URL, threadID)
	defer client.Close()
	executor := dialNeoActorWebSocket(t, server.URL, threadID)
	defer executor.Close()
	waitForNeoMessageType(t, client, "agent_state", 2*time.Second)
	waitForNeoMessageType(t, executor, "agent_state", 2*time.Second)

	if err := executor.WriteJSON(map[string]any{"type": "executor_filesystem_read_file", "requestId": "fs-1", "uri": "file:///tmp/a.txt"}); err != nil {
		t.Fatalf("write executor filesystem request: %v", err)
	}
	request := waitForNeoMessageType(t, client, "client_filesystem_read_file", 2*time.Second)
	if request["requestId"] != "fs-1" || request["uri"] != "file:///tmp/a.txt" {
		t.Fatalf("filesystem request = %#v", request)
	}
	if _, exists := request["maxBytes"]; exists {
		t.Fatalf("filesystem request kept non-binary maxBytes field: %#v", request)
	}

	if err := client.WriteJSON(map[string]any{"type": "client_filesystem_read_file_result", "requestId": "fs-1", "ok": true, "contentBase64": "aGVsbG8="}); err != nil {
		t.Fatalf("write client filesystem result: %v", err)
	}
	result := waitForNeoMessageType(t, executor, "executor_filesystem_read_file_result", 2*time.Second)
	if result["requestId"] != "fs-1" || result["ok"] != true || result["contentBase64"] != "aGVsbG8=" {
		t.Fatalf("filesystem result = %#v", result)
	}

	if err := client.WriteJSON(map[string]any{"type": "client_filesystem_write_file", "requestId": "write-1", "uri": "file:///tmp/a.txt", "contentBase64": "aGVsbG8="}); err != nil {
		t.Fatalf("write client filesystem write request: %v", err)
	}
	writeRequest := waitForNeoMessageType(t, executor, "executor_filesystem_write_file", 2*time.Second)
	if writeRequest["requestId"] != "write-1" || writeRequest["uri"] != "file:///tmp/a.txt" || writeRequest["contentBase64"] != "aGVsbG8=" {
		t.Fatalf("filesystem write request = %#v", writeRequest)
	}
	if err := executor.WriteJSON(map[string]any{"type": "executor_filesystem_write_file_result", "requestId": "write-1", "ok": true}); err != nil {
		t.Fatalf("write executor filesystem write result: %v", err)
	}
	writeResult := waitForNeoMessageType(t, client, "client_filesystem_write_file_result", 2*time.Second)
	if writeResult["requestId"] != "write-1" || writeResult["ok"] != true {
		t.Fatalf("filesystem write result = %#v", writeResult)
	}

	if err := executor.WriteJSON(map[string]any{"type": "executor_filesystem_write_file", "requestId": "write-2", "uri": "file:///tmp/b.txt", "contentBase64": "d29ybGQ="}); err != nil {
		t.Fatalf("write executor filesystem write request: %v", err)
	}
	reverseWriteRequest := waitForNeoMessageType(t, client, "client_filesystem_write_file", 2*time.Second)
	if reverseWriteRequest["requestId"] != "write-2" || reverseWriteRequest["contentBase64"] != "d29ybGQ=" {
		t.Fatalf("reverse filesystem write request = %#v", reverseWriteRequest)
	}
	if err := client.WriteJSON(map[string]any{"type": "client_filesystem_write_file_result", "requestId": "write-2", "ok": false, "error": map[string]any{"code": "TOO_LARGE", "message": "too large"}}); err != nil {
		t.Fatalf("write client filesystem write result: %v", err)
	}
	reverseWriteResult := waitForNeoMessageType(t, executor, "executor_filesystem_write_file_result", 2*time.Second)
	if reverseWriteResult["requestId"] != "write-2" || stringValue(mapValue(reverseWriteResult["error"])["code"]) != "TOO_LARGE" {
		t.Fatalf("reverse filesystem write result = %#v", reverseWriteResult)
	}

	if err := client.WriteJSON(map[string]any{"type": "client_filesystem_delete", "requestId": "delete-1", "uri": "file:///tmp/a.txt", "recursive": true}); err != nil {
		t.Fatalf("write client filesystem delete request: %v", err)
	}
	deleteRequest := waitForNeoMessageType(t, executor, "executor_filesystem_delete", 2*time.Second)
	if deleteRequest["requestId"] != "delete-1" || deleteRequest["uri"] != "file:///tmp/a.txt" || deleteRequest["recursive"] != true {
		t.Fatalf("filesystem delete request = %#v", deleteRequest)
	}
	if err := executor.WriteJSON(map[string]any{"type": "executor_filesystem_delete_result", "requestId": "delete-1", "ok": true}); err != nil {
		t.Fatalf("write executor filesystem delete result: %v", err)
	}
	deleteResult := waitForNeoMessageType(t, client, "client_filesystem_delete_result", 2*time.Second)
	if deleteResult["requestId"] != "delete-1" || deleteResult["ok"] != true {
		t.Fatalf("filesystem delete result = %#v", deleteResult)
	}

	if err := executor.WriteJSON(map[string]any{"type": "executor_filesystem_delete", "requestId": "delete-2", "uri": "file:///tmp/b.txt", "recursive": false}); err != nil {
		t.Fatalf("write executor filesystem delete request: %v", err)
	}
	reverseDeleteRequest := waitForNeoMessageType(t, client, "client_filesystem_delete", 2*time.Second)
	if reverseDeleteRequest["requestId"] != "delete-2" || reverseDeleteRequest["uri"] != "file:///tmp/b.txt" || reverseDeleteRequest["recursive"] != false {
		t.Fatalf("reverse filesystem delete request = %#v", reverseDeleteRequest)
	}
	if err := client.WriteJSON(map[string]any{"type": "client_filesystem_delete_result", "requestId": "delete-2", "ok": false, "error": map[string]any{"code": "NOT_FOUND", "message": "not found"}}); err != nil {
		t.Fatalf("write client filesystem delete result: %v", err)
	}
	reverseDeleteResult := waitForNeoMessageType(t, executor, "executor_filesystem_delete_result", 2*time.Second)
	if reverseDeleteResult["requestId"] != "delete-2" || stringValue(mapValue(reverseDeleteResult["error"])["code"]) != "NOT_FOUND" {
		t.Fatalf("reverse filesystem delete result = %#v", reverseDeleteResult)
	}

	clientV2Requests := []struct {
		message      map[string]any
		outboundType string
	}{
		{map[string]any{"type": "client_filesystem_read_directory_v2", "requestId": "v2-client-dir", "path": "src"}, "executor_filesystem_read_directory_v2"},
		{map[string]any{"type": "client_filesystem_read_file_v2", "requestId": "v2-client-read", "path": "src/main.go", "range": map[string]any{"offset": 0, "maxBytes": neoFilesystemReadChunkMaxBytes}}, "executor_filesystem_read_file_v2"},
		{map[string]any{"type": "client_filesystem_write_file_v2", "requestId": "v2-client-write", "path": "src/main.go", "contentBase64": "YQ=="}, "executor_filesystem_write_file_v2"},
		{map[string]any{"type": "client_filesystem_write_file_v3", "requestId": "v3-client-write", "path": "src/main.go", "contentBase64": "YQ==", "overwrite": false}, "executor_filesystem_write_file_v3"},
		{map[string]any{"type": "client_filesystem_delete_v2", "requestId": "v2-client-delete", "path": "tmp", "recursive": true}, "executor_filesystem_delete_v2"},
	}
	for _, test := range clientV2Requests {
		if err := client.WriteJSON(test.message); err != nil {
			t.Fatalf("write %s: %v", test.message["type"], err)
		}
		got := waitForNeoMessageType(t, executor, test.outboundType, 2*time.Second)
		for key, want := range test.message {
			if key == "type" {
				continue
			}
			if key == "range" {
				gotRange := mapValue(got[key])
				wantRange := mapValue(want)
				if numberFrom(gotRange["offset"]) != numberFrom(wantRange["offset"]) || numberFrom(gotRange["maxBytes"]) != numberFrom(wantRange["maxBytes"]) {
					t.Fatalf("%s range = %#v, want %#v: %#v", test.outboundType, gotRange, wantRange, got)
				}
				continue
			}
			if !reflect.DeepEqual(got[key], want) {
				t.Fatalf("%s field %s = %#v, want %#v: %#v", test.outboundType, key, got[key], want, got)
			}
		}
		if _, exists := got["uri"]; exists {
			t.Fatalf("%s added legacy uri: %#v", test.outboundType, got)
		}
	}
	if err := executor.WriteJSON(map[string]any{"type": "executor_filesystem_write_file_result", "requestId": "v3-client-write", "ok": false, "error": map[string]any{"code": "ALREADY_EXISTS", "message": "already exists"}}); err != nil {
		t.Fatalf("write filesystem v3 conflict result: %v", err)
	}
	v3ClientConflict := waitForNeoMessageType(t, client, "client_filesystem_write_file_result", 2*time.Second)
	if stringValue(mapValue(v3ClientConflict["error"])["code"]) != "ALREADY_EXISTS" {
		t.Fatalf("filesystem v3 conflict result = %#v", v3ClientConflict)
	}
	if err := executor.WriteJSON(map[string]any{"type": "executor_filesystem_read_file_result", "requestId": "v2-client-read", "ok": true, "contentBase64": "YQ==", "fileSizeBytes": 4096}); err != nil {
		t.Fatalf("write filesystem v2 result: %v", err)
	}
	v2ClientResult := waitForNeoMessageType(t, client, "client_filesystem_read_file_result", 2*time.Second)
	if numberFrom(v2ClientResult["fileSizeBytes"]) != 4096 {
		t.Fatalf("filesystem v2 result lost fileSizeBytes: %#v", v2ClientResult)
	}

	executorV2Requests := []struct {
		message      map[string]any
		outboundType string
	}{
		{map[string]any{"type": "executor_filesystem_read_directory_v2", "requestId": "v2-executor-dir", "path": "src"}, "client_filesystem_read_directory_v2"},
		{map[string]any{"type": "executor_filesystem_read_file_v2", "requestId": "v2-executor-read", "path": "src/main.go", "range": map[string]any{"offset": 4, "maxBytes": 1024}}, "client_filesystem_read_file_v2"},
		{map[string]any{"type": "executor_filesystem_write_file_v2", "requestId": "v2-executor-write", "path": "src/main.go", "contentBase64": "Yg=="}, "client_filesystem_write_file_v2"},
		{map[string]any{"type": "executor_filesystem_write_file_v3", "requestId": "v3-executor-write", "path": "src/main.go", "contentBase64": "Yg==", "overwrite": true}, "client_filesystem_write_file_v3"},
		{map[string]any{"type": "executor_filesystem_delete_v2", "requestId": "v2-executor-delete", "path": "tmp", "recursive": false}, "client_filesystem_delete_v2"},
	}
	for _, test := range executorV2Requests {
		if err := executor.WriteJSON(test.message); err != nil {
			t.Fatalf("write %s: %v", test.message["type"], err)
		}
		got := waitForNeoMessageType(t, client, test.outboundType, 2*time.Second)
		for key, want := range test.message {
			if key == "type" {
				continue
			}
			if key == "range" {
				gotRange := mapValue(got[key])
				wantRange := mapValue(want)
				if numberFrom(gotRange["offset"]) != numberFrom(wantRange["offset"]) || numberFrom(gotRange["maxBytes"]) != numberFrom(wantRange["maxBytes"]) {
					t.Fatalf("%s range = %#v, want %#v: %#v", test.outboundType, gotRange, wantRange, got)
				}
				continue
			}
			if !reflect.DeepEqual(got[key], want) {
				t.Fatalf("%s field %s = %#v, want %#v: %#v", test.outboundType, key, got[key], want, got)
			}
		}
		if _, exists := got["uri"]; exists {
			t.Fatalf("%s added legacy uri: %#v", test.outboundType, got)
		}
	}
	if err := client.WriteJSON(map[string]any{"type": "client_filesystem_write_file_result", "requestId": "v3-executor-write", "ok": false, "error": map[string]any{"code": "ALREADY_EXISTS", "message": "already exists"}}); err != nil {
		t.Fatalf("write reverse filesystem v3 conflict result: %v", err)
	}
	v3ExecutorConflict := waitForNeoMessageType(t, executor, "executor_filesystem_write_file_result", 2*time.Second)
	if stringValue(mapValue(v3ExecutorConflict["error"])["code"]) != "ALREADY_EXISTS" {
		t.Fatalf("reverse filesystem v3 conflict result = %#v", v3ExecutorConflict)
	}
	if err := client.WriteJSON(map[string]any{"type": "client_filesystem_read_file_result", "requestId": "v2-executor-read", "ok": true, "contentBase64": "Yg==", "fileSizeBytes": 8192}); err != nil {
		t.Fatalf("write reverse filesystem v2 result: %v", err)
	}
	v2ExecutorResult := waitForNeoMessageType(t, executor, "executor_filesystem_read_file_result", 2*time.Second)
	if numberFrom(v2ExecutorResult["fileSizeBytes"]) != 8192 {
		t.Fatalf("reverse filesystem v2 result lost fileSizeBytes: %#v", v2ExecutorResult)
	}

	oversizedContent := base64.StdEncoding.EncodeToString(make([]byte, neoFilesystemWriteMaxBytes+1))
	if err := client.WriteJSON(map[string]any{"type": "client_filesystem_write_file", "requestId": "write-3", "uri": "file:///tmp/c.txt", "contentBase64": oversizedContent}); err != nil {
		t.Fatalf("write oversized client filesystem request: %v", err)
	}
	oversizedClientResult := waitForNeoMessageType(t, client, "client_filesystem_write_file_result", 2*time.Second)
	if oversizedClientResult["requestId"] != "write-3" || stringValue(mapValue(oversizedClientResult["error"])["code"]) != "TOO_LARGE" {
		t.Fatalf("oversized client filesystem result = %#v", oversizedClientResult)
	}

	if err := executor.WriteJSON(map[string]any{"type": "executor_filesystem_write_file", "requestId": "write-4", "uri": "file:///tmp/d.txt", "contentBase64": oversizedContent}); err != nil {
		t.Fatalf("write oversized executor filesystem request: %v", err)
	}
	oversizedExecutorResult := waitForNeoMessageType(t, executor, "executor_filesystem_write_file_result", 2*time.Second)
	if oversizedExecutorResult["requestId"] != "write-4" || stringValue(mapValue(oversizedExecutorResult["error"])["code"]) != "TOO_LARGE" {
		t.Fatalf("oversized executor filesystem result = %#v", oversizedExecutorResult)
	}

	if err := client.WriteJSON(map[string]any{"type": "client_orb_services_ensure", "requestId": "orb-1"}); err != nil {
		t.Fatalf("write client Orb request: %v", err)
	}
	orbRequest := waitForNeoMessageType(t, executor, "executor_orb_services_ensure", 2*time.Second)
	if orbRequest["requestId"] != "orb-1" {
		t.Fatalf("Orb request = %#v", orbRequest)
	}
	orbPayload := map[string]any{
		"ok":       true,
		"noConfig": false,
		"services": []any{map[string]any{
			"name":         "preview",
			"ok":           true,
			"port":         3000,
			"baseURL":      "http://127.0.0.1:3000",
			"portals":      []any{map[string]any{"title": "Preview", "url": "http://127.0.0.1:3000"}},
			"healthStatus": 200,
		}},
	}
	if err := executor.WriteJSON(map[string]any{"type": "executor_orb_services_ensure_result", "requestId": "orb-1", "result": orbPayload}); err != nil {
		t.Fatalf("write executor Orb result: %v", err)
	}
	orbResult := waitForNeoMessageType(t, client, "client_orb_services_ensure_result", 2*time.Second)
	if orbResult["requestId"] != "orb-1" || mapValue(orbResult["result"])["ok"] != true {
		t.Fatalf("Orb result = %#v", orbResult)
	}

	if err := executor.WriteJSON(map[string]any{"type": "executor_orb_services_ensure", "requestId": "orb-2"}); err != nil {
		t.Fatalf("write executor Orb request: %v", err)
	}
	reverseOrbRequest := waitForNeoMessageType(t, client, "client_orb_services_ensure", 2*time.Second)
	if reverseOrbRequest["requestId"] != "orb-2" {
		t.Fatalf("reverse Orb request = %#v", reverseOrbRequest)
	}
	if err := client.WriteJSON(map[string]any{"type": "client_orb_services_ensure_result", "requestId": "orb-2", "result": orbPayload}); err != nil {
		t.Fatalf("write client Orb result: %v", err)
	}
	reverseOrbResult := waitForNeoMessageType(t, executor, "executor_orb_services_ensure_result", 2*time.Second)
	if reverseOrbResult["requestId"] != "orb-2" || mapValue(reverseOrbResult["result"])["ok"] != true {
		t.Fatalf("reverse Orb result = %#v", reverseOrbResult)
	}
}

func prepareNeoTerminalTmuxSession(t *testing.T, threadID, workingDirectory string) {
	t.Helper()
	command, err := exec.LookPath("tmux")
	if err != nil {
		t.Skip("tmux is not installed")
	}
	sessionName := neoTerminalTmuxSessionName(threadID)
	_ = exec.Command(command, "-L", neoTerminalTmuxSocket, "kill-session", "-t", sessionName).Run()
	if output, err := exec.Command(command, "-L", neoTerminalTmuxSocket, "new-session", "-d", "-s", sessionName, "-c", workingDirectory).CombinedOutput(); err != nil {
		t.Fatalf("create terminal tmux session: %v: %s", err, strings.TrimSpace(string(output)))
	}
	t.Cleanup(func() {
		_ = exec.Command(command, "-L", neoTerminalTmuxSocket, "kill-session", "-t", sessionName).Run()
	})
}

func TestNeoRuntimeTerminalBridgeRetypesBothDirections(t *testing.T) {
	if bridged, ok := neoTerminalBridgeType("client_terminal_invalid"); ok || bridged != "" {
		t.Fatalf("invalid terminal bridge = %q ok=%v", bridged, ok)
	}

	threadID := "T-019f7a11-0000-4000-8000-000000000036"
	workingDirectory := t.TempDir()
	prepareNeoTerminalTmuxSession(t, threadID, workingDirectory)
	rt := newNeoRuntime(&config.Config{})
	actor := rt.store.ensureThreadActor(threadID)
	actor.mu.Lock()
	actor.environment = map[string]any{"workingDirectory": workingDirectory}
	actor.mu.Unlock()
	server := httptest.NewServer(http.HandlerFunc(rt.handleHTTP))
	t.Cleanup(server.Close)

	client := dialNeoActorWebSocket(t, server.URL, threadID)
	defer client.Close()
	identityObserver := dialNeoActorWebSocket(t, server.URL, threadID)
	defer identityObserver.Close()
	executor := dialNeoActorWebSocket(t, server.URL, threadID)
	defer executor.Close()
	waitForNeoMessageType(t, client, "agent_state", 2*time.Second)
	waitForNeoMessageType(t, identityObserver, "agent_state", 2*time.Second)
	waitForNeoMessageType(t, executor, "agent_state", 2*time.Second)
	if err := executor.WriteJSON(map[string]any{"type": "executor_connected", "executorId": "active-executor"}); err != nil {
		t.Fatalf("write executor_connected: %v", err)
	}
	waitForNeoMessageType(t, executor, "executor_connected", 2*time.Second)
	assertNoNeoMessageType(t, identityObserver, "executor_connected", 100*time.Millisecond)

	for i, suffix := range []string{"open", "input", "resize", "close", "output", "exit"} {
		clientType := "client_terminal_" + suffix
		executorType := "executor_terminal_" + suffix
		clientMarker := "client-" + suffix
		if err := client.WriteJSON(map[string]any{"type": clientType, "terminalId": clientMarker, "marker": clientMarker, "ordinal": i}); err != nil {
			t.Fatalf("write %s: %v", clientType, err)
		}
		fromClient := waitForNeoMessageType(t, executor, executorType, 2*time.Second)
		if fromClient["terminalId"] != clientMarker || fromClient["marker"] != clientMarker || numberFrom(fromClient["ordinal"]) != i {
			t.Fatalf("%s bridge = %#v", clientType, fromClient)
		}

		executorMarker := "executor-" + suffix
		if err := executor.WriteJSON(map[string]any{"type": executorType, "terminalId": executorMarker, "marker": executorMarker, "ordinal": i}); err != nil {
			t.Fatalf("write %s: %v", executorType, err)
		}
		fromExecutor := waitForNeoMessageType(t, client, clientType, 2*time.Second)
		if fromExecutor["terminalId"] != executorMarker || fromExecutor["marker"] != executorMarker || numberFrom(fromExecutor["ordinal"]) != i {
			t.Fatalf("%s bridge = %#v", executorType, fromExecutor)
		}
	}
}

func TestNeoRuntimeTerminalBridgeUsesActiveExecutor(t *testing.T) {
	threadID := "T-019f7a11-0000-4000-8000-000000000037"
	workingDirectory := t.TempDir()
	prepareNeoTerminalTmuxSession(t, threadID, workingDirectory)
	rt := newNeoRuntime(&config.Config{})
	actor := rt.store.ensureThreadActor(threadID)
	actor.mu.Lock()
	actor.environment = map[string]any{"workingDirectory": workingDirectory}
	actor.mu.Unlock()
	server := httptest.NewServer(http.HandlerFunc(rt.handleHTTP))
	t.Cleanup(server.Close)

	client := dialNeoActorWebSocket(t, server.URL, threadID)
	defer client.Close()
	probeClient := dialNeoActorWebSocket(t, server.URL, threadID)
	defer probeClient.Close()
	activeExecutor := dialNeoActorWebSocket(t, server.URL, threadID)
	defer activeExecutor.Close()
	extraSocket := dialNeoActorWebSocket(t, server.URL, threadID)
	defer extraSocket.Close()
	waitForNeoMessageType(t, client, "agent_state", 2*time.Second)
	waitForNeoMessageType(t, probeClient, "agent_state", 2*time.Second)
	waitForNeoMessageType(t, activeExecutor, "agent_state", 2*time.Second)
	waitForNeoMessageType(t, extraSocket, "agent_state", 2*time.Second)

	if err := activeExecutor.WriteJSON(map[string]any{"type": "executor_connected", "executorId": "active-executor"}); err != nil {
		t.Fatalf("write active executor_connected: %v", err)
	}
	waitForNeoMessageType(t, activeExecutor, "executor_connected", 2*time.Second)

	if err := client.WriteJSON(map[string]any{"type": "client_terminal_open", "terminalId": "term-1", "cols": 80, "rows": 24}); err != nil {
		t.Fatalf("write client_terminal_open: %v", err)
	}
	open := waitForNeoMessageType(t, activeExecutor, "executor_terminal_open", 2*time.Second)
	if open["terminalId"] != "term-1" {
		t.Fatalf("executor_terminal_open = %#v", open)
	}
	assertNoNeoMessageType(t, extraSocket, "executor_terminal_open", 100*time.Millisecond)

	if err := extraSocket.WriteJSON(map[string]any{"type": "executor_terminal_exit", "terminalId": "term-1", "error": "Remote terminal control is disabled"}); err != nil {
		t.Fatalf("write stale executor_terminal_exit: %v", err)
	}
	assertNoNeoMessageType(t, probeClient, "client_terminal_exit", 100*time.Millisecond)

	if err := activeExecutor.WriteJSON(map[string]any{"type": "executor_terminal_output", "terminalId": "term-1", "dataBase64": "b2s="}); err != nil {
		t.Fatalf("write active executor_terminal_output: %v", err)
	}
	output := waitForNeoMessageType(t, client, "client_terminal_output", 2*time.Second)
	if output["terminalId"] != "term-1" || output["dataBase64"] != "b2s=" {
		t.Fatalf("client_terminal_output = %#v", output)
	}
}

