func TestInferNeoOpenAIChatStreamProviderAmpNostromoEmptyStreamFallsBackToAmpChat(t *testing.T) {
	streamCalls := 0
	nonStreamCalls := 0
	upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/api/provider/amp/v1/chat/completions" {
			t.Fatalf("unexpected path %s", r.URL.Path)
		}
		payload := readNeoJSON(r.Body)
		if payload["model"] != "amp-nostromo-v1" || stringValue(payload["reasoning_effort"]) != "low" {
			t.Fatalf("payload = %#v, want amp nostromo reasoning", payload)
		}
		if payload["stream"] == true {
			streamCalls++
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(http.StatusInternalServerError)
			_, _ = w.Write([]byte(`{"error":{"message":"empty_stream: upstream stream closed before first payload"}}`))
			return
		}
		nonStreamCalls++
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"choices":[{"message":{"content":"amp fallback"}}]}`))
	}))
	defer upstream.Close()

	deltaCalls := 0
	result, err := inferNeoOpenAIChatStreamProvider(testNeoRuntimeForServer(t, upstream), neoInferenceRequest{
		ThreadID:  "T-amp-chat-stream-empty",
		AgentMode: "nostromo",
		History:   []neoHistoryMessage{{Role: "user", Text: "hello"}},
	}, neoModelRoute{Provider: "amp", Model: "amp-nostromo-v1"}, func(delta neoInferenceDelta) {
		deltaCalls++
	}, "amp")
	if err != nil {
		t.Fatalf("inferNeoOpenAIChatStreamProvider error: %v", err)
	}
	if result.Provider != "amp" || result.Model != "amp-nostromo-v1" || result.Text != "amp fallback" {
		t.Fatalf("result = %+v, want amp fallback text", result)
	}
	if streamCalls != 1 || nonStreamCalls != 1 {
		t.Fatalf("streamCalls=%d nonStreamCalls=%d, want 1/1", streamCalls, nonStreamCalls)
	}
	if deltaCalls != 0 {
		t.Fatalf("deltaCalls=%d, want no streaming deltas from non-stream fallback", deltaCalls)
	}
}

func TestInferNeoOpenAIChatStreamProviderOpenAIEmptyStreamKeepsResponsesFallback(t *testing.T) {
	chatStreamCalls := 0
	responsesCalls := 0
	upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		switch r.URL.Path {
		case "/api/provider/openai/v1/chat/completions":
			chatStreamCalls++
			payload := readNeoJSON(r.Body)
			if payload["stream"] != true || payload["model"] != "gpt-test" {
				t.Fatalf("chat stream payload = %#v", payload)
			}
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(http.StatusInternalServerError)
			_, _ = w.Write([]byte(`{"error":{"message":"empty_stream: upstream stream closed before first payload"}}`))
		case "/api/provider/openai/v1/responses":
			responsesCalls++
			payload := readNeoJSON(r.Body)
			if payload["model"] != "gpt-test" || payload["stream"] == true {
				t.Fatalf("responses fallback payload = %#v", payload)
			}
			w.Header().Set("Content-Type", "application/json")
			_, _ = w.Write([]byte(`{"output":[{"type":"message","role":"assistant","content":[{"type":"output_text","text":"responses fallback"}]}]}`))
		default:
			t.Fatalf("unexpected path %s", r.URL.Path)
		}
	}))
	defer upstream.Close()

	result, err := inferNeoOpenAIChatStreamProvider(testNeoRuntimeForServer(t, upstream), neoInferenceRequest{
		ThreadID:        "T-openai-chat-stream-empty",
		AgentMode:       "deep",
		ReasoningEffort: "xhigh",
		History:         []neoHistoryMessage{{Role: "user", Text: "hello"}},
	}, neoModelRoute{Provider: "openai", Model: "gpt-test"}, nil, "openai")
	if err != nil {
		t.Fatalf("inferNeoOpenAIChatStreamProvider error: %v", err)
	}
	if result.Provider != "openai" || result.Model != "gpt-test" || result.Text != "responses fallback" {
		t.Fatalf("result = %+v, want responses fallback", result)
	}
	if chatStreamCalls != 1 || responsesCalls != 1 {
		t.Fatalf("chatStreamCalls=%d responsesCalls=%d, want 1/1", chatStreamCalls, responsesCalls)
	}
}

func TestInferNeoOpenAIChatProviderAppliesResponseJSONSchema(t *testing.T) {
	schema := map[string]any{
		"type": "object",
		"properties": map[string]any{
			"relevantContent": map[string]any{"type": "string"},
		},
		"required":             []any{"relevantContent"},
		"additionalProperties": false,
	}
	for _, stream := range []bool{false, true} {
		t.Run(fmt.Sprintf("stream_%t", stream), func(t *testing.T) {
			upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				if r.URL.Path != "/api/provider/openai/v1/chat/completions" {
					t.Fatalf("unexpected path %s", r.URL.Path)
				}
				payload := readNeoJSON(r.Body)
				format := mapValue(payload["response_format"])
				if format["type"] != "json_schema" {
					t.Fatalf("response_format = %#v, want json_schema", format)
				}
				jsonSchema := mapValue(format["json_schema"])
				if jsonSchema["name"] != "neo_response" || jsonSchema["strict"] != true {
					t.Fatalf("json_schema = %#v, want strict neo_response", jsonSchema)
				}
				gotSchema := mapValue(jsonSchema["schema"])
				if gotSchema["additionalProperties"] != false || len(mapValue(gotSchema["properties"])) == 0 {
					t.Fatalf("json_schema.schema = %#v, want cloned schema", gotSchema)
				}
				if payload["parallel_tool_calls"] != false {
					t.Fatalf("parallel_tool_calls = %#v, want false", payload["parallel_tool_calls"])
				}
				if stream {
					w.Header().Set("Content-Type", "text/event-stream")
					_, _ = w.Write([]byte("data: {\"choices\":[{\"delta\":{\"content\":\"{\\\"relevantContent\\\":\\\"ok\\\"}\"}}]}\n\ndata: [DONE]\n\n"))
					return
				}
				w.Header().Set("Content-Type", "application/json")
				_, _ = w.Write([]byte(`{"choices":[{"message":{"content":"{\"relevantContent\":\"ok\"}"}}]}`))
			}))
			defer upstream.Close()

			request := neoInferenceRequest{
				ThreadID:                 "T-openai-chat-schema",
				History:                  []neoHistoryMessage{{Role: "user", Text: "hi"}},
				ResponseMimeType:         "application/json",
				ResponseJSONSchema:       schema,
				ProviderFeature:          "amp.read-thread",
				DisableParallelToolCalls: true,
			}
			var (
				result neoInferenceResult
				err    error
			)
			if stream {
				result, err = inferNeoOpenAIChatStreamProvider(testNeoRuntimeForServer(t, upstream), request, neoModelRoute{Provider: "openai", Model: "gpt-test"}, nil, "openai")
			} else {
				result, err = inferNeoOpenAIChatProvider(testNeoRuntimeForServer(t, upstream), request, neoModelRoute{Provider: "openai", Model: "gpt-test"}, "openai")
			}
			if err != nil {
				t.Fatalf("inferNeoOpenAIChatProvider stream=%v error: %v", stream, err)
			}
			if !strings.Contains(result.Text, "relevantContent") {
				t.Fatalf("text = %q, want JSON response text", result.Text)
			}
		})
	}
}

func TestInferNeoLocalFireworksAppliesBinaryProviderSettings(t *testing.T) {
	for _, stream := range []bool{false, true} {
		t.Run(fmt.Sprintf("stream_%v", stream), func(t *testing.T) {
			upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				if r.URL.Path != "/api/provider/fireworks/v1/chat/completions" {
					t.Fatalf("unexpected path %s", r.URL.Path)
				}
				if got := r.Header.Get("x-fireworks-direct-routing"); got != "true" {
					t.Fatalf("x-fireworks-direct-routing = %q, want true", got)
				}
				payload := readNeoJSON(r.Body)
				if payload["stream"] != stream || payload["model"] != "accounts/fireworks/models/kimi-k2-instruct-0905" {
					t.Fatalf("payload = %#v, want fireworks kimi stream=%v", payload, stream)
				}
				if got := stringValue(payload["reasoning_effort"]); got != "none" {
					t.Fatalf("reasoning_effort = %q, want none; payload=%#v", got, payload)
				}
				if got := payload["temperature"]; got != 0.6 {
					t.Fatalf("temperature = %#v, want 0.6; payload=%#v", got, payload)
				}
				if got := payload["top_p"]; got != 0.95 {
					t.Fatalf("top_p = %#v, want 0.95; payload=%#v", got, payload)
				}
				if got := numberFrom(payload["max_tokens"]); got != 32000 {
					t.Fatalf("max_tokens = %d, want 32000; payload=%#v", got, payload)
				}

				if stream {
					w.Header().Set("Content-Type", "text/event-stream")
					_, _ = w.Write([]byte("data: {\"choices\":[{\"delta\":{\"content\":\"hi\"}}],\"usage\":{\"prompt_tokens\":1,\"completion_tokens\":1}}\n\n"))
					_, _ = w.Write([]byte("data: [DONE]\n\n"))
					return
				}
				w.Header().Set("Content-Type", "application/json")
				_, _ = w.Write([]byte(`{"choices":[{"message":{"content":"ok"}}],"usage":{"prompt_tokens":2,"completion_tokens":1}}`))
			}))
			defer upstream.Close()

			request := neoInferenceRequest{
				ThreadID:  "T-test",
				AgentMode: "smart",
				Settings: map[string]any{
					"internal.model":                   "accounts/fireworks/models/kimi-k2-instruct-0905",
					"internal.fireworks.directRouting": true,
					"internal.kimi.reasoning":          "none",
				},
				History: []neoHistoryMessage{{Role: "user", Text: "hello"}},
			}
			if stream {
				var deltas []string
				result, err := inferNeoLocalStream(testNeoRuntimeForServer(t, upstream), request, func(delta neoInferenceDelta) {
					deltas = append(deltas, delta.Text)
				})
				if err != nil {
					t.Fatalf("inferNeoLocalStream error: %v", err)
				}
				if result.Provider != "fireworks" || result.Model != "accounts/fireworks/models/kimi-k2-instruct-0905" || result.Text != "hi" || strings.Join(deltas, "") != "hi" {
					t.Fatalf("result = %+v deltas=%#v, want fireworks stream", result, deltas)
				}
				return
			}
			result, err := inferNeoLocal(testNeoRuntimeForServer(t, upstream), request)
			if err != nil {
				t.Fatalf("inferNeoLocal error: %v", err)
			}
			if result.Provider != "fireworks" || result.Model != "accounts/fireworks/models/kimi-k2-instruct-0905" || result.Text != "ok" {
				t.Fatalf("result = %+v, want fireworks text", result)
			}
		})
	}
}

func TestInferNeoLocalBasetenAppliesBinaryKimiReasoningSettings(t *testing.T) {
	for _, tc := range []struct {
		name         string
		reasoning    string
		wantTemplate bool
		wantTemp     float64
	}{
		{name: "default", wantTemplate: true, wantTemp: 1},
		{name: "none", reasoning: "none", wantTemp: 0.6},
	} {
		t.Run(tc.name, func(t *testing.T) {
			upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				if r.URL.Path != "/api/provider/baseten/v1/chat/completions" {
					t.Fatalf("unexpected path %s", r.URL.Path)
				}
				payload := readNeoJSON(r.Body)
				if payload["model"] != "moonshotai/Kimi-K2.5" {
					t.Fatalf("model = %#v, want moonshotai/Kimi-K2.5; payload=%#v", payload["model"], payload)
				}
				if _, exists := payload["reasoning_effort"]; exists {
					t.Fatalf("baseten payload should not include reasoning_effort: %#v", payload)
				}
				template := mapValue(payload["chat_template_args"])
				if tc.wantTemplate {
					if template["enable_thinking"] != true {
						t.Fatalf("chat_template_args = %#v, want enable_thinking true; payload=%#v", template, payload)
					}
				} else if len(template) > 0 {
					t.Fatalf("chat_template_args should be omitted for none reasoning: %#v", payload)
				}
				if got, ok := payload["temperature"].(float64); !ok || got != tc.wantTemp {
					t.Fatalf("temperature = %#v, want %#v; payload=%#v", payload["temperature"], tc.wantTemp, payload)
				}
				if got := payload["top_p"]; got != 0.95 {
					t.Fatalf("top_p = %#v, want 0.95; payload=%#v", got, payload)
				}
				if got := numberFrom(payload["max_tokens"]); got != 32000 {
					t.Fatalf("max_tokens = %d, want 32000; payload=%#v", got, payload)
				}
				w.Header().Set("Content-Type", "application/json")
				_, _ = w.Write([]byte(`{"choices":[{"message":{"content":"ok"}}],"usage":{"prompt_tokens":2,"completion_tokens":1}}`))
			}))
			defer upstream.Close()

			settings := map[string]any{"internal.model": "moonshotai/Kimi-K2.5"}
			if tc.reasoning != "" {
				settings["internal.kimi.reasoning"] = tc.reasoning
			}
			result, err := inferNeoLocal(testNeoRuntimeForServer(t, upstream), neoInferenceRequest{
				ThreadID:  "T-test",
				AgentMode: "smart",
				Settings:  settings,
				History:   []neoHistoryMessage{{Role: "user", Text: "hello"}},
			})
			if err != nil {
				t.Fatalf("inferNeoLocal error: %v", err)
			}
			if result.Provider != "baseten" || result.Model != "moonshotai/Kimi-K2.5" || result.Text != "ok" {
				t.Fatalf("result = %+v, want baseten text", result)
			}
		})
	}
}

func TestNeoModelRegistryMatchesAmpBinaryValues(t *testing.T) {
	baseline := ampBinaryParityBaselineForTest(t)
	if len(baseline.Signals.ModelLimits) == 0 {
		t.Fatal("Amp binary parity baseline has no model_limits")
	}
	for _, model := range baseline.Signals.ModelLimits {
		t.Run(model.Name, func(t *testing.T) {
			if got := neoModelContextWindow[model.Name]; got != model.ContextWindow {
				t.Fatalf("context window = %d, want %d from Amp binary baseline", got, model.ContextWindow)
			}
			if got := neoModelMaxOutputTokens[model.Name]; got != model.MaxOutputTokens {
				t.Fatalf("max output = %d, want %d from Amp binary baseline", got, model.MaxOutputTokens)
			}
			wantMaxInput := model.ContextWindow
			if max := model.ContextWindow - model.MaxOutputTokens; max > 0 {
				wantMaxInput = max
			}
			if got := neoModelMaxInputTokens(model.Name); got != wantMaxInput {
				t.Fatalf("max input = %d, want %d from Amp binary baseline", got, wantMaxInput)
			}
		})
	}
}

