func TestInferNeoCompactionLocalAmpNostromoInfersAmpProvider(t *testing.T) {
	upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/api/provider/amp/v1/chat/completions" {
			t.Fatalf("unexpected compaction path %s", r.URL.Path)
		}
		payload := readNeoJSON(r.Body)
		if payload["model"] != "amp-nostromo-v1" || payload["stream"] != false || stringValue(payload["reasoning_effort"]) != defaultNeoCompactionReasoning {
			t.Fatalf("payload = %#v, want inferred amp compaction reasoning %s", payload, defaultNeoCompactionReasoning)
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"choices":[{"message":{"content":"<summary>amp compacted</summary>"}}]}`))
	}))
	defer upstream.Close()

	summary, err := inferNeoCompactionLocal(context.Background(), testNeoRuntimeForServer(t, upstream), "T-amp-compaction", neoModelRoute{Model: "amp-nostromo-v1"}, []neoMessage{{
		ThreadID:  "T-amp-compaction",
		MessageID: "M-user",
		Role:      "user",
		Content:   []any{map[string]any{"type": "text", "text": "important state"}},
	}}, "")
	if err != nil {
		t.Fatalf("infer compaction: %v", err)
	}
	if summary != "<summary>amp compacted</summary>" {
		t.Fatalf("summary = %q", summary)
	}
}

func TestInferNeoCompactionAnthropicUsesBinaryHelperHeader(t *testing.T) {
	upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/api/provider/anthropic/v1/messages" {
			t.Fatalf("unexpected compaction path %s", r.URL.Path)
		}
		if got := r.Header.Get("x-stainless-helper"); got != "compaction" {
			t.Fatalf("x-stainless-helper = %q, want compaction", got)
		}
		payload := readNeoJSON(r.Body)
		if payload["model"] != "claude-opus-4-7" {
			t.Fatalf("compaction model = %#v, want claude-opus-4-7", payload["model"])
		}
		messages := arrayValue(payload["messages"])
		if len(messages) != 2 {
			t.Fatalf("messages = %#v, want history plus continuation prompt", messages)
		}
		last := mapValue(messages[len(messages)-1])
		if last["role"] != "user" || !strings.Contains(fmt.Sprint(last["content"]), "continuation summary") {
			t.Fatalf("last compaction message = %#v, want continuation prompt", last)
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"content":[{"type":"text","text":"<summary>anthropic compacted</summary>"}]}`))
	}))
	t.Cleanup(upstream.Close)

	rt := testNeoRuntimeForServer(t, upstream)
	summary, err := inferNeoCompactionLocal(context.Background(), rt, "T-anthropic-compaction", neoModelRoute{Provider: "anthropic", Model: "claude-opus-4-7"}, []neoMessage{{
		ThreadID:  "T-anthropic-compaction",
		MessageID: "M-user",
		Role:      "user",
		Content:   []any{map[string]any{"type": "text", "text": "important state"}},
	}}, "")
	if err != nil {
		t.Fatalf("infer compaction: %v", err)
	}
	if summary != "<summary>anthropic compacted</summary>" {
		t.Fatalf("summary = %q", summary)
	}
}

func TestInferNeoCompactionLocalPropagatesCallerContext(t *testing.T) {
	upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		if r.Context().Err() != nil {
			w.WriteHeader(http.StatusRequestTimeout)
			return
		}
		_, _ = w.Write([]byte(`{"content":[{"type":"text","text":"<summary>ctx compacted</summary>"}]}`))
	}))
	t.Cleanup(upstream.Close)

	summary, err := inferNeoCompactionLocal(context.Background(), testNeoRuntimeForServer(t, upstream), "T-ctx-compaction", neoModelRoute{Provider: "anthropic", Model: "claude-opus-4-7"}, []neoMessage{{
		ThreadID:  "T-ctx-compaction",
		MessageID: "M-user",
		Role:      "user",
		Content:   []any{map[string]any{"type": "text", "text": "important state"}},
	}}, "")
	if err != nil {
		t.Fatalf("infer compaction with caller context: %v", err)
	}
	if summary != "<summary>ctx compacted</summary>" {
		t.Fatalf("summary = %q", summary)
	}

	cancelledCtx, cancel := context.WithCancel(context.Background())
	cancel()
	if _, err := inferNeoCompactionLocal(cancelledCtx, testNeoRuntimeForServer(t, upstream), "T-ctx-compaction", neoModelRoute{Provider: "anthropic", Model: "claude-opus-4-7"}, []neoMessage{{
		ThreadID:  "T-ctx-compaction",
		MessageID: "M-user",
		Role:      "user",
		Content:   []any{map[string]any{"type": "text", "text": "important state"}},
	}}, ""); !errors.Is(err, context.Canceled) {
		t.Fatalf("cancelled caller context err = %v, want context.Canceled", err)
	}
}

