func TestNeoSystemPromptUsesBinaryPromptFamilies(t *testing.T) {
	headingGuidance := "Use a few information-dense H1-H3 headings for important updates and navigation; each should state a takeaway, not merely organize content."
	closedDiagram := "╰────────╯\n```"

	for _, tc := range []struct {
		name    string
		request neoInferenceRequest
		route   neoModelRoute
		want    []string
	}{
		{
			name:    "agg man",
			request: neoInferenceRequest{AgentMode: "agg-man"},
			route:   neoModelRoute{Provider: "openai", Model: "gpt-5.5"},
			want:    []string{"You are Agg Man, Amp's platform control-plane assistant.", "Use find_thread to discover relevant threads and read_thread before making claims", "Use archive_thread, archive_threads, and unarchive_thread", "workflow: \"code_review\"", "workflow: \"merge_changes\""},
		},
		{
			name:    "deep",
			request: neoInferenceRequest{AgentMode: "deep"},
			route:   neoModelRoute{Provider: "openai", Model: "gpt-5.5"},
			want:    []string{"You are Amp, an autonomous coding agent.", "Use finder for complex, multi-step codebase discovery", neoGitCommitMultilinePromptLine, headingGuidance, closedDiagram},
		},
		{
			name:    "low glm",
			request: neoInferenceRequest{AgentMode: "low"},
			route:   neoModelRoute{Provider: "amp", Model: "glm-5.2"},
			want:    []string{"You are a senior software engineer working directly in the user's codebase", "<operating_principles>", "<frontend_taste>"},
		},
		{
			name:    "ultra fable",
			request: neoInferenceRequest{AgentMode: "ultra"},
			route:   neoModelRoute{Provider: "anthropic", Model: "claude-fable-5"},
			want:    []string{"You are pair programming with a user to solve their coding task", "# How to act", "# Engineering principles", "# Verification", "# Communication"},
		},
		{
			name:    "ultra gpt fallback",
			request: neoInferenceRequest{AgentMode: "ultra"},
			route:   neoModelRoute{Provider: "openai", Model: "gpt-5.6-sol"},
			want:    []string{"# Fast Context Understanding", "# Parallel Execution Policy", "# Final Status Spec"},
		},
		{
			name:    "ultra kimi k3 override",
			request: neoInferenceRequest{AgentMode: "ultra"},
			route:   neoModelRoute{Provider: "moonshotai", Model: "kimi-k3"},
			want:    []string{"**SPEED FIRST**", "Prefer specialized tools over Bash"},
		},
		{
			name:    "deep gpt54",
			request: neoInferenceRequest{AgentMode: "deep"},
			route:   neoModelRoute{Provider: "openai", Model: "gpt-5.4"},
			want:    []string{"You are Amp. You and the user share the same workspace", "Pull in external references when uncertainty or risk is meaningful", "- " + neoGitCommitMultilinePromptLine, headingGuidance, closedDiagram},
		},
		{
			name:    "codex",
			request: neoInferenceRequest{AgentMode: "smart"},
			route:   neoModelRoute{Provider: "openai", Model: "gpt-5-codex"},
			want:    []string{"If the user asks you to do an edit or you can infer it, do edits.", "# Fast Context Understanding", "**Bad**", "> Bash", "GPT-5.5 reasoning model", headingGuidance, closedDiagram},
		},
		{
			name:    "xai",
			request: neoInferenceRequest{AgentMode: "smart"},
			route:   neoModelRoute{Provider: "xai", Model: "grok-code-fast-1"},
			want:    []string{"When invoking the Read tool, ALWAYS use absolute paths.", "# Diagrams", headingGuidance, closedDiagram},
		},
		{
			name:    "kimi",
			request: neoInferenceRequest{AgentMode: "smart"},
			route:   neoModelRoute{Provider: "anthropic", Model: "kimi-k2-0905"},
			want:    []string{"**SPEED FIRST**", "Prefer specialized tools over Bash", headingGuidance, closedDiagram},
		},
		{
			name:    "gemini with optional tool guidance",
			request: neoInferenceRequest{AgentMode: "smart", Tools: []neoToolSpec{{Name: "oracle"}, {Name: "get_diagnostics"}}},
			route:   neoModelRoute{Provider: "google", Model: "gemini-3-pro"},
			want:    []string{"oracle tool to get expert guidance", "get_diagnostics tool and  any lint", headingGuidance, closedDiagram},
		},
		{
			name:    "smart",
			request: neoInferenceRequest{AgentMode: "smart"},
			route:   neoModelRoute{Provider: "anthropic", Model: "claude-opus-4-7"},
			want:    []string{"Your main goal is to follow the user's instructions and verify that the result works", "<autonomy_and_persistence>", "<using_subagents>", "fewer than 4 lines of text", headingGuidance, closedDiagram},
		},
		{
			name:    "large default",
			request: neoInferenceRequest{AgentMode: "large"},
			route:   neoModelRoute{Provider: "anthropic", Model: "claude-opus-4-8"},
			want:    []string{"<autonomy_and_persistence>", "<using_subagents>", "fewer than 4 lines of text", headingGuidance, closedDiagram},
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			prompt := neoSystemPrompt(tc.request, tc.route)
			for _, want := range tc.want {
				if !strings.Contains(prompt, want) {
					t.Fatalf("prompt missing %q:\n%s", want, prompt)
				}
			}
		})
	}
}

func TestNeoAggManPromptUsesBinaryContextBlocks(t *testing.T) {
	prompt := neoSystemPrompt(neoInferenceRequest{
		AgentMode: "agg-man",
		Capabilities: map[string]any{"serverStatus": map[string]any{"user": map[string]any{
			"username":    "aikins",
			"githubLogin": "router-for-me",
		}}},
		History: []neoHistoryMessage{
			{Role: "user", UserState: map[string]any{"aggmanContext": map[string]any{"availableProjects": []any{
				map[string]any{"name": "Old", "repositoryURL": "https://github.com/example/old.git"},
			}}}},
			{Role: "assistant", Text: "ok"},
			{Role: "user", UserState: map[string]any{"aggmanContext": map[string]any{"availableProjects": []any{
				map[string]any{"name": "CLIProxyAPI", "repositoryURL": "https://github.com/router-for-me/CLIProxyAPI.git"},
				map[string]any{"name": "CLIProxyAPI", "repositoryURL": "https://github.com/router-for-me/CLIProxyAPI.git"},
				map[string]any{"name": "Local", "repositoryURL": "github.com/router-for-me/local.git"},
			}}}},
		},
	}, neoModelRoute{Provider: "openai", Model: "gpt-5.5"})

	for _, want := range []string{
		"# Signed-In User",
		"- Amp username: aikins",
		"- Connected GitHub login: @router-for-me",
		"- No stored Slack identity is currently known.",
		"# Workspace Projects",
		"- CLIProxyAPI: router-for-me/CLIProxyAPI (https://github.com/router-for-me/CLIProxyAPI.git)",
		"- Local: github.com/router-for-me/local (github.com/router-for-me/local.git)",
	} {
		if !strings.Contains(prompt, want) {
			t.Fatalf("agg-man prompt missing %q:\n%s", want, prompt)
		}
	}
	for _, notWant := range []string{
		"Old: example/old",
		"# Environment",
		"AGENTS.md guidance files are delivered dynamically",
		"## Skills",
	} {
		if strings.Contains(prompt, notWant) {
			t.Fatalf("agg-man prompt should not contain %q:\n%s", notWant, prompt)
		}
	}
}

func TestNeoPuckPromptUsesLocalControlPlaneContext(t *testing.T) {
	prompt := neoSystemPrompt(neoInferenceRequest{
		ThreadID:  "T-019f7000-0000-7000-8000-000000000099",
		AgentMode: "puck",
		Capabilities: map[string]any{"serverStatus": map[string]any{"user": map[string]any{
			"username":    "aikins",
			"githubLogin": "router-for-me",
		}}},
		History: []neoHistoryMessage{{Role: "user", UserState: map[string]any{
			"currentlyVisibleFiles": []any{},
			"puckContext": map[string]any{
				"currentURL": "https://ampcode.com/feed",
				"timeZone":   "Africa/Accra",
				"customization": map[string]any{
					"displayName": "Aikins",
					"emoji":       "🧭",
				},
				"availableProjects": []any{
					map[string]any{"projectID": "019f7000-0000-7000-8000-000000000098", "namespace": "router-for-me", "name": "CLIProxyAPI"},
				},
			},
		}}},
		Tools: []neoToolSpec{{Name: "thread_interact"}},
	}, neoModelRoute{Provider: "openai", Model: "gpt-5.6-terra"})

	for _, want := range []string{
		"You are Puck, Amp's platform control-plane assistant and meta agent.",
		"# Signed-In User",
		"# Current Puck Context",
		"- Current Puck thread ID: T-019f7000-0000-7000-8000-000000000099",
		"- Current Amp URL: https://ampcode.com/feed",
		"- User time zone: Africa/Accra",
		"- User display name: Aikins",
		"- User emoji: 🧭",
		"# Workspace Projects",
		"- CLIProxyAPI: router-for-me/CLIProxyAPI [projectID: 019f7000-0000-7000-8000-000000000098]",
		"quick assistant and home base for launching and coordinating other agents",
		"old computational familiar",
		"permanent expression of concentrated concern",
		"Inspect directly for quick, read-only coordination",
		"Delegate substantive coding",
		"Give each child a self-contained brief",
		"thread_interact with action \"message\", the Current Puck thread ID",
		"omitted child mode defaults to Medium",
		"Completion callbacks are not automatic",
		"Do not hold the current response open, sleep, or poll",
		"follow up only when the user asks for status",
		"Treat an incoming task announcement as a reported update",
		"Report duplicate callbacks only once",
		"later callback contradicts an earlier report",
		"its executor does not start",
		"do not silently retry",
		"Rename, pin, unpin, add labels, or remove named labels only on explicit request",
		"Preserve unmentioned labels",
		"must not assume old messages or unresolved references",
		"ask instead of guessing",
		"pass the original text and image blocks through create_thread content",
		"Archive and Start New Chat",
		"running child work is not cancelled or modified",
		"late child callback still belongs to its original request",
		"workflow: \"code_review\"",
		"workflow: \"merge_changes\"",
	} {
		if !strings.Contains(prompt, want) {
			t.Fatalf("Puck prompt missing %q:\n%s", want, prompt)
		}
	}
	for _, notWant := range []string{"You are Agg Man", "render_agg_man", "send_message_to_aggman"} {
		if strings.Contains(prompt, notWant) {
			t.Fatalf("Puck prompt should not contain %q:\n%s", notWant, prompt)
		}
	}
}

func TestNeoClientPuckContextMatchesOptionalWebProjectID(t *testing.T) {
	if !neoClientPuckContext(map[string]any{
		"currentURL": "https://ampcode.com/feed",
		"availableProjects": []any{
			map[string]any{"name": "CLIProxyAPI", "namespace": "router-for-me"},
		},
	}) {
		t.Fatal("Puck context rejected a web project without optional projectID")
	}
	if neoClientPuckContext(map[string]any{
		"currentURL": "https://ampcode.com/feed",
		"availableProjects": []any{
			map[string]any{"projectID": 42, "name": "CLIProxyAPI"},
		},
	}) {
		t.Fatal("Puck context accepted a non-string projectID")
	}
	if neoClientPuckContext(map[string]any{
		"currentURL": "https://ampcode.com/feed",
		"availableProjects": []any{
			map[string]any{"projectId": 42, "name": "CLIProxyAPI"},
		},
	}) {
		t.Fatal("Puck context accepted a non-string projectId alias")
	}
	projects := neoLatestWorkspaceProjects([]neoHistoryMessage{{Role: "user", UserState: map[string]any{
		"puckContext": map[string]any{
			"currentURL": "https://ampcode.com/feed",
			"availableProjects": []any{
				map[string]any{"projectID": "not-a-uuid", "name": "CLIProxyAPI"},
			},
		},
	}}})
	if len(projects) != 1 || stringValue(projects[0]["projectID"]) != "" {
		t.Fatalf("invalid project ID reached prompt projects: %#v", projects)
	}
}

