func TestValidateNeoHydratedAttachmentBytesNormalizesMediaType(t *testing.T) {
	imageData, err := base64.StdEncoding.DecodeString(testNeoPNGBase64(t, 1, 1))
	if err != nil {
		t.Fatal(err)
	}
	_, mediaType, err := validateNeoHydratedAttachmentBytes(imageData, "image/jpeg")
	if err != nil {
		t.Fatal(err)
	}
	if mediaType != "image/png" {
		t.Fatalf("detected media type = %q", mediaType)
	}
	if len(imageData) <= 33 {
		t.Fatalf("PNG fixture is too short: %d", len(imageData))
	}
	if _, _, err := validateNeoHydratedAttachmentBytes(imageData[:33], "image/png"); err == nil || !strings.Contains(err.Error(), "invalid image attachment data") {
		t.Fatalf("truncated PNG error = %v", err)
	}
	paletted := image.NewPaletted(image.Rect(0, 0, 1, 1), color.Palette{color.Black, color.White})
	var encodedGIF bytes.Buffer
	if err := gif.EncodeAll(&encodedGIF, &gif.GIF{Image: []*image.Paletted{paletted, paletted}, Delay: []int{0, 0}}); err != nil {
		t.Fatal(err)
	}
	truncatedGIF := encodedGIF.Bytes()[:encodedGIF.Len()-1]
	if _, mediaType, err := validateNeoHydratedAttachmentBytes(encodedGIF.Bytes(), "image/gif"); err != nil || mediaType != "image/gif" {
		t.Fatalf("valid animated GIF = media %q error %v", mediaType, err)
	}
	if _, _, err := validateNeoHydratedAttachmentBytes(truncatedGIF, "image/gif"); err == nil || !strings.Contains(err.Error(), "invalid image attachment data") {
		t.Fatalf("truncated GIF error = %v", err)
	}
	gifWithOutsideFrame := append([]byte(nil), encodedGIF.Bytes()...)
	descriptor := bytes.IndexByte(gifWithOutsideFrame, 0x2c)
	if descriptor < 0 {
		t.Fatal("GIF fixture has no image descriptor")
	}
	binary.LittleEndian.PutUint16(gifWithOutsideFrame[descriptor+1:descriptor+3], 2)
	if _, _, err := validateNeoHydratedAttachmentBytes(gifWithOutsideFrame, "image/gif"); err == nil || !strings.Contains(err.Error(), "invalid image attachment data") {
		t.Fatalf("outside-canvas GIF error = %v", err)
	}
	validWebP := testNeoAnimatedWebP(t, 0, 1)
	if _, mediaType, err := validateNeoHydratedAttachmentBytes(validWebP, "image/webp"); err != nil || mediaType != "image/webp" {
		t.Fatalf("valid animated WebP = media %q error %v", mediaType, err)
	}
	animStart := 12 + 8 + 10
	animEnd := animStart + 8 + 6
	misorderedWebP := append([]byte(nil), validWebP[:animStart]...)
	misorderedWebP = append(misorderedWebP, validWebP[animEnd:]...)
	misorderedWebP = append(misorderedWebP, validWebP[animStart:animEnd]...)
	if _, _, err := validateNeoHydratedAttachmentBytes(misorderedWebP, "image/webp"); err == nil || !strings.Contains(err.Error(), "invalid image attachment data") {
		t.Fatalf("misordered animated WebP error = %v", err)
	}
	if _, _, err := validateNeoHydratedAttachmentBytes(testNeoAnimatedWebP(t, 2, 1), "image/webp"); err == nil || !strings.Contains(err.Error(), "invalid image attachment data") {
		t.Fatalf("outside-canvas WebP error = %v", err)
	}
	if _, _, err := validateNeoHydratedAttachmentBytes(testNeoAnimatedWebP(t, 0, neoAttachmentMaxAnimationFrames+1), "image/webp"); err == nil || !strings.Contains(err.Error(), "invalid image attachment data") {
		t.Fatalf("over-frame-limit WebP error = %v", err)
	}
}

func testNeoAnimatedWebP(t *testing.T, frameX, frameCount int) []byte {
	t.Helper()
	static, err := base64.StdEncoding.DecodeString("")
	if err != nil {
		t.Fatal(err)
	}
	width, height, _, ok := neoValidWebPContainer(static)
	if !ok {
		t.Fatal("static WebP fixture is invalid")
	}
	appendUint24 := func(dst []byte, value int) {
		dst[0] = byte(value)
		dst[1] = byte(value >> 8)
		dst[2] = byte(value >> 16)
	}
	appendChunk := func(dst []byte, name string, data []byte) []byte {
		dst = append(dst, name...)
		size := make([]byte, 4)
		binary.LittleEndian.PutUint32(size, uint32(len(data)))
		dst = append(dst, size...)
		dst = append(dst, data...)
		if len(data)&1 != 0 {
			dst = append(dst, 0)
		}
		return dst
	}
	vp8x := make([]byte, 10)
	vp8x[0] = 0x02
	appendUint24(vp8x[4:7], width-1)
	appendUint24(vp8x[7:10], height-1)
	body := appendChunk([]byte("WEBP"), "VP8X", vp8x)
	body = appendChunk(body, "ANIM", make([]byte, 6))
	for range frameCount {
		frame := make([]byte, 16)
		appendUint24(frame[0:3], frameX/2)
		appendUint24(frame[6:9], width-1)
		appendUint24(frame[9:12], height-1)
		frame = append(frame, static[12:]...)
		body = appendChunk(body, "ANMF", frame)
	}
	raw := []byte("RIFF")
	size := make([]byte, 4)
	binary.LittleEndian.PutUint32(size, uint32(len(body)))
	raw = append(raw, size...)
	return append(raw, body...)
}

func TestNeoFetchAmpAttachmentCancellation(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	started := make(chan struct{})
	client := &http.Client{Transport: neoRoundTripFunc(func(req *http.Request) (*http.Response, error) {
		close(started)
		<-req.Context().Done()
		return nil, req.Context().Err()
	})}
	done := make(chan error, 1)
	workerDone := make(chan struct{})
	go func() {
		defer close(workerDone)
		_, _, err := neoFetchAmpAttachment(ctx, "https://ampcode.com/user-content/attachments/file.png", client, neoAttachmentMaxInferenceBytes, "")
		done <- err
	}()
	t.Cleanup(func() {
		cancel()
		waitNeoTestOperations(t, neoTestOperation{name: "cancelled attachment fetch", done: workerDone})
	})
	select {
	case <-started:
	case <-time.After(time.Second):
		t.Fatal("attachment fetch did not start")
	}
	cancel()
	select {
	case err := <-done:
		if !errors.Is(err, context.Canceled) {
			t.Fatalf("cancelled attachment error = %v", err)
		}
	case <-time.After(time.Second):
		t.Fatal("attachment fetch did not stop after cancellation")
	}
}

func TestNeoFetchAmpAttachmentCancellationDuringRetryBackoff(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	firstAttempt := make(chan struct{})
	client := &http.Client{Transport: neoRoundTripFunc(func(*http.Request) (*http.Response, error) {
		select {
		case <-firstAttempt:
		default:
			close(firstAttempt)
		}
		return nil, errors.New("temporary transport failure")
	})}
	done := make(chan error, 1)
	workerDone := make(chan struct{})
	go func() {
		defer close(workerDone)
		_, _, err := neoFetchAmpAttachment(ctx, "https://ampcode.com/user-content/attachments/file.png", client, neoAttachmentMaxInferenceBytes, "")
		done <- err
	}()
	t.Cleanup(func() {
		cancel()
		waitNeoTestOperations(t, neoTestOperation{name: "attachment retry backoff", done: workerDone})
	})
	select {
	case <-firstAttempt:
	case <-time.After(time.Second):
		t.Fatal("attachment retry attempt did not start")
	}
	cancel()
	select {
	case err := <-done:
		if !errors.Is(err, context.Canceled) {
			t.Fatalf("retry-backoff cancellation error = %v", err)
		}
	case <-time.After(time.Second):
		t.Fatal("retry backoff did not stop after cancellation")
	}
}

func TestNeoAmpAttachmentRedirectURLRejectsUntrustedHost(t *testing.T) {
	trusted, err := url.Parse("https://amp-attachments-prod-0.storage.googleapis.com/file.png")
	if err != nil {
		t.Fatal(err)
	}
	untrusted, err := url.Parse("https://127.0.0.1/private")
	if err != nil {
		t.Fatal(err)
	}
	if !neoAmpAttachmentRedirectURL(trusted) || neoAmpAttachmentRedirectURL(untrusted) {
		t.Fatalf("redirect allowlist = trusted %v untrusted %v", neoAmpAttachmentRedirectURL(trusted), neoAmpAttachmentRedirectURL(untrusted))
	}
	for _, rawURL := range []string{
		"https://storage.googleapis.com.evil.example/file.png",
		"https://evilstorage.googleapis.com/file.png",
	} {
		parsed, err := url.Parse(rawURL)
		if err != nil {
			t.Fatal(err)
		}
		if neoAmpAttachmentRedirectURL(parsed) {
			t.Fatalf("redirect allowlist trusted hostname near miss %s", rawURL)
		}
	}
	if neoAmpHostedAttachmentURL("https://ampcode.com/user-content/attachments/../private-image") {
		t.Fatal("traversal-shaped Amp attachment URL was accepted")
	}
	mixedCaseRedirect, err := url.Parse("HTTPS://storage.googleapis.com/file.png")
	if err != nil {
		t.Fatal(err)
	}
	if !neoAmpHostedAttachmentURL("HTTPS://ampcode.com/user-content/attachments/file.png") || !neoAmpAttachmentRedirectURL(mixedCaseRedirect) {
		t.Fatal("mixed-case HTTPS scheme was rejected")
	}
	for _, rawURL := range []string{
		"https://ampcode.com:444/user-content/attachments/file.png",
		"https://storage.googleapis.com:444/file.png",
	} {
		parsed, err := url.Parse(rawURL)
		if err != nil {
			t.Fatal(err)
		}
		if neoAmpHostedAttachmentURL(rawURL) || neoAmpAttachmentRedirectURL(parsed) {
			t.Fatalf("explicit non-default port was trusted: %s", rawURL)
		}
		if err := neoAmpAttachmentHTTPClient.CheckRedirect(&http.Request{URL: parsed}, nil); err == nil {
			t.Fatalf("production redirect callback trusted %s", rawURL)
		}
	}
	if neoAttachmentOriginsEqual(&url.URL{Scheme: "https", Host: "neo.example.com:444"}, &url.URL{Scheme: "https", Host: "neo.example.com"}) {
		t.Fatal("local attachment origins with mismatched ports compared equal")
	}
	trustedDefaultPort, err := url.Parse("https://storage.googleapis.com:443/file.png")
	if err != nil {
		t.Fatal(err)
	}
	if err := neoAmpAttachmentHTTPClient.CheckRedirect(&http.Request{URL: trustedDefaultPort}, nil); err != nil {
		t.Fatalf("production redirect callback rejected default HTTPS port: %v", err)
	}
	if !neoAttachmentOriginsEqual(&url.URL{Scheme: "https", Host: "neo.example.com:443"}, &url.URL{Scheme: "https", Host: "neo.example.com"}) {
		t.Fatal("local attachment origins with equivalent default ports compared unequal")
	}
}

func TestNeoProviderMessagesFilterThinkingByProviderLikeBinary(t *testing.T) {
	msg := neoHistoryMessage{
		Role: "assistant",
		Text: "final answer",
		ThinkingBlocks: []neoThinkingBlock{
			{Thinking: "openai plan", Signature: "openai-sig", Provider: "openai", ID: "rs-openai"},
			{Thinking: "anthropic plan", Signature: "anthropic-sig", Provider: "anthropic"},
		},
	}

	anthropic := anthropicNeoMessages([]neoHistoryMessage{msg})
	anthropicContent := arrayValue(mapValue(anthropic[0])["content"])
	if len(anthropicContent) != 2 {
		t.Fatalf("anthropic content = %#v", anthropicContent)
	}
	if thinking := mapValue(anthropicContent[0]); stringValue(thinking["type"]) != "thinking" || stringValue(thinking["thinking"]) != "anthropic plan" || stringValue(thinking["signature"]) != "anthropic-sig" {
		t.Fatalf("anthropic thinking = %#v", thinking)
	}
	if text := mapValue(anthropicContent[1]); stringValue(text["text"]) != "final answer" {
		t.Fatalf("anthropic text = %#v", text)
	}

	openAIChat := openAINeoMessages([]neoHistoryMessage{msg}, "")
	openAIContent := arrayValue(mapValue(openAIChat[0])["content"])
	if len(openAIContent) != 2 {
		t.Fatalf("openai chat content = %#v", openAIContent)
	}
	if got := stringValue(mapValue(openAIContent[0])["text"]); got != "Thoughts: openai plan" {
		t.Fatalf("openai thought = %q", got)
	}
	if got := stringValue(mapValue(openAIContent[1])["text"]); got != "final answer" {
		t.Fatalf("openai text = %q", got)
	}

	responsesInput := openAIResponsesNeoInput([]neoHistoryMessage{msg}, "")
	if len(responsesInput) != 2 {
		t.Fatalf("responses input = %#v", responsesInput)
	}
	reasoning := mapValue(responsesInput[0])
	if reasoning["type"] != "reasoning" || reasoning["id"] != "rs-openai" || reasoning["encrypted_content"] != "openai-sig" {
		t.Fatalf("responses reasoning = %#v", reasoning)
	}
	summary := arrayValue(reasoning["summary"])
	if len(summary) != 1 || stringValue(mapValue(summary[0])["text"]) != "openai plan" {
		t.Fatalf("responses summary = %#v", summary)
	}
	message := mapValue(responsesInput[1])
	if message["type"] != "message" || message["role"] != "assistant" || message["content"] != "final answer" {
		t.Fatalf("responses assistant message = %#v", message)
	}
}

func TestAnthropicNeoMessagesReplaysThinkingOnlyForLatestToolContinuation(t *testing.T) {
	messages := anthropicNeoMessages([]neoHistoryMessage{
		{Role: "user", Text: "request"},
		{
			Role:           "assistant",
			Text:           "first step",
			ThinkingBlocks: []neoThinkingBlock{{Thinking: "stale", Signature: "stale-signature", Provider: "anthropic"}},
			ToolCalls:      []neoToolCall{{ID: "TU-first", Name: "Read", Input: map[string]any{"path": "first.txt"}}},
		},
		{Role: "tool", ToolCallID: "TU-first", ToolName: "Read", Text: "first result"},
		{
			Role:           "assistant",
			Text:           "second step",
			ThinkingBlocks: []neoThinkingBlock{{Thinking: "also stale", Signature: "also-stale-signature", Provider: "anthropic"}},
			ToolCalls: []neoToolCall{
				{ID: "TU-second-one", Name: "Bash", Input: map[string]any{"cmd": "pwd"}},
				{ID: "TU-second-two", Name: "Read", Input: map[string]any{"path": "second.txt"}},
			},
		},
		{Role: "tool", ToolCallID: "TU-second-one", ToolName: "Bash", Text: "workspace"},
		{Role: "tool", ToolCallID: "TU-second-two", ToolName: "Read", Text: "second result"},
		{
			Role: "assistant",
			Text: "latest step",
			ThinkingBlocks: []neoThinkingBlock{
				{Thinking: "latest plan one", Signature: "opaque-latest-signature-one", Provider: "anthropic"},
				{Redacted: true, RedactedData: "opaque-latest-redacted-data", Provider: "anthropic"},
				{Thinking: "unsigned partial plan", Provider: "anthropic"},
				{Thinking: "other provider plan", Signature: "other-provider-signature", Provider: "openai"},
				{Thinking: "", Signature: "opaque-latest-signature-two", Provider: "anthropic"},
			},
			ToolCalls: []neoToolCall{{ID: "TU-latest", Name: "Read", Input: map[string]any{"path": "latest.txt"}}},
		},
		{Role: "tool", ToolCallID: "TU-latest", ToolName: "Read", Text: "latest result"},
	})

	firstContent := arrayValue(mapValue(messages[1])["content"])
	if !reflect.DeepEqual(firstContent, []any{
		map[string]any{"type": "text", "text": "first step"},
		map[string]any{"type": "tool_use", "id": "TU-first", "name": "Read", "input": map[string]any{"path": "first.txt"}},
	}) {
		t.Fatalf("first assistant content = %#v, want stale thinking omitted", firstContent)
	}
	firstResult := mapValue(arrayValue(mapValue(messages[2])["content"])[0])
	if firstResult["type"] != "tool_result" || firstResult["tool_use_id"] != "TU-first" {
		t.Fatalf("first tool result = %#v", firstResult)
	}
	secondContent := arrayValue(mapValue(messages[3])["content"])
	if !reflect.DeepEqual(secondContent, []any{
		map[string]any{"type": "text", "text": "second step"},
		map[string]any{"type": "tool_use", "id": "TU-second-one", "name": "Bash", "input": map[string]any{"cmd": "pwd"}},
		map[string]any{"type": "tool_use", "id": "TU-second-two", "name": "Read", "input": map[string]any{"path": "second.txt"}},
	}) {
		t.Fatalf("second assistant content = %#v, want stale thinking omitted", secondContent)
	}
	for messageIndex, toolCallID := range []string{"TU-second-one", "TU-second-two"} {
		result := mapValue(arrayValue(mapValue(messages[messageIndex+4])["content"])[0])
		if result["type"] != "tool_result" || result["tool_use_id"] != toolCallID {
			t.Fatalf("second tool result %d = %#v", messageIndex, result)
		}
	}
	latestContent := arrayValue(mapValue(messages[6])["content"])
	if !reflect.DeepEqual(latestContent, []any{
		map[string]any{"type": "thinking", "thinking": "latest plan one", "signature": "opaque-latest-signature-one"},
		map[string]any{"type": "redacted_thinking", "data": "opaque-latest-redacted-data"},
		map[string]any{"type": "thinking", "thinking": "", "signature": "opaque-latest-signature-two"},
		map[string]any{"type": "text", "text": "latest step"},
		map[string]any{"type": "tool_use", "id": "TU-latest", "name": "Read", "input": map[string]any{"path": "latest.txt"}},
	}) {
		t.Fatalf("latest assistant content = %#v", latestContent)
	}
	latestResult := mapValue(arrayValue(mapValue(messages[7])["content"])[0])
	if latestResult["type"] != "tool_result" || latestResult["tool_use_id"] != "TU-latest" {
		t.Fatalf("latest tool result = %#v", latestResult)
	}
}

func TestAnthropicNeoMessagesThinkingReplayBoundaries(t *testing.T) {
	tests := []struct {
		name    string
		history []neoHistoryMessage
		want    []any
	}{
		{
			name: "fresh ordinary user request",
			history: []neoHistoryMessage{
				{Role: "user", Text: "old request"},
				{Role: "assistant", Text: "old answer", ThinkingBlocks: []neoThinkingBlock{{Thinking: "stale", Signature: "stale-signature", Provider: "anthropic"}}},
				{Role: "user", Text: "fresh request"},
			},
			want: []any{},
		},
		{
			name: "assistant tool result continuation",
			history: []neoHistoryMessage{
				{Role: "user", Text: "request"},
				{Role: "assistant", ThinkingBlocks: []neoThinkingBlock{{Thinking: "plan", Signature: "signature-one", Provider: "anthropic"}}, ToolCalls: []neoToolCall{{ID: "TU-one", Name: "Read"}}},
				{Role: "tool", ToolCallID: "TU-one", ToolName: "Read", Text: "result"},
			},
			want: []any{map[string]any{"type": "thinking", "thinking": "plan", "signature": "signature-one"}},
		},
		{
			name: "multiple tool results",
			history: []neoHistoryMessage{
				{Role: "user", Text: "request"},
				{
					Role: "assistant",
					ThinkingBlocks: []neoThinkingBlock{
						{Thinking: "plan", Signature: "signature-one", Provider: "anthropic"},
						{Redacted: true, RedactedData: "redacted-two", Provider: "anthropic"},
					},
					ToolCalls: []neoToolCall{{ID: "TU-one", Name: "Read"}, {ID: "TU-two", Name: "Bash"}},
				},
				{Role: "tool", ToolCallID: "TU-one", ToolName: "Read", Text: "first result"},
				{Role: "tool", ToolCallID: "TU-two", ToolName: "Bash", Text: "second result"},
			},
			want: []any{
				map[string]any{"type": "thinking", "thinking": "plan", "signature": "signature-one"},
				map[string]any{"type": "redacted_thinking", "data": "redacted-two"},
			},
		},
		{
			name: "multiple assistant tool result rounds",
			history: []neoHistoryMessage{
				{Role: "user", Text: "request"},
				{Role: "assistant", ThinkingBlocks: []neoThinkingBlock{{Thinking: "stale plan", Signature: "stale-signature", Provider: "anthropic"}}, ToolCalls: []neoToolCall{{ID: "TU-old", Name: "Read"}}},
				{Role: "tool", ToolCallID: "TU-old", ToolName: "Read", Text: "old result"},
				{Role: "assistant", ThinkingBlocks: []neoThinkingBlock{{Thinking: "latest plan", Signature: "latest-signature", Provider: "anthropic"}}, ToolCalls: []neoToolCall{{ID: "TU-latest", Name: "Bash"}}},
				{Role: "tool", ToolCallID: "TU-latest", ToolName: "Bash", Text: "latest result"},
			},
			want: []any{map[string]any{"type": "thinking", "thinking": "latest plan", "signature": "latest-signature"}},
		},
		{
			name: "noncontiguous tool result after ordinary user",
			history: []neoHistoryMessage{
				{Role: "user", Text: "request"},
				{Role: "assistant", ThinkingBlocks: []neoThinkingBlock{{Thinking: "stale plan", Signature: "stale-signature", Provider: "anthropic"}}, ToolCalls: []neoToolCall{{ID: "TU-old", Name: "Read"}}},
				{Role: "user", Text: "new request"},
				{Role: "tool", ToolCallID: "TU-old", ToolName: "Read", Text: "late result"},
			},
			want: []any{},
		},
		{
			name: "history ending in assistant",
			history: []neoHistoryMessage{
				{Role: "user", Text: "request"},
				{Role: "assistant", Text: "old answer", ThinkingBlocks: []neoThinkingBlock{{Thinking: "stale", Signature: "stale-signature", Provider: "anthropic"}}},
				{Role: "assistant", Text: "answer", ThinkingBlocks: []neoThinkingBlock{{Thinking: "plan", Signature: "signature-one", Provider: "anthropic"}}},
			},
			want: []any{map[string]any{"type": "thinking", "thinking": "plan", "signature": "signature-one"}},
		},
		{
			name: "no user entries",
			history: []neoHistoryMessage{
				{Role: "assistant", Text: "old answer", ThinkingBlocks: []neoThinkingBlock{{Thinking: "stale", Signature: "stale-signature", Provider: "anthropic"}}},
				{Role: "assistant", Text: "answer", ThinkingBlocks: []neoThinkingBlock{{Thinking: "plan", Signature: "signature-one", Provider: "anthropic"}}},
			},
			want: []any{map[string]any{"type": "thinking", "thinking": "plan", "signature": "signature-one"}},
		},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			messages := anthropicNeoMessages(test.history)
			got := make([]any, 0)
			for _, rawMessage := range messages {
				message := mapValue(rawMessage)
				if message["role"] != "assistant" {
					continue
				}
				for _, rawBlock := range arrayValue(message["content"]) {
					block := mapValue(rawBlock)
					if block["type"] == "thinking" || block["type"] == "redacted_thinking" {
						got = append(got, block)
					}
				}
			}
			if !reflect.DeepEqual(got, test.want) {
				t.Fatalf("thinking blocks = %#v, want %#v", got, test.want)
			}
		})
	}
}

