func TestInferNeoAnthropicStreamMatchesBinaryRequestEnvelope(t *testing.T) {
	calls := 0
	upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/api/provider/anthropic/v1/messages" {
			t.Fatalf("unexpected path %s", r.URL.Path)
		}
		payload := readNeoJSON(r.Body)
		if payload["stream"] != true {
			t.Fatalf("stream = %#v, want true", payload["stream"])
		}
		if got := numberFrom(payload["max_tokens"]); got != 64000 {
			t.Fatalf("max_tokens = %d, want binary thread maxTokens override 64000; payload=%#v", got, payload)
		}
		if _, ok := payload["context_management"]; ok {
			t.Fatalf("request included context_management, but current Amp binary omits it: %#v", payload)
		}
		if beta := r.Header.Get("Anthropic-Beta"); strings.Contains(beta, "context-management") {
			t.Fatalf("Anthropic-Beta = %q, want no context-management beta", beta)
		}

		calls++
		w.Header().Set("Content-Type", "text/event-stream")
		_, _ = w.Write([]byte("event: message_start\n" +
			`data: {"type":"message_start","message":{"usage":{"input_tokens":3}}}` + "\n\n" +
			"event: content_block_start\n" +
			`data: {"type":"content_block_start","index":0,"content_block":{"type":"text","text":""}}` + "\n\n" +
			"event: content_block_delta\n" +
			`data: {"type":"content_block_delta","index":0,"delta":{"type":"text_delta","text":"retried"}}` + "\n\n" +
			"event: message_stop\n" +
			`data: {"type":"message_stop"}` + "\n\n"))
	}))
	defer upstream.Close()

	var deltas []string
	result, err := inferNeoLocalStream(testNeoRuntimeForServer(t, upstream), neoInferenceRequest{
		ThreadID:  "T-test",
		AgentMode: "smart",
		MaxTokens: 64000,
		Settings:  map[string]any{"internal.model": "anthropic/claude-test"},
		History:   []neoHistoryMessage{{Role: "user", Text: "hi"}},
	}, func(delta neoInferenceDelta) {
		deltas = append(deltas, delta.Text)
	})
	if err != nil {
		t.Fatalf("inferNeoLocalStream error: %v", err)
	}
	if calls != 1 {
		t.Fatalf("calls=%d, want 1", calls)
	}
	if result.Text != "retried" || strings.Join(deltas, "") != "retried" {
		t.Fatalf("text=%q deltas=%#v", result.Text, deltas)
	}
}

func TestInferNeoAnthropicCanDisableParallelToolCalls(t *testing.T) {
	for _, stream := range []bool{false, true} {
		t.Run(fmt.Sprintf("stream_%t", stream), func(t *testing.T) {
			upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				toolChoice := mapValue(readNeoJSON(r.Body)["tool_choice"])
				if toolChoice["type"] != "auto" || toolChoice["disable_parallel_tool_use"] != true {
					t.Fatalf("tool_choice = %#v, want auto with parallel use disabled", toolChoice)
				}
				if stream {
					w.Header().Set("Content-Type", "text/event-stream")
					_, _ = w.Write([]byte("event: message_start\n" +
						`data: {"type":"message_start","message":{"usage":{"input_tokens":1}}}` + "\n\n" +
						"event: content_block_start\n" +
						`data: {"type":"content_block_start","index":0,"content_block":{"type":"text","text":""}}` + "\n\n" +
						"event: content_block_delta\n" +
						`data: {"type":"content_block_delta","index":0,"delta":{"type":"text_delta","text":"ok"}}` + "\n\n" +
						"event: message_stop\n" +
						`data: {"type":"message_stop"}` + "\n\n"))
					return
				}
				w.Header().Set("Content-Type", "application/json")
				_, _ = w.Write([]byte(`{"content":[{"type":"text","text":"ok"}]}`))
			}))
			defer upstream.Close()

			request := neoInferenceRequest{
				ThreadID:                 "T-anthropic-sequential-tools",
				History:                  []neoHistoryMessage{{Role: "user", Text: "search"}},
				Tools:                    []neoToolSpec{{Name: "search_thread_messages", InputSchema: map[string]any{"type": "object"}}},
				DisableParallelToolCalls: true,
			}
			var err error
			if stream {
				_, err = inferNeoAnthropicStream(testNeoRuntimeForServer(t, upstream), request, neoModelRoute{Provider: "anthropic", Model: "claude-test"}, nil)
			} else {
				_, err = inferNeoAnthropic(testNeoRuntimeForServer(t, upstream), request, neoModelRoute{Provider: "anthropic", Model: "claude-test"})
			}
			if err != nil {
				t.Fatalf("Anthropic inference stream=%v error: %v", stream, err)
			}
		})
	}
}

func TestInferNeoAnthropicStreamRejectsMaxTokensStopReason(t *testing.T) {
	upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/api/provider/anthropic/v1/messages" {
			t.Fatalf("unexpected path %s", r.URL.Path)
		}
		w.Header().Set("Content-Type", "text/event-stream")
		_, _ = w.Write([]byte("event: message_start\n" +
			`data: {"type":"message_start","message":{"usage":{"input_tokens":3}}}` + "\n\n" +
			"event: content_block_start\n" +
			`data: {"type":"content_block_start","index":0,"content_block":{"type":"tool_use","id":"toolu_create","name":"create_file","input":{}}}` + "\n\n" +
			"event: content_block_delta\n" +
			`data: {"type":"content_block_delta","index":0,"delta":{"type":"input_json_delta","partial_json":"{\"path\":\"/tmp/setup.c\""}}` + "\n\n" +
			"event: message_delta\n" +
			`data: {"type":"message_delta","delta":{"stop_reason":"max_tokens"},"usage":{"input_tokens":3,"output_tokens":32000}}` + "\n\n" +
			"event: message_stop\n" +
			`data: {"type":"message_stop"}` + "\n\n" +
			"data: [DONE]\n\n"))
	}))
	defer upstream.Close()

	deltaCalls := 0
	_, err := inferNeoLocalStream(testNeoRuntimeForServer(t, upstream), neoInferenceRequest{
		ThreadID:  "T-test",
		AgentMode: "smart",
		Settings:  map[string]any{"internal.model": "anthropic/claude-test"},
		History:   []neoHistoryMessage{{Role: "user", Text: "hi"}},
		Tools:     []neoToolSpec{{Name: "create_file", Description: "create a file", InputSchema: map[string]any{"type": "object"}}},
	}, func(delta neoInferenceDelta) {
		if delta.ToolCall != nil {
			deltaCalls++
		}
	})
	if err == nil || !strings.Contains(err.Error(), "max_tokens") {
		t.Fatalf("error = %v, want max_tokens", err)
	}
	if deltaCalls == 0 {
		t.Fatalf("deltaCalls=%d, want partial tool delta before max_tokens error", deltaCalls)
	}
}

