func TestInferNeoAnthropicAppliesTemperatureOnlyWhenThinkingDisabled(t *testing.T) {
	tests := []struct {
		name           string
		request        neoInferenceRequest
		wantTemp       bool
		wantNoThinking bool
	}{
		{
			name: "reasoning none",
			request: neoInferenceRequest{
				ThreadID:        "T-test",
				AgentMode:       "smart",
				ReasoningEffort: "none",
				Settings:        map[string]any{"anthropic.temperature": 0.7},
				History:         []neoHistoryMessage{{Role: "user", Text: "hi"}},
			},
			wantTemp:       true,
			wantNoThinking: true,
		},
		{
			name: "setting disabled",
			request: neoInferenceRequest{
				ThreadID:        "T-test",
				AgentMode:       "smart",
				ReasoningEffort: "high",
				Settings:        map[string]any{"anthropic.temperature": 0.7, "anthropic.thinking.enabled": false},
				History:         []neoHistoryMessage{{Role: "user", Text: "hi"}},
			},
			wantTemp:       true,
			wantNoThinking: true,
		},
		{
			name: "default disabled",
			request: neoInferenceRequest{
				ThreadID:        "T-test",
				AgentMode:       "smart",
				ReasoningEffort: "high",
				History:         []neoHistoryMessage{{Role: "user", Text: "hi"}},
			},
			wantNoThinking: true,
		},
		{
			name: "thinking enabled",
			request: neoInferenceRequest{
				ThreadID:        "T-test",
				AgentMode:       "smart",
				ReasoningEffort: "high",
				Settings:        map[string]any{"anthropic.temperature": 0.7, "anthropic.thinking.enabled": true},
				History:         []neoHistoryMessage{{Role: "user", Text: "hi"}},
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				if r.URL.Path != "/api/provider/anthropic/v1/messages" {
					t.Fatalf("unexpected path %s", r.URL.Path)
				}
				payload := readNeoJSON(r.Body)
				if tt.wantTemp {
					if temp, ok := payload["temperature"].(float64); !ok || temp != 0.7 {
						t.Fatalf("temperature = %#v, want 0.7; payload=%#v", payload["temperature"], payload)
					}
				} else if _, exists := payload["temperature"]; exists {
					t.Fatalf("temperature should be omitted while thinking is enabled: %#v", payload)
				}
				if tt.wantNoThinking {
					if _, exists := payload["thinking"]; exists {
						t.Fatalf("thinking should be omitted when disabled for non-adaptive Anthropic models: %#v", payload)
					}
				} else {
					thinkingBody := mapValue(payload["thinking"])
					if stringValue(thinkingBody["type"]) != "enabled" {
						t.Fatalf("thinking = %#v, want enabled", thinkingBody)
					}
				}
				w.Header().Set("Content-Type", "application/json")
				_, _ = w.Write([]byte(`{"content":[{"type":"text","text":"ok"}]}`))
			}))
			defer upstream.Close()

			result, err := inferNeoAnthropic(testNeoRuntimeForServer(t, upstream), tt.request, neoModelRoute{Provider: "anthropic", Model: "claude-test"})
			if err != nil {
				t.Fatalf("inferNeoAnthropic error: %v", err)
			}
			if result.Text != "ok" {
				t.Fatalf("text=%q, want ok", result.Text)
			}
		})
	}
}

func TestInferNeoAnthropicStreamRetriesWithAdaptiveThinkingWhenEnabledUnsupported(t *testing.T) {
	calls := 0
	upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/api/provider/anthropic/v1/messages" {
			t.Fatalf("unexpected path %s", r.URL.Path)
		}
		payload := readNeoJSON(r.Body)
		if payload["stream"] != true {
			t.Fatalf("stream = %#v, want true", payload["stream"])
		}

		calls++
		switch calls {
		case 1:
			thinkingBody := mapValue(payload["thinking"])
			if stringValue(thinkingBody["type"]) != "enabled" || numberFrom(thinkingBody["budget_tokens"]) == 0 {
				t.Fatalf("first request thinking = %#v, want enabled with budget", thinkingBody)
			}
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(http.StatusBadRequest)
			_, _ = w.Write([]byte(`{"type":"error","error":{"type":"invalid_request_error","message":"\"thinking.type.enabled\" is not supported for this model. Use \"thinking.type.adaptive\" and \"output_config.effort\" to control thinking behavior."}}`))
		case 2:
			thinkingBody := mapValue(payload["thinking"])
			if stringValue(thinkingBody["type"]) != "adaptive" {
				t.Fatalf("retry request thinking = %#v, want adaptive", thinkingBody)
			}
			if _, ok := thinkingBody["budget_tokens"]; ok {
				t.Fatalf("retry request retained thinking budget: %#v", thinkingBody)
			}
			if effort := stringValue(mapValue(payload["output_config"])["effort"]); effort != "high" {
				t.Fatalf("retry request effort = %q, want high; payload=%#v", effort, payload)
			}
			w.Header().Set("Content-Type", "text/event-stream")
			_, _ = w.Write([]byte("event: message_start\n" +
				`data: {"type":"message_start","message":{"usage":{"input_tokens":3}}}` + "\n\n" +
				"event: content_block_delta\n" +
				`data: {"type":"content_block_delta","index":0,"delta":{"type":"text_delta","text":"adaptive"}}` + "\n\n" +
				"event: message_stop\n" +
				`data: {"type":"message_stop"}` + "\n\n"))
		default:
			t.Fatalf("unexpected retry call %d", calls)
		}
	}))
	defer upstream.Close()

	var deltas []string
	result, err := inferNeoLocalStream(testNeoRuntimeForServer(t, upstream), neoInferenceRequest{
		ThreadID:        "T-test",
		AgentMode:       "smart",
		ReasoningEffort: "high",
		Settings:        map[string]any{"internal.model": "anthropic/claude-test", "anthropic.thinking.enabled": true},
		History:         []neoHistoryMessage{{Role: "user", Text: "hi"}},
	}, func(delta neoInferenceDelta) {
		deltas = append(deltas, delta.Text)
	})
	if err != nil {
		t.Fatalf("inferNeoLocalStream error: %v", err)
	}
	if calls != 2 {
		t.Fatalf("calls=%d, want 2", calls)
	}
	if result.Text != "adaptive" || strings.Join(deltas, "") != "adaptive" {
		t.Fatalf("text=%q deltas=%#v", result.Text, deltas)
	}
}

func TestInferNeoAnthropicRetriesWithAdaptiveThinkingOnlyOnce(t *testing.T) {
	for _, stream := range []bool{false, true} {
		t.Run(fmt.Sprintf("stream=%v", stream), func(t *testing.T) {
			calls := 0
			upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				calls++
				payload := readNeoJSON(r.Body)
				if payload["stream"] != stream {
					t.Fatalf("stream = %#v, want %v", payload["stream"], stream)
				}
				w.Header().Set("Content-Type", "application/json")
				w.WriteHeader(http.StatusBadRequest)
				_, _ = w.Write([]byte(`{"type":"error","error":{"type":"invalid_request_error","message":"\"thinking.type.enabled\" is not supported for this model. Use \"thinking.type.adaptive\" and \"output_config.effort\" to control thinking behavior."}}`))
			}))
			defer upstream.Close()

			request := neoInferenceRequest{
				ThreadID:        "T-test",
				AgentMode:       "smart",
				ReasoningEffort: "high",
				Settings:        map[string]any{"anthropic.thinking.enabled": true},
				History:         []neoHistoryMessage{{Role: "user", Text: "hi"}},
			}
			route := neoModelRoute{Provider: "anthropic", Model: "claude-test"}
			var err error
			if stream {
				_, err = inferNeoAnthropicStream(testNeoRuntimeForServer(t, upstream), request, route, nil)
			} else {
				_, err = inferNeoAnthropic(testNeoRuntimeForServer(t, upstream), request, route)
			}
			if err == nil {
				t.Fatal("persistent enabled-thinking rejection unexpectedly succeeded")
			}
			if calls != 2 {
				t.Fatalf("calls = %d, want one initial request and one adaptive retry", calls)
			}
		})
	}
}

func TestInferNeoAnthropicStreamRetriesWithoutRejectedThinkingSignature(t *testing.T) {
	calls := 0
	upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		payload := readNeoJSON(r.Body)
		messages := arrayValue(payload["messages"])
		calls++
		switch calls {
		case 1:
			assistantContent := arrayValue(mapValue(messages[1])["content"])
			if block := mapValue(assistantContent[0]); block["type"] != "thinking" || block["signature"] != "rejected-signature" {
				t.Fatalf("first request thinking = %#v", block)
			}
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(http.StatusBadRequest)
			_, _ = w.Write([]byte(`{"type":"error","error":{"type":"invalid_request_error","message":"messages.1.content.0: Invalid signature in thinking block"}}`))
		case 2:
			for _, rawMessage := range messages {
				for _, rawBlock := range arrayValue(mapValue(rawMessage)["content"]) {
					blockType := stringValue(mapValue(rawBlock)["type"])
					if blockType == "thinking" || blockType == "redacted_thinking" {
						t.Fatalf("retry retained %s block: %#v", blockType, payload)
					}
				}
			}
			assistantContent := arrayValue(mapValue(messages[1])["content"])
			if len(assistantContent) != 2 || stringValue(mapValue(assistantContent[0])["text"]) != "checking" || stringValue(mapValue(assistantContent[1])["type"]) != "tool_use" {
				t.Fatalf("retry changed assistant continuation: %#v", assistantContent)
			}
			w.Header().Set("Content-Type", "text/event-stream")
			_, _ = w.Write([]byte("event: message_start\n" +
				`data: {"type":"message_start","message":{"usage":{"input_tokens":3}}}` + "\n\n" +
				"event: content_block_delta\n" +
				`data: {"type":"content_block_delta","index":0,"delta":{"type":"text_delta","text":"continued"}}` + "\n\n" +
				"event: message_stop\n" +
				`data: {"type":"message_stop"}` + "\n\n"))
		default:
			t.Fatalf("unexpected retry call %d", calls)
		}
	}))
	defer upstream.Close()

	result, err := inferNeoAnthropicStream(testNeoRuntimeForServer(t, upstream), neoInferenceRequest{
		ThreadID: "T-test",
		Settings: map[string]any{},
		History: []neoHistoryMessage{
			{Role: "user", Text: "inspect"},
			{
				Role:           "assistant",
				Text:           "checking",
				ThinkingBlocks: []neoThinkingBlock{{Thinking: "plan", Signature: "rejected-signature", Provider: "anthropic"}},
				ToolCalls:      []neoToolCall{{ID: "TU-test", Name: "Read", Input: map[string]any{"path": "file.go"}}},
			},
			{Role: "tool", ToolCallID: "TU-test", Text: "contents"},
		},
	}, neoModelRoute{Provider: "anthropic", Model: "claude-test"}, nil)
	if err != nil {
		t.Fatalf("inferNeoAnthropicStream error: %v", err)
	}
	if calls != 2 || result.Text != "continued" {
		t.Fatalf("calls=%d text=%q, want 2 and continued", calls, result.Text)
	}
}

func TestInferNeoAnthropicOmitsThinkingWhenDisabled(t *testing.T) {
	upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/api/provider/anthropic/v1/messages" {
			t.Fatalf("unexpected path %s", r.URL.Path)
		}
		if beta := r.Header.Get("Anthropic-Beta"); strings.Contains(beta, neoAnthropicInterleavedThinkingBeta) {
			t.Fatalf("Anthropic-Beta = %q, want no interleaved thinking beta", beta)
		}
		payload := readNeoJSON(r.Body)
		if _, exists := payload["thinking"]; exists {
			t.Fatalf("thinking should be omitted when disabled: %#v", payload)
		}
		if outputConfig := mapValue(payload["output_config"]); len(outputConfig) > 0 {
			t.Fatalf("output_config should be omitted when disabled: %#v", payload)
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"content":[{"type":"text","text":"ok"}]}`))
	}))
	defer upstream.Close()

	result, err := inferNeoAnthropic(testNeoRuntimeForServer(t, upstream), neoInferenceRequest{
		ThreadID:                 "T-test",
		AgentMode:                "smart",
		ReasoningEffort:          "xhigh",
		DisableProviderReasoning: true,
		Settings:                 map[string]any{"anthropic.interleavedThinking.enabled": true, "anthropic.thinking.enabled": true},
		History:                  []neoHistoryMessage{{Role: "user", Text: "hi"}},
	}, neoModelRoute{Provider: "anthropic", Model: "claude-test"})
	if err != nil {
		t.Fatalf("inferNeoAnthropic error: %v", err)
	}
	if result.Text != "ok" {
		t.Fatalf("text = %q, want ok", result.Text)
	}
}

