func TestNeoRuntimeColdLocalThreadImportPreservesConversationState(t *testing.T) {
	enabled := true
	threadID := "T-019f5464-6bb4-7d2b-8faa-f093660aaab9"
	dir := t.TempDir()
	thread := map[string]any{
		"id":              threadID,
		"v":               41,
		"title":           "persisted conversation",
		"agentMode":       "deep",
		"reasoningEffort": "xhigh",
		"meta":            map[string]any{"ampcodeConnectorLocalNeo": true, "projectName": "memory-profile"},
		"messages": []any{
			map[string]any{
				"messageId":       "M-0000000000000000000001",
				"role":            "user",
				"agentMode":       "deep",
				"reasoningEffort": "xhigh",
				"content":         []any{map[string]any{"type": "text", "text": "preserve the complete conversation"}},
			},
			map[string]any{
				"messageId": "M-0000000000000000000002",
				"role":      "assistant",
				"state":     map[string]any{"type": "cancelled"},
				"content": []any{
					map[string]any{"type": "thinking", "thinking": "reasoning", "blockState": "complete"},
					map[string]any{"type": "tool_use", "id": "TU-stable", "name": "shell_command", "input": map[string]any{"command": "go test ./..."}},
				},
			},
			map[string]any{
				"messageId": "M-0000000000000000000003",
				"role":      "user",
				"content": []any{map[string]any{
					"type":      "tool_result",
					"toolUseID": "TU-stable",
					"content":   []any{map[string]any{"type": "text", "text": "all tests passed"}},
				}},
			},
			map[string]any{
				"messageId": "M-0000000000000000000004",
				"role":      "info",
				"content": []any{
					map[string]any{"type": "summary", "summary": "preserved summary", "content": "preserved summary"},
					map[string]any{"type": "manual_bash_invocation", "command": "git status --short"},
				},
			},
		},
		"compactionRecords": []any{map[string]any{
			"cutMessageId": "M-0000000000000000000001",
			"summary":      "preserved summary",
			"createdAt":    "2026-07-12T20:00:00Z",
		}},
		"relationships": []any{map[string]any{
			"threadID": "T-019f5464-6bb4-7d2b-8faa-f093660aaa00",
			"type":     "mention",
			"role":     "parent",
		}},
	}
	if _, err := writeNeoLocalThreadFileInDir(dir, threadID, thread); err != nil {
		t.Fatalf("write local thread: %v", err)
	}
	rt := newNeoRuntime(&config.Config{AmpCode: config.AmpCode{NeoLocalRuntime: config.AmpNeoLocalRuntime{Enabled: &enabled}}})
	rt.threadDir = dir

	if !rt.tryImportNeoLocalThreadActor(threadID) {
		t.Fatal("cold local thread import failed")
	}
	actor := rt.store.lookupThreadActor(threadID)
	if actor == nil {
		t.Fatal("cold local thread actor missing")
	}
	actor.mu.Lock()
	defer actor.mu.Unlock()
	if actor.title != "persisted conversation" || actor.currentAgentMode != "deep" || actor.currentReasoningEffort != "xhigh" {
		t.Fatalf("actor state = title:%q mode:%q effort:%q", actor.title, actor.currentAgentMode, actor.currentReasoningEffort)
	}
	wantIDs := []string{"M-0000000000000000000001", "M-0000000000000000000002", "M-0000000000000000000003", "M-0000000000000000000004"}
	if len(actor.messages) != len(wantIDs) {
		t.Fatalf("messages = %d, want %d", len(actor.messages), len(wantIDs))
	}
	for index, wantID := range wantIDs {
		if actor.messages[index].MessageID != wantID {
			t.Fatalf("message %d id = %q, want %q", index, actor.messages[index].MessageID, wantID)
		}
	}
	if got := mapValue(actor.messages[1].Content[1]); got["id"] != "TU-stable" || stringValue(mapValue(got["input"])["command"]) != "go test ./..." {
		t.Fatalf("tool use = %#v", got)
	}
	if got := mapValue(actor.messages[2].Content[0]); got["toolUseID"] != "TU-stable" || textFromBlocks(arrayValue(got["content"])) != "all tests passed" {
		t.Fatalf("tool result = %#v", got)
	}
	if len(actor.messages[3].Content) != 2 || stringValue(mapValue(actor.messages[3].Content[0])["type"]) != "summary" || stringValue(mapValue(actor.messages[3].Content[1])["type"]) != "manual_bash_invocation" {
		t.Fatalf("compaction message = %#v", actor.messages[3].Content)
	}
	if len(actor.compactionRecords) != 1 || stringValue(actor.compactionRecords[0]["cutMessageId"]) != "M-0000000000000000000001" {
		t.Fatalf("compaction records = %#v", actor.compactionRecords)
	}
	if len(actor.relationships) != 1 || len(actor.replayEvents) != 0 {
		t.Fatalf("relationships/replay = %#v/%#v", actor.relationships, actor.replayEvents)
	}
}

func TestNeoRuntimeConcurrentColdLocalThreadImportsShareHydratedActor(t *testing.T) {
	enabled := true
	threadID := "T-019f5464-6bb4-7d2b-8faa-f093660aaaba"
	dir := t.TempDir()
	if _, err := writeNeoLocalThreadFileInDir(dir, threadID, map[string]any{
		"id":        threadID,
		"agentMode": "deep",
		"meta":      map[string]any{"ampcodeConnectorLocalNeo": true},
		"messages": []any{
			map[string]any{"messageId": "M-0000000000000000000001", "role": "user", "content": []any{map[string]any{"type": "text", "text": "hydrate once"}}},
		},
	}); err != nil {
		t.Fatalf("write local thread: %v", err)
	}
	rt := newNeoRuntime(&config.Config{AmpCode: config.AmpCode{NeoLocalRuntime: config.AmpNeoLocalRuntime{Enabled: &enabled}}})
	rt.threadDir = dir

	start := make(chan struct{})
	results := make(chan bool, 16)
	var workers sync.WaitGroup
	for range 16 {
		workers.Add(1)
		go func() {
			defer workers.Done()
			<-start
			results <- rt.tryImportNeoLocalThreadActor(threadID)
		}()
	}
	close(start)
	workers.Wait()
	close(results)
	for imported := range results {
		if !imported {
			t.Fatal("concurrent local thread import failed")
		}
	}
	rt.store.mu.Lock()
	actorCount := len(rt.store.actors)
	rt.store.mu.Unlock()
	if actorCount != 1 {
		t.Fatalf("actor count = %d, want 1", actorCount)
	}
	actor := rt.store.lookupThreadActor(threadID)
	actor.mu.Lock()
	defer actor.mu.Unlock()
	if len(actor.messages) != 1 || actor.messages[0].MessageID != "M-0000000000000000000001" || textFromBlocks(actor.messages[0].Content) != "hydrate once" {
		t.Fatalf("hydrated messages = %#v", actor.messages)
	}
}

func TestNeoActorImportRestoresPendingToolForPayloadRequiredStatusOnlyDone(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})
	threadID := "T-019eb741-4031-702e-a552-6824b09e3aea"
	userMessageID := newNeoMessageID()
	assistantMessageID := newNeoMessageID()
	resultMessageID := newNeoMessageID()
	actor := newNeoActor(rt, "actor-pending-tool", "thread-actor", threadID, threadID, neoActorRecord("actor-pending-tool", "thread-actor", threadID), nil)
	thread := map[string]any{
		"id":        threadID,
		"agentMode": "deep",
		"messages": []any{
			map[string]any{"messageId": userMessageID, "role": "user", "agentMode": "deep", "reasoningEffort": "xhigh", "content": []any{map[string]any{"type": "text", "text": "ship it"}}},
			map[string]any{
				"messageId": assistantMessageID,
				"role":      "assistant",
				"state":     map[string]any{"type": "complete", "stopReason": "tool_use"},
				"content": []any{map[string]any{
					"type":  "tool_use",
					"id":    "TU-review",
					"name":  "shell_command",
					"input": map[string]any{"command": "amp review", "timeout_ms": 1200000},
				}},
			},
			map[string]any{
				"messageId": resultMessageID,
				"role":      "user",
				"content": []any{map[string]any{
					"type":      "tool_result",
					"toolUseID": "TU-review",
					"run":       map[string]any{"status": "done"},
				}},
			},
		},
	}
	if err := actor.importThreadLocalOnly(thread); err != nil {
		t.Fatalf("import thread: %v", err)
	}

	actor.mu.Lock()
	if actor.agentState != "running_tools" {
		actor.mu.Unlock()
		t.Fatalf("agentState = %q, want running_tools", actor.agentState)
	}
	pending, ok := actor.pendingTools["TU-review"]
	if !ok {
		actor.mu.Unlock()
		t.Fatalf("pendingTools = %#v, want restored shell_command lease", actor.pendingTools)
	}
	if pending.Name != "shell_command" || pending.AgentMode != "deep" || pending.ReasoningEffort != "xhigh" || pending.MessageID != assistantMessageID {
		actor.mu.Unlock()
		t.Fatalf("pending = %#v, want restored deep/xhigh shell command", pending)
	}
	if actor.messages[2].CompletionStatus != "tool_progress" {
		actor.mu.Unlock()
		t.Fatalf("completionStatus = %q, want tool_progress", actor.messages[2].CompletionStatus)
	}
	if len(actor.history) != 2 {
		actor.mu.Unlock()
		t.Fatalf("history = %#v, want status-only done omitted", actor.history)
	}
	actor.mu.Unlock()

	actor.handle(map[string]any{
		"type":    "tool:data",
		"toolUse": "TU-review",
		"data": map[string]any{
			"status": "done",
			"result": map[string]any{"exitCode": 0, "output": "review clean\n"},
		},
	})

	actor.mu.Lock()
	defer actor.mu.Unlock()
	if _, ok := actor.pendingTools["TU-review"]; ok {
		t.Fatalf("pending tool remained after full result: %#v", actor.pendingTools)
	}
	if actor.messages[2].CompletionStatus != "" {
		t.Fatalf("final completionStatus = %q, want cleared", actor.messages[2].CompletionStatus)
	}
	if actor.pendingInference == nil || actor.pendingInference.agentMode != "deep" || actor.pendingInference.reasoningEffort != "xhigh" {
		t.Fatalf("pendingInference = %#v, want continuation after restored pending tool completes", actor.pendingInference)
	}
	if len(actor.history) != 3 || !strings.Contains(actor.history[2].Text, "review clean") {
		t.Fatalf("history = %#v, want full shell_command result after completion", actor.history)
	}
}

func TestNeoActorImportClassifiesRunTerminalCommandAlias(t *testing.T) {
	tests := []struct {
		name            string
		toolName        string
		wantPendingName string
		wantCompletion  string
		wantAgentState  string
	}{
		{name: "exact alias", toolName: "run_terminal_command", wantPendingName: "Bash", wantCompletion: "tool_progress", wantAgentState: "running_tools"},
		{name: "near miss", toolName: "run_terminal_commands", wantAgentState: "idle"},
	}
	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			threadID := "T-019eb741-4031-702e-a552-6824b09e3aeb"
			actor := newNeoActor(nil, "actor-terminal-alias", "thread-actor", threadID, threadID, neoActorRecord("actor-terminal-alias", "thread-actor", threadID), nil)
			thread := map[string]any{
				"id":        threadID,
				"agentMode": "deep",
				"messages": []any{
					map[string]any{
						"messageId": "M-0000000000000000000001",
						"role":      "assistant",
						"content": []any{map[string]any{
							"type": "tool_use",
							"id":   "TU-terminal-alias",
							"name": test.toolName,
						}},
					},
					map[string]any{
						"messageId": "M-0000000000000000000002",
						"role":      "user",
						"content": []any{map[string]any{
							"type":      "tool_result",
							"toolUseID": "TU-terminal-alias",
							"run":       map[string]any{"status": "done"},
						}},
					},
				},
			}
			if err := actor.importThreadLocalOnly(thread); err != nil {
				t.Fatalf("import thread: %v", err)
			}
			if actor.messages[1].CompletionStatus != test.wantCompletion {
				t.Fatalf("completionStatus = %q, want %q", actor.messages[1].CompletionStatus, test.wantCompletion)
			}
			if actor.agentState != test.wantAgentState {
				t.Fatalf("agentState = %q, want %q", actor.agentState, test.wantAgentState)
			}
			pending, ok := actor.pendingTools["TU-terminal-alias"]
			if test.wantPendingName == "" {
				if ok {
					t.Fatalf("pending tool = %#v, want completed near miss", pending)
				}
				return
			}
			if !ok || pending.Name != test.wantPendingName {
				t.Fatalf("pending tool = %#v, want %q", pending, test.wantPendingName)
			}
		})
	}
}

func TestNeoActorImportRunsPendingInferenceWhenExecutorAlreadyReady(t *testing.T) {
	started := make(chan struct{})
	release := make(chan struct{})
	var startedOnce sync.Once
	var releaseOnce sync.Once
	upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/api/provider/openai/v1/responses" {
			t.Fatalf("unexpected path %s", r.URL.Path)
		}
		startedOnce.Do(func() { close(started) })
		w.Header().Set("Content-Type", "text/event-stream")
		flusher, _ := w.(http.Flusher)
		_, _ = w.Write([]byte(`data: {"type":"response.output_text.delta","output_index":0,"content_index":0,"delta":"resumed"}` + "\n\n"))
		if flusher != nil {
			flusher.Flush()
		}
		select {
		case <-release:
		case <-time.After(2 * time.Second):
		}
		_, _ = w.Write([]byte(`data: {"type":"response.completed","response":{"usage":{"input_tokens":1,"output_tokens":1},"output":[]}}` + "\n\n"))
		_, _ = w.Write([]byte("data: [DONE]\n\n"))
		if flusher != nil {
			flusher.Flush()
		}
	}))
	t.Cleanup(upstream.Close)
	t.Cleanup(func() { releaseOnce.Do(func() { close(release) }) })

	rt := testNeoRuntimeForServer(t, upstream)
	threadID := "T-019e6541-06ae-75d7-b10e-d893170fa62c"
	actor := newNeoActor(rt, "actor-ready-import", "thread-actor", threadID, threadID, neoActorRecord("actor-ready-import", "thread-actor", threadID), nil)
	actor.mu.Lock()
	actor.executorID = "neo-ready"
	actor.executorReady = true
	actor.executorBootstrapComplete = true
	actor.mu.Unlock()

	thread := map[string]any{
		"id":        threadID,
		"agentMode": "deep",
		"messages": []any{
			map[string]any{"messageId": "M-user", "role": "user", "agentMode": "deep", "reasoningEffort": "xhigh", "content": []any{map[string]any{"type": "text", "text": "continue after restart"}}},
			map[string]any{"messageId": "M-cancelled", "role": "assistant", "state": map[string]any{"type": "cancelled"}, "content": []any{map[string]any{"type": "text", "text": "partial"}}},
		},
		"pendingInference": map[string]any{"messageId": "M-cancelled", "agentMode": "deep", "reasoningEffort": "xhigh", "preflightCompactionChecked": true},
	}
	if err := actor.importThreadLocalOnly(thread); err != nil {
		t.Fatalf("import thread: %v", err)
	}

	select {
	case <-started:
	case <-time.After(2 * time.Second):
		t.Fatal("pending inference did not start after import")
	}
	actor.mu.Lock()
	state := actor.agentState
	pending := actor.pendingInference
	current := actor.currentInference
	actor.mu.Unlock()
	if pending != nil {
		t.Fatalf("pendingInference = %#v, want consumed", pending)
	}
	if current == nil || current.agentMode != "deep" || current.reasoningEffort != "xhigh" {
		t.Fatalf("currentInference = %#v, want resumed deep/xhigh inference", current)
	}
	if state != "working" && state != "streaming" {
		t.Fatalf("agentState = %q, want resumed work", state)
	}

	releaseOnce.Do(func() { close(release) })
	deadline := time.Now().Add(2 * time.Second)
	for time.Now().Before(deadline) {
		actor.mu.Lock()
		done := actor.currentInference == nil && actor.agentState == "idle"
		actor.mu.Unlock()
		if done {
			return
		}
		time.Sleep(10 * time.Millisecond)
	}
	t.Fatal("resumed inference did not finish")
}

func TestNeoActorImportSpawnsWebLocalExecutorForRestoredPendingInference(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("fake Amp executor script uses /bin/sh")
	}

	enabled := true
	dir := t.TempDir()
	pidDir := filepath.Join(dir, "pids")
	if err := os.MkdirAll(pidDir, 0o700); err != nil {
		t.Fatalf("mkdir pid dir: %v", err)
	}
	t.Cleanup(replaceNeoHeadlessPIDDir(func() string { return pidDir }))

	command := filepath.Join(dir, "amp-sleep")
	if err := os.WriteFile(command, []byte("#!/bin/sh\nsleep 5\n"), 0o700); err != nil {
		t.Fatalf("write executor command: %v", err)
	}
	rt := newNeoRuntime(&config.Config{
		SDKConfig: config.SDKConfig{APIKeys: []string{"local-key"}},
		AmpCode: config.AmpCode{NeoLocalRuntime: config.AmpNeoLocalRuntime{
			Enabled:         &enabled,
			ExecutorCommand: command,
		}},
	})
	threadID := "T-019e6541-06ae-75d7-b10e-d893170fa62d"
	actor := newNeoActor(rt, "actor-restored-pending", "thread-actor", threadID, threadID, neoActorRecord("actor-restored-pending", "thread-actor", threadID), nil)
	t.Cleanup(actor.stopSpawnedExecutors)

	thread := map[string]any{
		"id":        threadID,
		"agentMode": "deep",
		"meta":      map[string]any{"ampcodeConnectorLocalNeo": true},
		"env":       map[string]any{"workingDirectory": dir},
		"messages": []any{
			map[string]any{"messageId": "M-user", "role": "user", "agentMode": "deep", "reasoningEffort": "xhigh", "content": []any{map[string]any{"type": "text", "text": "continue after restart"}}},
			map[string]any{"messageId": "M-cancelled", "role": "assistant", "state": map[string]any{"type": "cancelled"}, "content": []any{map[string]any{"type": "text", "text": "partial"}}},
		},
		"pendingInference": map[string]any{"messageId": "M-cancelled", "agentMode": "deep", "reasoningEffort": "xhigh", "preflightCompactionChecked": true},
	}
	if err := actor.importThreadLocalOnly(thread); err != nil {
		t.Fatalf("import thread: %v", err)
	}

	deadline := time.Now().Add(2 * time.Second)
	for time.Now().Before(deadline) {
		actor.mu.Lock()
		bootstrapExecutorType := actor.bootstrapExecutorType
		pending := actor.pendingInference
		spawned := len(actor.spawnedExecutors)
		actor.mu.Unlock()
		if bootstrapExecutorType == "local-client" && pending != nil && spawned == 1 {
			return
		}
		time.Sleep(10 * time.Millisecond)
	}
	actor.mu.Lock()
	defer actor.mu.Unlock()
	t.Fatalf("restored pending inference did not spawn executor: bootstrap=%q pending=%#v spawned=%d", actor.bootstrapExecutorType, actor.pendingInference, len(actor.spawnedExecutors))
}

func TestNeoActorThreadSnapshotDropsStaleCurrentInference(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})
	actor := newNeoActor(rt, "actor-test", "thread-actor", "T-test", "T-test", neoActorRecord("actor-test", "thread-actor", "T-test"), nil)
	actor.messages = []neoMessage{{ThreadID: "T-test", MessageID: "M-existing", Role: "user", Content: []any{map[string]any{"type": "text", "text": "hello"}}, Seq: 1}}
	actor.currentInference = &neoInferenceInflight{messageID: "M-missing", agentMode: "deep", tools: []string{"shell_command"}}

	snapshot, ok := actor.threadSnapshot()
	if !ok {
		t.Fatal("snapshot failed")
	}
	if snapshot.currentInference != nil {
		t.Fatalf("snapshot currentInference = %#v, want nil", snapshot.currentInference)
	}
	if actor.currentInference != nil {
		t.Fatalf("actor currentInference = %#v, want nil", actor.currentInference)
	}
	if thread := neoCloudThread(snapshot); thread["currentInference"] != nil {
		t.Fatalf("cloud thread retained currentInference: %#v", thread["currentInference"])
	}
}

