func TestNeoRuntimeWebLocalThreadSummaryImportsOnlyExistingLocalSnapshot(t *testing.T) {
	useTempNeoThreadStore(t)
	enabled := true
	rt := newNeoRuntime(&config.Config{AmpCode: config.AmpCode{NeoLocalRuntime: config.AmpNeoLocalRuntime{Enabled: &enabled}}})
	threadID := "T-019f6592-074a-74af-801b-7e9402909565"
	if err := writeNeoLocalThreadSnapshotToDir(neoCloudThreadSnapshot{
		threadID:  threadID,
		seq:       1,
		createdMs: 1778170000000,
		title:     "Past local web thread",
		messages: []neoMessage{{
			ThreadID:  threadID,
			MessageID: "M-local",
			Role:      "user",
			Content:   []any{map[string]any{"type": "text", "text": "resume past local thread"}},
			Seq:       1,
		}},
	}, rt.threadDir); err != nil {
		t.Fatalf("write local thread: %v", err)
	}
	if actor := rt.store.lookupThreadActor(threadID); actor != nil {
		t.Fatal("local actor was loaded before discovery")
	}
	summary := rt.neoWebLocalThreadSummary(threadID)
	if stringValue(summary["id"]) != threadID || stringValue(summary["title"]) != "Past local web thread" {
		t.Fatalf("local thread summary = %#v", summary)
	}
	if actor := rt.store.lookupThreadActor(threadID); actor == nil || !actor.hasLocalThreadState() {
		t.Fatal("local snapshot was not imported during discovery")
	}
	threadData := rt.neoWebLocalThreadData(threadID, "http://127.0.0.1:8317", "local-key")
	thread := mapValue(threadData["thread"])
	if numberFrom(thread["v"]) != 1 || len(arrayValue(thread["messages"])) != 1 {
		t.Fatalf("local thread data history = %#v", thread)
	}
	actor := rt.store.lookupThreadActor(threadID)
	actor.bumpSeqAndRemember(map[string]any{"type": "resume_probe"})
	if !actor.canReplayFrom(1) {
		t.Fatal("local thread data snapshot did not establish replay continuity")
	}

	unknownThreadID := "T-019f6592-074a-74af-801b-7e9402909566"
	if summary := rt.neoWebLocalThreadSummary(unknownThreadID); summary != nil {
		t.Fatalf("unknown thread summary = %#v", summary)
	}
	if actor := rt.store.lookupThreadActor(unknownThreadID); actor != nil {
		t.Fatal("unknown cloud thread created an empty local actor")
	}
}

func TestUploadNeoCloudThreadKeepsSmallPayloadUncompressed(t *testing.T) {
	t.Setenv("XDG_DATA_HOME", t.TempDir())
	var received []byte
	var contentLength int64
	upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if got := r.Header.Get("Content-Encoding"); got != "" {
			t.Errorf("Content-Encoding = %q, want empty", got)
		}
		contentLength = r.ContentLength
		var err error
		received, err = io.ReadAll(r.Body)
		if err != nil {
			t.Errorf("read payload: %v", err)
		}
		writeNeoJSON(w, http.StatusOK, map[string]any{"ok": true})
	}))
	defer upstream.Close()

	serializedBytes, err := uploadNeoCloudThread(neoCloudThreadSnapshot{
		upstreamURL: upstream.URL,
		apiKey:      "secret",
		threadID:    "T-small-upload",
		seq:         1,
		createdMs:   1778170000000,
		title:       "Small upload",
	})
	if err != nil {
		t.Fatalf("uploadNeoCloudThread error: %v", err)
	}
	if contentLength != int64(len(received)) || serializedBytes != int64(len(received)) {
		t.Fatalf("payload bytes = content-length:%d serialized:%d received:%d", contentLength, serializedBytes, len(received))
	}
	var payload map[string]any
	if err := json.Unmarshal(received, &payload); err != nil {
		t.Fatalf("decode payload: %v", err)
	}
	if stringValue(payload["method"]) != "uploadThread" || stringValue(mapValue(mapValue(payload["params"])["thread"])["id"]) != "T-small-upload" {
		t.Fatalf("payload = %#v", payload)
	}
}

func TestUploadNeoCloudThreadUsesAmpInternalClientHeaders(t *testing.T) {
	dataHome := t.TempDir()
	t.Setenv("XDG_DATA_HOME", dataHome)
	deviceDir := filepath.Join(dataHome, "amp")
	if err := os.MkdirAll(deviceDir, 0o700); err != nil {
		t.Fatalf("mkdir device dir: %v", err)
	}
	if err := os.WriteFile(filepath.Join(deviceDir, "device-id.json"), []byte(`{"installationID":"upload-install-123"}`), 0o600); err != nil {
		t.Fatalf("write device id: %v", err)
	}

	threadID := "T-019e65c0-0310-77a8-b233-4b84d9c0612b"
	largeText := strings.Repeat("x", neoCloudGzipBytes)
	var sawRequest bool
	var receivedBytes atomic.Int64
	upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		sawRequest = true
		if r.URL.Path != "/api/internal" || r.URL.RawQuery != "uploadThread" {
			t.Fatalf("request target = %s?%s", r.URL.Path, r.URL.RawQuery)
		}
		if got := r.Header.Get("Authorization"); got != "Bearer secret" {
			t.Fatalf("Authorization = %q", got)
		}
		if got := r.Header.Get("Content-Type"); got != "application/json" {
			t.Fatalf("Content-Type = %q", got)
		}
		if got := r.Header.Get("Content-Encoding"); got != "gzip" {
			t.Fatalf("Content-Encoding = %q", got)
		}
		if got := r.Header.Get("X-Amp-Client-Application"); got != "CLI" {
			t.Fatalf("X-Amp-Client-Application = %q", got)
		}
		if got := r.Header.Get("X-Amp-Client-Type"); got != "cli" {
			t.Fatalf("X-Amp-Client-Type = %q", got)
		}
		if got := r.Header.Get("X-Amp-Client-Version"); got != "test-client-version" {
			t.Fatalf("X-Amp-Client-Version = %q", got)
		}
		if got := r.Header.Get("X-Amp-Installation-ID"); got != "upload-install-123" {
			t.Fatalf("X-Amp-Installation-ID = %q", got)
		}
		if got, want := r.Header.Get("X-Amp-Device-Fingerprint"), neoAmpDeviceFingerprint(); got != want {
			t.Fatalf("X-Amp-Device-Fingerprint = %q, want %q", got, want)
		}
		gz, err := gzip.NewReader(r.Body)
		if err != nil {
			t.Fatalf("open gzip payload: %v", err)
		}
		defer gz.Close()
		body, err := io.ReadAll(gz)
		if err != nil {
			t.Fatalf("read payload: %v", err)
		}
		receivedBytes.Store(int64(len(body)))
		var payload map[string]any
		if err := json.Unmarshal(body, &payload); err != nil {
			t.Fatalf("decode payload: %v", err)
		}
		if payload["method"] != "uploadThread" {
			t.Fatalf("method = %#v", payload["method"])
		}
		params := mapValue(payload["params"])
		if params["createdOnServer"] != false {
			t.Fatalf("createdOnServer = %#v", params["createdOnServer"])
		}
		thread := mapValue(params["thread"])
		if thread["id"] != threadID {
			t.Fatalf("thread id = %#v", thread["id"])
		}
		writeNeoJSON(w, http.StatusOK, map[string]any{"ok": true})
	}))
	defer upstream.Close()

	serializedBytes, err := uploadNeoCloudThread(neoCloudThreadSnapshot{
		upstreamURL:   upstream.URL,
		apiKey:        "secret",
		clientVersion: "test-client-version",
		threadID:      threadID,
		seq:           1,
		createdMs:     1778170000000,
		title:         "Header parity",
		messages: []neoMessage{
			{ThreadID: threadID, MessageID: "M-user", Role: "user", Content: []any{map[string]any{"type": "text", "text": largeText}}, Seq: 1},
		},
	})
	if err != nil {
		t.Fatalf("uploadNeoCloudThread error: %v", err)
	}
	if !sawRequest {
		t.Fatal("upstream did not receive uploadThread request")
	}
	if serializedBytes != receivedBytes.Load() {
		t.Fatalf("serialized bytes = %d, received bytes = %d", serializedBytes, receivedBytes.Load())
	}
}

