func TestNeoRuntimeThreadActorCreationAcceptsUnnamedCustomAgentsAndUsesRequestedModel(t *testing.T) {
	useTempNeoThreadStore(t)
	rt := newNeoRuntime(&config.Config{})
	var modes []string
	for _, name := range []any{nil, "Security Agent (Kimi)"} {
		agent := map[string]any{
			"kind":         "agent-definition",
			"model":        "anthropic/claude-opus-4-7",
			"instructions": "UNNAMED_CUSTOM_AGENT_INSTRUCTIONS",
		}
		if name != nil {
			agent["name"] = name
		}
		response, status := rt.localThreadActorManagementResponse(context.Background(), map[string]any{"agent": agent}, "")
		if status != http.StatusOK {
			t.Fatalf("name=%#v status = %d response=%#v", name, status, response)
		}
		mode := stringValue(response["agentMode"])
		actor := rt.store.ensureThreadActor(stringValue(response["threadId"]))
		actor.mu.Lock()
		request := actor.inferenceRequestLocked(mode, actor.currentReasoningEffort, "")
		actor.mu.Unlock()
		route := selectNeoModelRouteWithConfig(rt, mode, request.Settings)
		if route.Provider != "anthropic" || route.Model != "claude-opus-4-7" {
			t.Fatalf("name=%#v route = %#v", name, route)
		}
		if !strings.Contains(neoSystemPrompt(request, route), "UNNAMED_CUSTOM_AGENT_INSTRUCTIONS") {
			t.Fatalf("name=%#v custom instructions missing", name)
		}
		modes = append(modes, mode)
	}
	if len(modes) != 2 || modes[0] == "" || modes[0] != modes[1] {
		t.Fatalf("custom modes = %#v, want stable identity independent of name", modes)
	}
}

func TestNeoRuntimeCustomAgentToolSelectors(t *testing.T) {
	tests := []struct {
		name     string
		selector any
		want     []string
	}{
		{name: "empty", selector: []any{}, want: []string{}},
		{name: "string", selector: "read_thread", want: []string{"read_thread"}},
		{name: "explicit built-in", selector: []any{"apply_patch"}, want: []string{"apply_patch"}},
		{name: "all", selector: "all", want: []string{"apply_patch", "mcp__git-server__search", "read_thread", "shell_command"}},
		{name: "include", selector: []any{"read_thread", "mcp__*"}, want: []string{"mcp__git-server__search", "read_thread"}},
		{name: "exclude", selector: map[string]any{"include": "all", "exclude": []any{"shell_*", "mcp__*"}}, want: []string{"apply_patch", "read_thread"}},
	}
	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			useTempNeoThreadStore(t)
			rt := newNeoRuntime(&config.Config{})
			response, status := rt.localThreadActorManagementResponse(context.Background(), map[string]any{
				"agent": map[string]any{
					"kind":         "agent-definition",
					"model":        "anthropic/claude-opus-4-7",
					"instructions": "CUSTOM_TOOL_SELECTOR_INSTRUCTIONS",
					"tools":        test.selector,
				},
			}, "")
			if status != http.StatusOK {
				t.Fatalf("status = %d response=%#v", status, response)
			}
			actor := rt.store.ensureThreadActor(stringValue(response["threadId"]))
			actor.mu.Lock()
			actor.tools = map[string]neoToolSpec{
				"apply_patch":             {Name: "apply_patch"},
				"shell_command":           {Name: "shell_command"},
				"read_thread":             {Name: "read_thread"},
				"mcp__git-server__search": {Name: "mcp__git-server__search", Meta: map[string]any{"source": map[string]any{"plugin": "test"}}},
			}
			actor.toolOrder = []string{"shell_command", "read_thread", "mcp__git-server__search"}
			request := actor.inferenceRequestLocked(actor.currentAgentMode, actor.currentReasoningEffort, "")
			actor.mu.Unlock()
			got := make([]string, 0, len(request.Tools))
			for _, tool := range request.Tools {
				got = append(got, tool.Name)
			}
			if !reflect.DeepEqual(got, test.want) {
				t.Fatalf("tools = %#v, want %#v", got, test.want)
			}
		})
	}
}

func TestNeoActorCustomAgentModeClientMessages(t *testing.T) {
	useTempNeoThreadStore(t)
	rt := newNeoRuntime(&config.Config{})
	actor := newNeoActor(rt, "actor-custom-client", "thread-actor", "T-custom-client", "T-custom-client", neoActorRecord("actor-custom-client", "thread-actor", "T-custom-client"), nil)
	customMode := "custom-0123456789abcdef"
	actor.settings = map[string]any{
		"agentMode":                       customMode,
		"reasoning.effort":                "high",
		neoCustomAgentModeSetting:         customMode,
		neoCustomAgentModelSetting:        "anthropic/claude-opus-4-7",
		neoCustomAgentInstructionsSetting: "CUSTOM_CLIENT_INSTRUCTIONS",
		neoCustomAgentConfigKeySetting:    "custom-client",
	}
	actor.currentAgentMode = customMode
	actor.currentReasoningEffort = "high"

	actor.updateReasoningEffortFromBinary(map[string]any{"effort": "low"})
	actor.mu.Lock()
	if actor.currentReasoningEffort != "low" || actor.settings["reasoning.effort"] != "low" {
		actor.mu.Unlock()
		t.Fatalf("custom reasoning effort = current:%q settings:%#v", actor.currentReasoningEffort, actor.settings)
	}
	actor.mu.Unlock()

	actor.receiveUserMessage(nil, map[string]any{
		"messageId":       "M-0000000000000000000001",
		"content":         []any{map[string]any{"type": "text", "text": "custom append"}},
		"agentMode":       customMode,
		"reasoningEffort": "low",
	})
	actor.receiveUserMessage(nil, map[string]any{
		"messageId": "M-0000000000000000000002",
		"content":   []any{map[string]any{"type": "text", "text": "wrong custom append"}},
		"agentMode": "custom-fedcba9876543210",
	})
	actor.mu.Lock()
	if len(actor.queue) != 1 || actor.queue[0].AgentMode != customMode {
		actor.mu.Unlock()
		t.Fatalf("custom client queue = %#v", actor.queue)
	}
	actor.queue = nil
	actor.messages = []neoMessage{{
		ThreadID:        "T-custom-client",
		MessageID:       "M-0000000000000000000003",
		Role:            "user",
		Content:         []any{map[string]any{"type": "text", "text": "before edit"}},
		AgentMode:       customMode,
		ReasoningEffort: "low",
		Seq:             1,
	}}
	actor.seq = 2
	actor.rebuildHistoryLocked()
	actor.settings["reasoning.effort"] = "high"
	actor.currentReasoningEffort = "high"
	actor.meta["agentMode"] = customMode
	actor.meta["reasoningEffort"] = "high"
	actor.meta["pluginName"] = "custom-client"
	actor.mu.Unlock()

	actor.editMessage(nil, map[string]any{
		"messageId":       "M-0000000000000000000003",
		"editId":          "E-0000000000000000000001",
		"content":         []any{map[string]any{"type": "text", "text": "after edit"}},
		"agentMode":       customMode,
		"reasoningEffort": "low",
	})
	actor.mu.Lock()
	defer actor.mu.Unlock()
	if len(actor.messages) != 1 || textFromBlocks(actor.messages[0].Content) != "after edit" || actor.messages[0].AgentMode != customMode || actor.messages[0].ReasoningEffort != "low" {
		t.Fatalf("custom client edit = %#v", actor.messages)
	}
	if actor.currentReasoningEffort != "low" || actor.settings["reasoning.effort"] != "low" || actor.meta["reasoningEffort"] != "low" || actor.meta["pluginName"] != "custom-client" {
		t.Fatalf("custom edit effort state = current:%q settings:%#v meta:%#v", actor.currentReasoningEffort, actor.settings, actor.meta)
	}
	if actor.pendingInference == nil || actor.pendingInference.agentMode != customMode || actor.pendingInference.reasoningEffort != "low" {
		t.Fatalf("custom edit pending inference = %#v", actor.pendingInference)
	}
}

func TestNeoActorStoreQueuedUserMessagePreservesCustomModeEffort(t *testing.T) {
	useTempNeoThreadStore(t)
	rt := newNeoRuntime(&config.Config{})
	actor := newNeoActor(rt, "actor-custom-queued", "thread-actor", "T-custom-queued", "T-custom-queued", neoActorRecord("actor-custom-queued", "thread-actor", "T-custom-queued"), nil)
	customMode := "custom-0123456789abcdef"
	actor.settings = map[string]any{
		"agentMode":                       customMode,
		"reasoning.effort":                "high",
		neoCustomAgentModeSetting:         customMode,
		neoCustomAgentModelSetting:        "anthropic/claude-opus-4-7",
		neoCustomAgentInstructionsSetting: "CUSTOM_QUEUED_INSTRUCTIONS",
	}
	actor.currentAgentMode = customMode
	actor.currentReasoningEffort = "high"

	actor.mu.Lock()
	message, mode, effort := actor.storeQueuedUserMessageLocked(neoQueuedMessage{
		MessageID:       "M-0000000000000000000001",
		Content:         []any{map[string]any{"type": "text", "text": "custom queued"}},
		AgentMode:       customMode,
		ReasoningEffort: "low",
	}, false)
	actor.mu.Unlock()
	if mode != customMode || effort != "low" || message.AgentMode != customMode || message.ReasoningEffort != "low" {
		t.Fatalf("stored custom message mode=%q effort=%q message=%#v", mode, effort, message)
	}
}

func TestNeoRuntimeRejectsInvalidCustomAgentBeforeCreatingActor(t *testing.T) {
	useTempNeoThreadStore(t)
	threadID := "T-019f7018-3a48-75c4-a21e-3db2bac16693"
	requests := 0
	upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		requests++
		writeNeoJSON(w, http.StatusCreated, map[string]any{"threadId": threadID})
	}))
	t.Cleanup(upstream.Close)
	rt := newNeoRuntime(&config.Config{AmpCode: config.AmpCode{UpstreamURL: upstream.URL, UpstreamAPIKey: "secret"}})

	for name, selector := range map[string]any{
		"empty object":   map[string]any{},
		"unknown member": map[string]any{"includes": []any{"read_thread"}},
	} {
		t.Run(name, func(t *testing.T) {
			response, status := rt.localThreadActorManagementResponse(context.Background(), map[string]any{
				"threadId":   threadID,
				"threadMeta": map[string]any{"cliProxyAPIWebLocalShell": true},
				"agent": map[string]any{
					"kind":         "agent-definition",
					"model":        "anthropic/claude-opus-4-7",
					"instructions": "CUSTOM_INVALID_SELECTOR",
					"tools":        selector,
				},
			}, "")
			if status != http.StatusBadRequest || stringValue(response["error"]) != "invalid_custom_agent" {
				t.Fatalf("status = %d response=%#v", status, response)
			}
			if requests != 0 {
				t.Fatalf("invalid custom agent made %d upstream requests", requests)
			}
			if actor := rt.store.lookupThreadActor(threadID); actor != nil {
				t.Fatal("invalid custom agent created a local actor")
			}
		})
	}
}

func TestNeoRuntimeThreadActorCredentialsDoNotInventUpstreamRoutingFields(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})
	response, status := rt.localThreadActorManagementResponse(context.Background(), map[string]any{
		"agentMode":        "deep",
		"usesThreadActors": true,
	}, "")
	if status != http.StatusOK {
		t.Fatalf("status = %d response=%#v", status, response)
	}
	for _, key := range []string{"threadId", "wsToken", "ownerUserId", "threadVersion"} {
		if response[key] == nil || response[key] == "" {
			t.Fatalf("missing binary-required credential field %q in %#v", key, response)
		}
	}
	for _, key := range []string{"poolName", "capability", "userId"} {
		if _, exists := response[key]; exists {
			t.Fatalf("local thread actor credentials should not include %s: %#v", key, response)
		}
	}
}

func TestNeoRuntimeThreadImportVersionAllocatesFutureSeq(t *testing.T) {
	dir := t.TempDir()
	oldStoreDir := neoAmpDataDir
	neoAmpDataDir = func() string { return dir }
	t.Cleanup(func() { neoAmpDataDir = oldStoreDir })

	rt := newNeoRuntime(&config.Config{})
	actor := rt.store.ensureThreadActor("T-import-version")
	err := actor.importThreadLocalOnly(map[string]any{
		"id":        "T-import-version",
		"v":         7,
		"agentMode": "deep",
		"messages": []any{
			map[string]any{"role": "user", "messageId": 0, "content": []any{map[string]any{"type": "text", "text": "carry this"}}},
			map[string]any{"role": "assistant", "messageId": 1, "content": []any{map[string]any{"type": "text", "text": "done"}}, "state": map[string]any{"type": "complete", "stopReason": "end_turn"}},
		},
	})
	if err != nil {
		t.Fatalf("importThreadLocalOnly error: %v", err)
	}

	actor.mu.Lock()
	if actor.seq != 8 {
		t.Fatalf("next seq after import = %d, want 8", actor.seq)
	}
	actor.mu.Unlock()

	response, status := rt.localThreadActorManagementResponse(context.Background(), map[string]any{
		"threadId":         "T-import-version",
		"usesThreadActors": true,
	}, "T-import-version")
	if status != http.StatusCreated {
		t.Fatalf("thread actor status = %d, want %d; response=%#v", status, http.StatusCreated, response)
	}
	if got := numberFrom(response["threadVersion"]); got != 7 {
		t.Fatalf("thread actor version = %d, want imported high water 7", got)
	}

	actor.handle(map[string]any{"type": "message_added", "message": map[string]any{
		"role":      "assistant",
		"messageId": "M-next",
		"content":   []any{map[string]any{"type": "text", "text": "new"}},
		"state":     map[string]any{"type": "complete", "stopReason": "end_turn"},
	}})

	actor.mu.Lock()
	nextSeq := actor.seq
	seq := 0
	for _, message := range actor.messages {
		if message.MessageID == "M-next" {
			seq = message.Seq
			break
		}
	}
	actor.mu.Unlock()
	if seq != 8 || nextSeq != 9 {
		t.Fatalf("new message seq/next = %d/%d, want 8/9", seq, nextSeq)
	}
	snapshot, ok := actor.threadSnapshot()
	if !ok || snapshot.seq != 8 {
		t.Fatalf("snapshot seq = %#v/%v, want 8", snapshot, ok)
	}
}

func TestNeoRuntimeProtocolDeltaNormalizesLikeBinary(t *testing.T) {
	dir := t.TempDir()
	oldStoreDir := neoAmpDataDir
	neoAmpDataDir = func() string { return dir }
	t.Cleanup(func() { neoAmpDataDir = oldStoreDir })

	rt := newNeoRuntime(&config.Config{})
	actor := rt.store.ensureThreadActor("T-protocol-delta-normalize")

	actor.handle(map[string]any{
		"type":      "delta",
		"messageId": "M-ignored",
		"role":      "system",
		"blocks":    []any{map[string]any{"type": "text", "text": "ignored"}},
	})
	actor.mu.Lock()
	if len(actor.messages) != 0 || len(actor.replayEvents) != 0 {
		actor.mu.Unlock()
		t.Fatalf("invalid role was not dropped: messages=%#v replay=%#v", actor.messages, actor.replayEvents)
	}
	actor.mu.Unlock()

	actor.handle(map[string]any{
		"type":       "delta",
		"messageId":  "M-assistant",
		"role":       "assistant",
		"state":      "not-a-state",
		"blockIndex": "bad",
		"blocks": []any{
			map[string]any{"type": "unknown"},
			map[string]any{"type": "text", "text": "hello", "blockState": "bad"},
		},
	})
	actor.mu.Lock()
	if len(actor.messages) != 1 {
		actor.mu.Unlock()
		t.Fatalf("messages = %#v, want assistant message", actor.messages)
	}
	assistant := actor.messages[0]
	replay := actor.replayEvents[len(actor.replayEvents)-1].Payload
	actor.mu.Unlock()
	if got := stringValue(mapValue(assistant.State)["type"]); got != "streaming" {
		t.Fatalf("assistant state = %q, want streaming", got)
	}
	if len(assistant.Content) != 2 {
		t.Fatalf("assistant content = %#v, want 2 blocks", assistant.Content)
	}
	if hidden := mapValue(assistant.Content[0]); stringValue(hidden["type"]) != "text" || stringValue(hidden["text"]) != "" || !boolValue(hidden["hidden"]) {
		t.Fatalf("hidden replacement block = %#v", hidden)
	}
	if text := mapValue(assistant.Content[1]); stringValue(text["text"]) != "hello" {
		t.Fatalf("text block = %#v", text)
	} else if _, exists := text["blockState"]; exists {
		t.Fatalf("invalid blockState was preserved: %#v", text)
	}
	if got := stringValue(replay["state"]); got != "generating" {
		t.Fatalf("replay state = %q, want generating", got)
	}
	if got := numberFrom(replay["blockIndex"]); got != 0 {
		t.Fatalf("replay blockIndex = %d, want 0", got)
	}

	actor.handle(map[string]any{
		"type":       "delta",
		"messageId":  "M-user",
		"role":       "user",
		"state":      "generating",
		"blockIndex": 3,
		"blocks": []any{
			map[string]any{"type": "tool_use", "id": "TU-invalid"},
			map[string]any{"type": "text", "text": "user text"},
		},
	})
	actor.mu.Lock()
	user := actor.messages[1]
	userReplay := actor.replayEvents[len(actor.replayEvents)-1].Payload
	actor.mu.Unlock()
	if got := stringValue(userReplay["state"]); got != "complete" {
		t.Fatalf("user replay state = %q, want complete", got)
	}
	if _, exists := userReplay["blockIndex"]; exists {
		t.Fatalf("user replay kept blockIndex: %#v", userReplay)
	}
	if len(user.Content) != 1 || stringValue(mapValue(user.Content[0])["text"]) != "user text" {
		t.Fatalf("user content = %#v, want filtered text", user.Content)
	}
	waitForNeoActorSyncIdle(t, actor)
}

func TestNeoRuntimeProtocolMessagesNormalizeContentLikeBinary(t *testing.T) {
	dir := t.TempDir()
	oldStoreDir := neoAmpDataDir
	neoAmpDataDir = func() string { return dir }
	t.Cleanup(func() { neoAmpDataDir = oldStoreDir })

	rt := newNeoRuntime(&config.Config{})
	actor := rt.store.ensureThreadActor("T-protocol-message-normalize")

	actor.handle(map[string]any{"type": "message_added", "message": map[string]any{
		"messageId": "M-assistant",
		"role":      "assistant",
		"content": []any{
			map[string]any{"type": "text", "text": "kept"},
			map[string]any{"type": "thinking", "thinking": "missing signature"},
		},
		"state": map[string]any{"type": "streaming"},
	}})
	actor.mu.Lock()
	assistant := actor.messages[0]
	actor.mu.Unlock()
	if len(assistant.Content) != 1 || stringValue(mapValue(assistant.Content[0])["text"]) != "kept" {
		t.Fatalf("assistant content = %#v, want only valid text", assistant.Content)
	}
	if len(assistant.State) != 0 {
		t.Fatalf("assistant invalid message state was preserved: %#v", assistant.State)
	}

	actor.handle(map[string]any{"type": "message_added", "message": map[string]any{
		"messageId": "M-user",
		"role":      "user",
		"content": []any{
			map[string]any{
				"type":       "image",
				"name":       "shot.png",
				"media_type": "image/png",
				"source":     map[string]any{"type": "base64", "media_type": "image/png", "data": "abcd"},
			},
		},
	}})
	actor.mu.Lock()
	user := actor.messages[1]
	actor.mu.Unlock()
	image := mapValue(user.Content[0])
	source := mapValue(image["source"])
	if got := stringValue(source["mediaType"]); got != "image/png" {
		t.Fatalf("image source mediaType = %q, want image/png; block=%#v", got, image)
	}
	if got := stringValue(image["sourcePath"]); got != "shot.png" {
		t.Fatalf("image sourcePath = %q, want shot.png", got)
	}

	actor.handle(map[string]any{"type": "message_added", "message": map[string]any{
		"messageId": "M-user-invalid-image",
		"role":      "user",
		"content": []any{
			map[string]any{"type": "text", "text": "kept"},
			map[string]any{"type": "image", "source": map[string]any{"type": "base64", "mediaType": "image/svg+xml", "data": "abcd"}},
			map[string]any{"type": "image", "source": map[string]any{"type": "base64", "data": "abcd"}},
			map[string]any{"type": "image", "source": map[string]any{"type": "base64", "mediaType": "image/png", "data": "abcd"}},
			map[string]any{"type": "image", "source": map[string]any{"type": "unknown"}},
		},
	}})
	actor.mu.Lock()
	invalidUser := actor.messages[2]
	actor.mu.Unlock()
	if len(invalidUser.Content) != 2 || stringValue(mapValue(invalidUser.Content[0])["text"]) != "kept" {
		t.Fatalf("invalid image blocks were not filtered like binary schema: %#v", invalidUser.Content)
	}
	keptImage := mapValue(invalidUser.Content[1])
	keptSource := mapValue(keptImage["source"])
	if stringValue(keptSource["mediaType"]) != "image/png" || stringValue(keptSource["data"]) != "abcd" {
		t.Fatalf("valid image with optional source_path was not kept: %#v", keptImage)
	}
	if _, exists := keptImage["sourcePath"]; exists {
		t.Fatalf("binary source_path is optional but was synthesized: %#v", keptImage)
	}

	actor.handle(map[string]any{"type": "message_added", "message": map[string]any{
		"messageId": "M-info",
		"role":      "info",
		"content": []any{
			map[string]any{"type": "text", "text": "drop"},
			map[string]any{"type": "manual_bash_invocation", "args": map[string]any{"cmd": "pwd"}, "toolRun": map[string]any{"status": "success"}},
		},
	}})
	actor.mu.Lock()
	info := actor.messages[3]
	beforeInvalid := len(actor.messages)
	actor.mu.Unlock()
	if len(info.Content) != 1 || stringValue(mapValue(info.Content[0])["type"]) != "manual_bash_invocation" {
		t.Fatalf("info content = %#v, want only manual bash invocation", info.Content)
	}

	actor.handle(map[string]any{"type": "message_added", "message": map[string]any{
		"messageId": "M-invalid",
		"role":      "assistant",
	}})
	actor.mu.Lock()
	afterInvalid := len(actor.messages)
	actor.mu.Unlock()
	if afterInvalid != beforeInvalid {
		t.Fatalf("invalid message without content was stored: before=%d after=%d", beforeInvalid, afterInvalid)
	}
	waitForNeoActorSyncIdle(t, actor)
}

func TestNeoRuntimeThreadImportDerivesModeFromMessages(t *testing.T) {
	rt := newNeoRuntime(&config.Config{})
	actor := rt.store.ensureThreadActor("T-import-mode")
	actor.pendingInference = &neoInferenceInflight{agentMode: "smart", reasoningEffort: "high"}

	thread := map[string]any{
		"id": "T-import-mode",
		"messages": []any{
			map[string]any{"role": "user", "messageId": "M-user", "agentMode": "deep", "reasoningEffort": "xhigh", "content": []any{map[string]any{"type": "text", "text": "keep deep"}}},
		},
	}
	if err := actor.importThreadLocalOnly(thread); err != nil {
		t.Fatalf("importThreadLocalOnly error: %v", err)
	}

	actor.mu.Lock()
	defer actor.mu.Unlock()
	if actor.currentAgentMode != "deep" || actor.settings["agentMode"] != "deep" || actor.currentReasoningEffort != "xhigh" || actor.settings["reasoning.effort"] != "xhigh" {
		t.Fatalf("imported mode/effort = current:%q/%q settings:%#v", actor.currentAgentMode, actor.currentReasoningEffort, actor.settings)
	}
	if actor.pendingInference != nil {
		t.Fatalf("pending inference after import = %#v, want nil", actor.pendingInference)
	}
}

